"use client";

import type { ComponentProps, CSSProperties } from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BADGE_SIZE, useBarSize } from "./barSize";

/**
 * src/components/badge.tsx — a plain, stock shadcn Badge. Not vendored
 * anywhere else in this repo (checked apps/docs and packages/inspector —
 * absent from both), so this is written fresh rather than ported; it's a
 * small, extremely standard shadcn primitive with nothing repo-specific to
 * preserve. No `asChild`/Slot support — this app has no reason yet to
 * render a Badge as a link, and skipping it avoids a new dependency.
 *
 * WHY `size` was added here (stock shadcn's Badge has none): the Bar size
 * cascade (barSize.tsx) needs somewhere to land on Badge, and there was no
 * existing scale to hook into. Four rungs, matching `Bar`'s own directly.
 *
 * WHY `shape` defaults to `"rounded"` rather than flipping to pill
 * (docs/FEEDBACK-2026-09-17b-PLAN.md A-1, Zach: "show some badges with a
 * more pill shape"): he asked to *see* the pill option, not replace the
 * landed look — every existing caller (in particular `Bar`'s title badge,
 * which reads as a chip on purpose) must render unchanged. `rounded-full`
 * is opt-in via `shape="pill"`, not the new floor.
 */
const badgeVariants = cva(
  "relative inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border font-medium whitespace-nowrap transition-[color,box-shadow] [&>svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground",
        secondary: "border-transparent bg-secondary text-secondary-foreground",
        destructive: "border-transparent bg-destructive text-white dark:bg-destructive/60",
        // docs/INVALID-STATES-PLAN.md §5's Badge row: "amber bg, dark
        // text" — one cva row, no new component. `--bbox-warning` (ported
        // in src/globals.css) stays light enough in BOTH themes that black
        // text keeps its contrast; `destructive` above needs the opposite
        // (white-on-dark-red) for the same reason.
        warning: "border-transparent bg-[var(--bbox-warning)] text-black",
        // The one variant with a REAL (non-transparent) border, so it's
        // the one that gets `--bbox-skin-line-override`: default/secondary/
        // destructive are already `border-transparent` and need nothing —
        // suppressing an already-invisible border would be a no-op. See
        // block.tsx's own line-override note on why the colour a skin
        // suppresses has to be the one the STATE cascade already owns.
        outline: "border-[color:var(--bbox-skin-line-override,currentColor)] text-foreground",
      },
      size: {
        sm: "gap-0.5 px-1.5 py-0 text-[0.65rem] [&>svg]:size-2.5",
        md: "gap-1 px-2 py-0.5 text-xs [&>svg]:size-3",
        lg: "gap-1 px-2.5 py-1 text-sm [&>svg]:size-3.5",
        xl: "gap-1.5 px-3 py-1 text-base [&>svg]:size-4",
      },
      // WHY radius moved OFF these two classes and onto inline style
      // (see the component body): `rounded-md`/`rounded-full` bake a
      // fixed radius no skin token can reach. The literal each falls back
      // to below is unchanged from before this port — `rounded-md` here
      // resolves to `var(--radius-md)` = 8px on this app's `--radius:
      // 0.625rem` base, captured live off `components-text-marks-badge--variants` before
      // the edit.
      shape: {
        rounded: "",
        pill: "",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
      shape: "rounded",
    },
  },
);

export interface BadgeProps extends ComponentProps<"span">, VariantProps<typeof badgeVariants> {}

export function Badge({ className, variant, size, shape, style, ...props }: BadgeProps) {
  // Explicit `size` wins; the ambient Bar cascade is only the fallback when
  // `size` itself is omitted, `"md"` (cva's own default) is the floor when
  // there is no Bar ancestor either.
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BADGE_SIZE[barSize]) ?? "md";
  const resolvedShape = shape ?? "rounded";
  return (
    <span
      data-slot="badge"
      data-size={resolvedSize}
      data-shape={resolvedShape}
      // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M7. The edge has
      // no props, so its default seed is geometry-derived
      // (`${width}x${height}`) — a different wobble PATTERN than this
      // component's own semantic seed, `badge:${resolvedSize}:${resolvedShape}`
      // (same character and amplitude either way, just a different jitter
      // sequence). Publishing it closes that gap: `sketchAtEdge.ts`'s
      // `seedForBox` reads this attribute first.
      data-bbox-seed={`badge:${resolvedSize}:${resolvedShape}`}
      className={cn(badgeVariants({ variant, size: resolvedSize, shape: resolvedShape }), className)}
      style={{
        borderRadius:
          resolvedShape === "pill"
            ? "var(--bbox-skin-radius-pill, 9999px)"
            : "var(--bbox-skin-radius, var(--radius-md))",
        // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M6.
        // `currentColor` IS this variant's resolved line colour — every
        // variant above sets its own `text-*` class, and a real CSS border
        // (the `outline` variant) is already drawn in `currentColor`. A
        // boundary twin is appended as a CHILD of this span, so it inherits
        // the same `color` and lands on the same value without this
        // component importing the skin or hardcoding a token.
        ...({ "--bbox-ink-state": "currentColor" } as CSSProperties),
        ...style,
      }}
      {...props}
    >
      {props.children}
    </span>
  );
}

export { badgeVariants };

import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";
import { BarSizeProvider } from "./barSize";

/**
 * Bar — a horizontal strip with three slots (left · center · right).
 * Structure is unchanged from the reset: no appearance cascade, no
 * tone/state, just the three slots. What changed in the shadcn/Tailwind
 * migration is HOW it's painted — Tailwind utilities against the shadcn CSS
 * variables in src/globals.css instead of raw `style={{...}}` colors,
 * borrowing the visual vocabulary (not the props) of
 * packages/bbox-ui/src/bar.tsx.
 *
 * WHY the grid template is COMPUTED, not a fixed `1fr auto 1fr` (Zach: "if
 * the center slot is empty or so, then things in the other slots should
 * just continue to expand width wise, and not truncate. Unless you
 * specifically set a width limit"): `1fr auto 1fr` forces the left/right
 * tracks to stay EQUAL width even when one of them (or center) is empty —
 * that symmetry is exactly what real centering needs, but it also means an
 * empty center/right still claims (and wastes) half the bar's width, and a
 * long `left` label truncates against that artificial half-width ceiling
 * with the other half sitting empty. Measured live: a previous lane's own
 * `AllSizes` cascade cluster had already been moved from `left` to `center`
 * and its swatch widened 420→520px specifically to dodge this — a symptom
 * fix, not a cause fix, and reverted below now that the cause is fixed.
 * `barGridTemplateColumns` (below) keeps `1fr auto 1fr`'s symmetric flanks
 * ONLY when `center` actually holds content (centering is structurally
 * impossible without equal flanks, filled or not); otherwise the unused
 * slot's track collapses to `0` and `left`'s own track becomes the single
 * `1fr` that absorbs everything center/right aren't using — so it only
 * truncates once the BAR ITSELF is out of room, never before. A caller that
 * wants a truncation limit narrower than "however wide the bar naturally
 * is" sets one explicitly by wrapping its own content in a `width`-bounded
 * box — see `Bar.stories.tsx`'s `Widths` gallery — rather than `Bar`
 * growing a new prop for it.
 *
 * WHY no `rounded-lg`/`border`/`bg-card` here: a Bar is a layout strip, not
 * a card — the same way `Flex` paints nothing of its own. Zach: "I don't
 * like how the bars have these borders. they should fill the block footer
 * and headers edge to edge... the only lines are the dividers." A Bar
 * filling `Block`'s header/footer must read as flush with it, not as a
 * pill floating inside it — `Block`'s own `border-b`/`border-t` supply the
 * only lines. A standalone Bar story that wants to show the strip's own
 * extent adds a wrapper (e.g. a dashed box) at the STORY level instead.
 *
 * WHY `size` is also published via `BarSizeProvider`: Zach's size-cascade
 * ask — a Bar's contents should size themselves off the Bar's own `size`
 * rather than each getting hand-tuned. See `barSize.tsx` for the mapping
 * from these four rungs onto each consumer's own scale.
 */
function barGridTemplateColumns(hasCenter: boolean, hasRight: boolean): string {
  if (hasCenter) return "1fr auto 1fr";
  if (hasRight) return "1fr 0 auto";
  return "1fr 0 0";
}

export const BAR_SIZES = ["sm", "md", "lg", "xl"] as const;
export type BarSize = (typeof BAR_SIZES)[number];

/** Bar height per rung, px. */
export const BAR_HEIGHT: Record<BarSize, number> = { sm: 28, md: 36, lg: 48, xl: 60 };

export interface BarProps {
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
  size?: BarSize;
  style?: CSSProperties;
}

// WHY `overflow-clip` + a 4px `overflow-clip-margin` instead of plain
// `overflow-hidden`: a focusable control flush against a cell's edge (a
// left-slot FoldingChevron, a right-slot Toggle/Button) paints its
// focus-visible ring OUTSIDE its own border box — `hidden` clips that ink
// the instant it crosses the cell boundary, which is the actual cause of
// the bug Zach reported ("chevron has a box cut off on its left") and,
// measured live, hits any focusable control sitting flush at a cell edge,
// not just the chevron. `overflow-clip-margin` is the CSS-spec-native fix:
// it only relaxes where PAINT (ink like a box-shadow ring or an outline) is
// allowed to bleed past the clip box, layout overflow — the thing this
// class exists to contain, e.g. EditableText's own `minWidth:0`/ellipsis
// truncation still clips flush at (edge + 4px). 4px covers both the
// shadcn ring-3 box-shadow (3px spread, 0 offset) and the browser's native
// default outline that a bare-button control like FoldingChevron falls
// back to. Only takes effect on `overflow: clip` (not `hidden`), which is
// otherwise behaviourally identical for this cell's purposes — no scroll
// either way.
const cellClass = "flex min-w-0 items-center overflow-clip [overflow-clip-margin:4px]";

export function Bar({ left, center, right, size = "md", style }: BarProps) {
  return (
    <BarSizeProvider size={size}>
      <div
        data-slot="bar"
        data-size={size}
        // WHY `group`: a plain Tailwind marker class, paints nothing on its
        // own — it exists so a `FoldingChevron reveal="hover"` inside this
        // Bar can key its `group-hover`/`group-focus-within` reveal off the
        // Bar itself ("the surrounding region... the Bar/header it lives
        // in", not the 24px button). Harmless for every Bar that has no
        // such child.
        className={cn("group grid w-full items-center gap-2 px-3 text-sm text-card-foreground")}
        style={{
          gridTemplateColumns: barGridTemplateColumns(center !== undefined, right !== undefined),
          height: BAR_HEIGHT[size],
          ...style,
        }}
      >
        <div data-slot="bar-left" className={cn(cellClass, "justify-start")}>
          {left}
        </div>
        <div data-slot="bar-center" className={cn(cellClass, "justify-center")}>
          {center}
        </div>
        <div data-slot="bar-right" className={cn(cellClass, "justify-end")}>
          {right}
        </div>
      </div>
    </BarSizeProvider>
  );
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

import type { BarSize } from "./bar";
import type { EditableTextSize } from "./editableText.layout";
import type { GlyphSize } from "./glyph.layout";

/**
 * src/components/barSize.tsx — the size CASCADE from `Bar` down to its own
 * contents. Zach: "various things inside of the bar will size themselves
 * correctly... with a 'large bar' vs small bar you don't need to hand tune
 * each element inside." A React context, mirroring `glyph.tsx`'s own
 * resolver-context pattern (provider + `use*` hook), not a new prop
 * threaded through every layer in between — `Bar` already owns a `size`
 * prop (bar.tsx); this only makes that value reach descendants.
 *
 * The mapping from Bar's four rungs (sm/md/lg/xl) onto each consumer's OWN
 * size scale lives HERE, in one place, rather than scattered per component.
 * `Glyph`/`EditableText` already share Bar's exact four-rung ladder, so
 * their mapping is the identity — still spelled out below so all five
 * mappings are visible in one lookup. `Badge`/`Button`/`Toggle` each carry
 * a differently-shaped scale of their own.
 *
 * An explicit size prop on any child ALWAYS wins — every consumer only
 * calls into this context as the fallback when its own prop is
 * `undefined`, same "explicit beats derived" rule `glyphFootprint` already
 * applies to its own size/sizePreset pair.
 */

const BarSizeContext = createContext<BarSize | undefined>(undefined);

/** Mounted by `Bar` itself (bar.tsx) — not meant to be reached for by callers. */
export function BarSizeProvider({ size, children }: { size: BarSize; children?: ReactNode }) {
  return <BarSizeContext.Provider value={size}>{children}</BarSizeContext.Provider>;
}

/** `undefined` outside any `Bar` — "not inside a cascade," not an error;
 *  same shape as `useGlyphResolver`'s "no provider mounted" case. */
export function useBarSize(): BarSize | undefined {
  return useContext(BarSizeContext);
}

/** Glyph's own ladder (glyph.layout.ts's `GLYPH_SIZES`) is identical to
 *  Bar's four rungs, so the cascade is the identity. */
export const BAR_SIZE_TO_GLYPH_PRESET: Record<BarSize, GlyphSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** EditableText's own ladder (editableText.layout.ts's `EDITABLE_TEXT_SIZES`)
 *  is the same four-rung ladder too — see that file's own comment on why
 *  Glyph/EditableText/Port each keep an independent ladder rather than
 *  sharing one, even though the VALUES line up. */
export const BAR_SIZE_TO_EDITABLE_TEXT_SIZE: Record<BarSize, EditableTextSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Badge has no size scale of its own yet (badge.tsx was a plain stock
 *  shadcn Badge, one size only) — this cascade is what gives it one,
 *  matching Bar's own four rungs directly. */
export type BadgeSize = "sm" | "md" | "lg" | "xl";
export const BAR_SIZE_TO_BADGE_SIZE: Record<BarSize, BadgeSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Button and Toggle each already ship a THREE-rung size scale
 *  (sm/default/lg — no "xl"), so Bar's `xl` clamps down to their largest
 *  rung rather than this cascade inventing a fourth one they don't have. */
export type ButtonToggleSize = "sm" | "default" | "lg";
export const BAR_SIZE_TO_BUTTON_SIZE: Record<BarSize, ButtonToggleSize> = {
  sm: "sm",
  md: "default",
  lg: "lg",
  xl: "lg",
};
export const BAR_SIZE_TO_TOGGLE_SIZE: Record<BarSize, ButtonToggleSize> = BAR_SIZE_TO_BUTTON_SIZE;

// src/components/blockDescription.tsx — the sentence under a block's title,
// and the one boolean that decides whether it is painted at all.
//
// PORTED, not designed: packages/bbox-ui is the frozen v1 lineage and it
// already settled this feature's shape twice over —
//
//   - `src/block.fields.ts:120-124` — `{ id: "description", label:
//     "Description", kind: "toggle", defaultValue: true }`. Visibility is a
//     GOVERNED FIELD with a default of ON, not a prop someone remembers to
//     pass, which is why `showDescription` below defaults to `true`.
//   - `src/block.tsx:367-380` — `BlockDescription`: a `<p>` stamped
//     `data-slot="block-description"`, `text-muted-foreground`, an explicit
//     `fontSize`, caller `style` merged last.
//   - `src/blockFace.tsx:437-454` — WHERE it paints and WHEN: immediately
//     after the header, in BOTH header modes, and only when the resolved
//     boolean AND a non-empty string are both present
//     (`resolved.description && data.description`).
//
// This file restates those three facts for the trunk. `packages/bbox-ui` is
// not edited to match (ARCHITECTURE.md: "Never edit `packages/bbox-ui` to
// chase a trunk change").
import type { ComponentProps } from "react";

import { cn } from "../lib/utils";

/**
 * The description's own type size, px.
 *
 * WHY this is 12 and the donor's `META_FONT_PX` is 18: the donor's number is
 * calibrated to its Simple View box, which `layout.ts` fixes at 384 × 258.
 * The trunk's `Block` defaults to 320 wide and the whiteboard's own `ss-block`
 * defaults to 160 (`BlockShapeUtil.getDefaultProps`), where an 18px sentence
 * is wider than the card it is describing. 12 is the trunk's own meta step —
 * one below `Block`'s root `text-sm` (14) — so the description reads as
 * subordinate to the title at every size the trunk actually ships.
 *
 * Exported because a spatial claim about this element has to be measured
 * against the component's own constant rather than a number retyped in a
 * test (`BlockDescription.stories.tsx` asserts exactly that).
 */
export const BLOCK_DESCRIPTION_FONT_PX = 12;

/**
 * The description's inset, px — horizontally the SAME 12 as `Block`'s own
 * header/footer `px-3`, so the sentence's left edge lines up with the title
 * above it instead of sitting in its own gutter. Vertically tighter (`py-1`)
 * because it is a continuation of the header, not a third region.
 */
export const BLOCK_DESCRIPTION_PADDING_X_PX = 12;
export const BLOCK_DESCRIPTION_PADDING_Y_PX = 4;

/**
 * The donor's gate (`blockFace.tsx:437`), as one named predicate instead of
 * two `&&`s repeated at every paint site.
 *
 * WHY an empty string paints NOTHING even when the toggle is on: the donor's
 * face reads `resolved.description && data.description`, i.e. a block that has
 * never been given a description looks identical to one whose description is
 * hidden. Without this, the eye toggle's "on" state would reserve an empty
 * line under every untouched block on the board.
 *
 * Pure, and used by exactly one component — so by this repo's placement rule
 * it lives WITH that component rather than in `scene/`.
 */
export function blockDescriptionIsPainted(description: string | undefined, showDescription: boolean): boolean {
  return showDescription && typeof description === "string" && description.trim() !== "";
}

/**
 * The text slot itself. `ComponentProps<"p">` and a merged `style`, exactly
 * the donor's own signature — a caller may restyle it; it may not make
 * authored characters disappear (`feedback_truthful_property_rendering`),
 * which is why nothing here truncates or clips.
 */
export function BlockDescription({ className, style, ...props }: ComponentProps<"p">) {
  return (
    <p
      data-slot="block-description"
      className={cn("text-muted-foreground", className)}
      style={{
        fontSize: BLOCK_DESCRIPTION_FONT_PX,
        lineHeight: 1.35,
        padding: `${BLOCK_DESCRIPTION_PADDING_Y_PX}px ${BLOCK_DESCRIPTION_PADDING_X_PX}px`,
        // The board stores one string; a newline the author typed is a
        // newline they meant. `pre-wrap` also keeps runs of spaces, which is
        // the same "render stored properties truthfully" rule the port
        // declaration already follows.
        whiteSpace: "pre-wrap",
        ...style,
      }}
      {...props}
    />
  );
}

"use client";

// src/components/blockMembers.tsx — Block membership: the members region a
// Block renders between its body and footer. Free vs Stack are two layout
// modes over the SAME member list ("free vs stack is basically the same
// thing, it's all just membership" — Zach), never two features: `free`
// places each member at its own authored (x, y) like a frame's canvas;
// `stack` lays the same list out as an ordered column, drag-reorderable
// like kanban cards.
//
// Ported by value from SystemSketch (read-only donor, never imported):
//   - `BLOCK_MEMBER_INSET_PX` / `BLOCK_MEMBER_GAP_PX` = 12
//     (src/blocks/memberLayout.ts:18) — the gutter/gap defaults.
//   - the layout vocabulary (src/blocks/blockModel.ts): body layouts
//     `free | stack`, member widths `fill | own`, member spacing
//     `inset | edge-to-edge`, inset backgrounds none vs soft gray.
//   - the geometry of `stackMemberPlacements` (memberLayout.ts:60): first
//     slot one gap below the header, members follow in list order, a fill
//     member takes `inner - gutter*2` — restated here as flex column
//     geometry (rowGap + per-slot margins) instead of computed x/y
//     writes, because this app is props-in DOM-out, not a tldraw store.
//   - `blockMemberDropTarget`'s midpoint rule (memberLayout.ts:84) is
//     subsumed by dnd-kit's own `closestCenter` — not re-ported.
//
// WHY spacing and width are PER MEMBER here where the donor kept them
// parent-level: the donor's own `BLOCK_MEMBER_WIDTHS` comment says
// "Parent-level on purpose for V1; a per-member override is the documented
// follow-up" — Zach is now asking for exactly that follow-up ("we want to
// be able to apply these settings on a per member setting"), so the
// per-member move is the deliberate delta from the donor, not a drift.
//
// The dnd machinery mirrors portEdge.tsx (this app's prior art for
// kanban-style reorder): PointerSensor with a 4px activation distance, and
// `neutralizeScale` pinning scaleX/scaleY to 1 — see this file's own
// `neutralizeScale` doc for why `useDerivedTransform` otherwise stretches
// non-uniform siblings mid-reorder. (Its donor, portEdge.tsx's comment B1,
// was deleted when PortEdge moved to anchor-space layout — W1, ported
// 2026-09-30 — which dropped `useSortable` there; this file still uses it.) The whole DndContext only mounts when the caller
// passes `onMembersChange` AND the layout is `stack`: a static gallery
// (or a nested Block inside a sortable member) never grows drag listeners
// it can't honour, which is also what keeps nested membership safe from
// two DndContexts fighting over one pointerdown.
import {
  DndContext,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core";
import { SortableContext, arrayMove, useSortable, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { CSSProperties, KeyboardEvent, ReactNode } from "react";
import { useLayoutEffect, useRef } from "react";

import { cn } from "../lib/utils";
import { captureEditingFocus, isSingleLineTextEditor, reorderDeltaForKey, reorderHintText, type ReorderChord } from "./keyboardReorder";
import "./keyboardReorder.css";

/* ------------------------------------------------------------------ */
/* Vocabulary — the donor's enums, restated as string unions.           */
/* ------------------------------------------------------------------ */

export type BlockMembersLayout = "free" | "stack";
/** Per member: inset (a card with breathing room) vs edge-to-edge (full inner width). */
export type BlockMemberInset = "inset" | "edge-to-edge";
/** Per member: take the parent's inner width (Fill) or keep its own (Own). */
export type BlockMemberWidth = "fill" | "own";
/** Block-level surface behind the members — "basically just differentiates it a bit". */
export type BlockInsetBackground = "none" | "soft-gray";

export const BLOCK_MEMBER_INSET_PX = 12;
export const BLOCK_MEMBER_GAP_PX = 12;

export interface BlockMember {
  id: string;
  /** Arbitrary content: another Block, a CodeEditor, text — boxes all the way down. */
  content: ReactNode;
  /** Free-mode position, px, relative to the members region. Ignored by
   *  `stack` — which is what makes a free→stack→free round trip lossless:
   *  stacking never rewrites these. */
  x?: number;
  y?: number;
  /** Per-member spacing. Defaults to `"inset"`. */
  inset?: BlockMemberInset;
  /** Per-member width. Defaults to `"fill"`. */
  width?: BlockMemberWidth;
  /**
   * WHY: rectangles/arrows can be members but make no sense stacked —
   * Zach's ruling is "they should keep their membership but have their
   * visibility turned off". `false` keeps the member in the list (and in
   * any future members panel) while rendering nothing.
   */
  visible?: boolean;
}

export interface BlockMembersProps {
  layout: BlockMembersLayout;
  members: BlockMember[];
  /** Enables drag-to-reorder in `stack` layout. Omit for a static region. */
  onMembersChange?(members: BlockMember[]): void;
  /** Vertical gap between stacked members, and the stack's top/bottom padding. */
  gap: number;
  /** Horizontal inset an `"inset"` member sits in from the Block's inner edge. */
  gutter: number;
  insetBackground: BlockInsetBackground;
  /** Off = member content leaves the DOM entirely (not opacity 0). */
  showMembers: boolean;
  /**
   * WHY overlay, not container (2026-09-17,
   * docs/FEEDBACK-2026-09-17b-PLAN.md, Lane B — "I don't like how when you
   * show the cards it kinda changes the shape of how the members look"):
   * the card is a VIEW of membership that's always true — those cards are
   * always "there" in spirit — so drawing it must never move the thing it
   * describes. On = a translucent red, Chrome-inspector-style outline is
   * painted OVER each member's existing box; it never wraps, pads or
   * insets the content, which is exactly what the old "sits inside a
   * kanban-style card surface" wrapper did wrong.
   */
  showCards: boolean;
  /**
   * The IDE move-line chord, applied to a STACKED MEMBER
   * (`keyboardReorder.ts`): while a single-line text editor inside a member
   * has focus — its title, in practice — ↑/↓ under this modifier moves that
   * member one slot within this stack, and the editor stays open, focused,
   * caret in place. Needs `layout: "stack"` and `onMembersChange` (the same
   * gate drag-to-reorder has); omit and no key is claimed.
   *
   * Zach, 2026-09-21: "it should be able to reorder any members that are
   * organized in a stack ... If you are editing their title and you do the
   * ide hot keys then it should change its order in that stack."
   */
  reorderChord?: ReorderChord;
}

/**
 * Move `activeId` to where `overId` sits — `arrayMove` over the FULL member
 * list, so a hidden member (visible: false) keeps its membership through a
 * reorder of its visible siblings. The ONE reorder a drop and the keyboard
 * chord both run, so the two can never disagree about the resulting list.
 */
export function moveMember(members: BlockMember[], activeId: string, overId: string): BlockMember[] {
  const from = members.findIndex((member) => member.id === activeId);
  const to = members.findIndex((member) => member.id === overId);
  if (from === -1 || to === -1 || from === to) return members;
  return arrayMove(members, from, to);
}

/* ------------------------------------------------------------------ */
/* Slot geometry                                                       */
/* ------------------------------------------------------------------ */

// A card whose member content is hidden still reads as a card — same as
// portEdge.tsx's empty-card behaviour ("showCard alone still reads as a
// real (if empty) card"), so "hide the members and just focus on the card
// interactions" has cards left to interact with. This is the ONE place the
// overlay is still allowed to affect geometry: with no content there is no
// content box left to preserve, so the SLOT reserves the footprint instead
// (the overlay itself never sizes anything — see `memberSlotChildren`).
export const EMPTY_CARD_MIN_PX = 24;
// Chrome DevTools' own element-highlight recipe: translucent fill + a solid
// edge, red because that's what Zach asked for. Same split as portEdge.tsx's
// identical overlay: the skin seam touches SHAPE only (radius, stroke-width)
// — this red stays exactly this red in every skin, a deliberate ruling, not
// a state the skin owns.
const CARD_OVERLAY_FILL = "rgb(239 68 68 / 0.18)";
const CARD_OVERLAY_BORDER = "rgb(239 68 68 / 0.7)";
const CARD_OVERLAY_RADIUS = "var(--bbox-skin-radius, var(--radius-lg))";
const CARD_OVERLAY_STROKE_WIDTH = "var(--bbox-skin-stroke-width, 1px)";

interface MemberSlotProps {
  member: BlockMember;
  layout: BlockMembersLayout;
  gutter: number;
  showMembers: boolean;
  showCards: boolean;
}

function resolveMemberContent({ member, showMembers }: MemberSlotProps): ReactNode {
  return showMembers ? member.content : null;
}

function slotStyle(props: MemberSlotProps): CSSProperties {
  const { member, layout, gutter, showCards } = props;
  // The one geometry-affecting case: no content box exists to keep
  // identical, so the slot (not the overlay) reserves the footprint.
  const reserveEmptyFootprint = showCards && resolveMemberContent(props) == null;
  if (layout === "free") {
    // The frame inside: authored position, own size — like the canvas
    // outside. `position: absolute` already establishes the containing
    // block the overlay positions against, same as `relative` would.
    return {
      position: "absolute",
      left: member.x ?? 0,
      top: member.y ?? 0,
      width: "max-content",
      ...(reserveEmptyFootprint ? { minHeight: EMPTY_CARD_MIN_PX } : null),
    };
  }
  const inset = (member.inset ?? "inset") === "inset";
  const own = (member.width ?? "fill") === "own";
  return {
    // `position: relative` so the overlay (`absolute inset-0`, added in
    // `memberSlotChildren`) positions against the slot itself.
    position: "relative",
    // WHY block layout, not flex: a block-level child (a Block, a
    // CodeEditor, a plain div) then fills the slot's width naturally,
    // which is what `fill` means; a flex slot would shrink children to
    // max-content and quietly break it.
    marginLeft: inset ? gutter : 0,
    marginRight: inset ? gutter : 0,
    // Own: the slot hugs its content and left-aligns where the donor
    // placed it (x = gutter for inset, 0 for edge-to-edge).
    ...(own ? { alignSelf: "flex-start", width: "max-content" } : null),
    ...(reserveEmptyFootprint ? { minHeight: EMPTY_CARD_MIN_PX } : null),
  };
}

/**
 * Content plus, when `showCards`, a sibling overlay — NEVER a wrapper.
 * `position: absolute inset-0` makes the overlay contribute nothing to the
 * slot's own size, and `pointer-events: none` keeps it out of the way of
 * drag/reorder (B3) — an overlay the pointer could hit would steal the
 * gesture that reorders members.
 */
function memberSlotChildren(props: MemberSlotProps): ReactNode {
  const content = resolveMemberContent(props);
  if (!props.showCards) return content;
  return (
    <>
      {content}
      <div
        aria-hidden
        data-slot="block-member-card"
        className="pointer-events-none absolute inset-0 border"
        style={{
          borderRadius: CARD_OVERLAY_RADIUS,
          borderWidth: CARD_OVERLAY_STROKE_WIDTH,
          backgroundColor: CARD_OVERLAY_FILL,
          borderColor: CARD_OVERLAY_BORDER,
        }}
      />
    </>
  );
}

function memberSlotData(member: BlockMember) {
  return {
    "data-slot": "block-member",
    "data-member-id": member.id,
    "data-member-inset": member.inset ?? "inset",
    "data-member-width": member.width ?? "fill",
  } as const;
}

/**
 * WHY an edge-to-edge member squares ALL FOUR corners of its outermost box
 * (`[&>*]` — the card surface or the bare content, never anything deeper):
 * Zach's ruling — "when block goes edge to edge, its corners should not be
 * radius, so it looks like it's part of the parent block". A rounded corner
 * on a flush member reads as a separate card that happens to touch; square
 * corners merge it into the parent's surface. All four rather than only the
 * flush left/right sides: a stacked member only ever touches the parent's
 * left/right inner edges (the header and the region's own gap padding keep
 * it off the top and bottom), and in the degenerate case where one does
 * reach a real corner, the parent Block's own `overflow-hidden rounded-lg`
 * re-clips it to the parent's radius anyway — so following the parent's
 * radius from the inside would only duplicate what the clip already
 * guarantees. An inset member keeps its radius on purpose: it IS a
 * separate card. Free-mode members are never flush, so nothing applies.
 */
function slotClassName(member: BlockMember, layout: BlockMembersLayout): string | undefined {
  if (layout !== "stack") return undefined;
  return (member.inset ?? "inset") === "edge-to-edge" ? "[&>*]:rounded-none!" : undefined;
}

function StaticMemberSlot(props: MemberSlotProps) {
  return (
    <div
      {...memberSlotData(props.member)}
      className={slotClassName(props.member, props.layout)}
      style={slotStyle(props)}
    >
      {memberSlotChildren(props)}
    </div>
  );
}

/**
 * portEdge.tsx's B1 fix, copied by value: `useSortable`'s transform can
 * carry a scaleX/scaleY "squeeze" from `useDerivedTransform` on any
 * sibling whose rect differs from the dragged one's — members are
 * arbitrary content, so theirs always differ. Pin scale to 1; only ever
 * translate.
 */
function neutralizeScale(transform: Parameters<typeof CSS.Transform.toString>[0]) {
  if (!transform) return transform;
  return { ...transform, scaleX: 1, scaleY: 1 };
}

/**
 * The chord hint's spot inside a member slot: the right end, vertically
 * centred — clear of a title, which starts at the left. Inside the slot
 * rather than beside it because the parent Block clips its own box.
 */
const MEMBER_REORDER_HINT_STYLE: CSSProperties = {
  position: "absolute",
  right: 8,
  top: "50%",
  transform: "translateY(-50%)",
  fontSize: 10,
  lineHeight: 1,
  whiteSpace: "nowrap",
  color: "var(--muted-foreground)",
  pointerEvents: "none",
};

function SortableMemberSlot(
  props: MemberSlotProps & {
    /** `BlockMembersProps.reorderChord`'s key handler, bound to this stack. */
    onReorderKey?(memberId: string, event: KeyboardEvent<HTMLDivElement>): void;
    reorderHint?: string;
  },
) {
  const { onReorderKey, reorderHint } = props;
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: props.member.id });
  const style: CSSProperties = {
    ...slotStyle(props),
    transform: CSS.Transform.toString(neutralizeScale(transform)),
    transition,
    opacity: isDragging ? 0.35 : 1,
    cursor: "grab",
    touchAction: "none",
  };
  return (
    <div
      ref={setNodeRef}
      {...memberSlotData(props.member)}
      className={slotClassName(props.member, props.layout)}
      data-dragging={isDragging || undefined}
      style={style}
      {...attributes}
      {...listeners}
      onKeyDown={onReorderKey ? (event) => onReorderKey(props.member.id, event) : undefined}
    >
      {memberSlotChildren(props)}
      {reorderHint && (
        // Shown only while this member's own title editor has focus —
        // keyboardReorder.css, which also keeps a nested stack's out.
        <span data-slot="block-member-reorder-hint" aria-hidden style={MEMBER_REORDER_HINT_STYLE}>
          {reorderHint}
        </span>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* The region                                                          */
/* ------------------------------------------------------------------ */

export function BlockMembers({ layout, members, onMembersChange, gap, gutter, insetBackground, showMembers, showCards, reorderChord }: BlockMembersProps) {
  // `reorderChord`'s focus hand-back, run in the layout effect of the render
  // that carries the new order — see `captureEditingFocus` for why moving a
  // member needs one, and portEdge.tsx's identical `pendingFocusRestore`.
  // Hooks above the early return below, which is a prop, not a hook order.
  const pendingFocusRestore = useRef<(() => void) | null>(null);
  useLayoutEffect(() => {
    const restore = pendingFocusRestore.current;
    pendingFocusRestore.current = null;
    restore?.();
  });

  // Both toggles off: nothing member-related renders at all — the Block
  // itself still stands (its header/body/footer are not this region's).
  if (!showMembers && !showCards) return null;

  const rendered = members.filter((member) => member.visible !== false);
  const sortable = layout === "stack" && onMembersChange !== undefined;

  // WHY a keydown on the member SLOT rather than a keymap inside one
  // editor: a member's content is arbitrary (a Block whose title is an
  // `EditableText`, a `CodeEditor`, …), so the stack cannot reach into it —
  // it listens for the chord bubbling out of whichever single-line editor
  // sits inside. `defaultPrevented` is the editor's own claim (a multi-line
  // CodeEditor's Alt+↑/↓ move-line) and wins; the `closest` check makes a
  // nested stack's member answer only to its own stack.
  const handleReorderKey =
    sortable && reorderChord && showMembers
      ? (memberId: string, event: KeyboardEvent<HTMLDivElement>) => {
          if (event.defaultPrevented || event.nativeEvent.isComposing) return;
          if (!(event.target instanceof Element) || !isSingleLineTextEditor(event.target)) return;
          if (event.target.closest('[data-slot="block-member"]') !== event.currentTarget) return;
          const delta = reorderDeltaForKey(event, "column", reorderChord);
          if (delta === null) return;
          // Claimed even at an end — the chord means "move this member".
          event.preventDefault();
          event.stopPropagation();
          const index = rendered.findIndex((member) => member.id === memberId);
          const neighbour = rendered[index + delta];
          if (index === -1 || !neighbour) return;
          pendingFocusRestore.current = captureEditingFocus(event.target);
          onMembersChange(moveMember(members, memberId, neighbour.id));
        }
      : undefined;
  const reorderHint = handleReorderKey && reorderChord ? reorderHintText("column", reorderChord) : undefined;

  const regionStyle: CSSProperties =
    layout === "free"
      ? // The frame inside: fills whatever height the Block gives it. A free
        // region needs the Block to carry an explicit height — absolutely
        // positioned members contribute none, same as a canvas.
        { position: "relative", flex: 1, minHeight: 0, alignSelf: "stretch" }
      : // The donor's stack geometry: first member one gap below the header,
        // one uniform gap between members, one gap before whatever follows.
        { display: "flex", flexDirection: "column", rowGap: gap, paddingTop: gap, paddingBottom: gap };

  const region = (
    <div
      data-slot="block-members"
      data-layout={layout}
      data-inset-background={insetBackground}
      className={cn(insetBackground === "soft-gray" && "bg-muted/50")}
      style={regionStyle}
    >
      {rendered.map((member) => {
        const slotProps: MemberSlotProps = { member, layout, gutter, showMembers, showCards };
        return sortable ? (
          <SortableMemberSlot key={member.id} {...slotProps} onReorderKey={handleReorderKey} reorderHint={reorderHint} />
        ) : (
          <StaticMemberSlot key={member.id} {...slotProps} />
        );
      })}
    </div>
  );

  if (!sortable) return region;
  return (
    <MemberDndBoundary members={members} renderedIds={rendered.map((member) => member.id)} onMembersChange={onMembersChange}>
      {region}
    </MemberDndBoundary>
  );
}

function MemberDndBoundary({
  members,
  renderedIds,
  onMembersChange,
  children,
}: {
  members: BlockMember[];
  renderedIds: string[];
  onMembersChange(members: BlockMember[]): void;
  children: ReactNode;
}) {
  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 4 } }));
  function handleDragEnd({ active, over }: DragEndEvent) {
    if (!over || over.id === active.id) return;
    const next = moveMember(members, String(active.id), String(over.id));
    if (next !== members) onMembersChange(next);
  }
  return (
    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <SortableContext items={renderedIds} strategy={verticalListSortingStrategy}>
        {children}
      </SortableContext>
    </DndContext>
  );
}

/**
 * src/components/blockPort.layout.ts — the pure half of `BlockPort`
 * (docs/BLOCK-PORT-EDGES-PLAN.md §2/§3, phase A1).
 *
 * Two jobs, both closed-form and both unit-testable without a DOM:
 *
 *  1. `railPlanFor` — the view→placement rules, RESTATED AS PortEdge PROPS.
 *     SystemSketch's `layoutBlock.ts` is the target spec for the behaviour
 *     (each row below cites the donor line it reproduces); not one line of
 *     it is ported. The governing principle (Zach, 2026-09-17): "System
 *     sketch is a great reference for the target spec, but we need to
 *     refactor to use our component based approach." A layout problem
 *     `portEdge.tsx` already solves is expressed as its props, never
 *     re-implemented here.
 *
 *  2. `railBoxFor` — where the rail sits and how long it is, given the
 *     Block's MEASURED bands (D-A5: a Block hugs its content, so any closed
 *     form over props lies the moment a header wraps). The measuring is the
 *     component's, app-level and legal here (the D8 precedent — the app may
 *     measure itself, the core may not); the arithmetic on those measured
 *     numbers is pure and lives here.
 *
 * WHY a rail's CONTENT box — not its border box — is what spans the band:
 * `PortEdge`'s track carries its own `CONTAINER_BORDER` + `CONTAINER_PADDING`
 * before the first slot box, so a rail laid flush with the band would start
 * its first dot 16px further in than the band top and the "packed from the
 * body top" rule would quietly become "packed from 16px below the body top".
 * Insetting the border box by `RAIL_MAIN_INSET_PX` makes the stated rule the
 * measured one: first dot centre at `bandTop + slotMainPx / 2`, exactly.
 */
import { BLOCK_SIDES, PORT_DIAMETERS, PORT_LABEL_GAP, PORT_RING_OVERHANG_PX, type BlockSide, type PortSize } from "./port.layout";
import {
  CONTAINER_BORDER,
  CONTAINER_PADDING,
  DEFAULT_ALIGN_GAP,
  defaultDistributionForEdges,
  type Distribution,
} from "./portEdge.layout";

/* ------------------------------------------------------------------ */
/* Vocabulary — the donor's own two enums, by value                    */
/* ------------------------------------------------------------------ */

/** Donor `BLOCK_PRESENTATION_VIEWS` (`blockModel.ts:96`). */
export type BlockView = "simple" | "port" | "expanded";
export const BLOCK_VIEWS: BlockView[] = ["simple", "port", "expanded"];
export const BLOCK_VIEW_LABELS: Record<BlockView, string> = {
  simple: "Simple",
  port: "Port",
  expanded: "Expanded",
};

/** Donor `PORT_LAYOUTS` (`blockModel.ts:106`); default `inline`
 *  (`blockModel.ts:622`). */
export type BlockPortLayout = "inline" | "offset";
export const BLOCK_PORT_LAYOUTS: BlockPortLayout[] = ["inline", "offset"];
export const BLOCK_PORT_LAYOUT_LABELS: Record<BlockPortLayout, string> = {
  inline: "Inline",
  offset: "Offset",
};

/* ------------------------------------------------------------------ */
/* Constants                                                           */
/* ------------------------------------------------------------------ */

/**
 * The main-axis size of ONE slot box on a rail.
 *
 * WHY this is re-declared instead of imported: it mirrors `portEdge.tsx`'s
 * module-private `EMPTY_SLOT_MIN_PX`, the size a slot takes when `showCard`
 * is false — which is exactly how a rail is configured (`BlockPort` never
 * turns cards on, since the Block itself is the card). `portEdge.tsx` does
 * not export it, and A1 is authorised exactly one surgical edit to that file
 * (D-A7's `renderCollapsed`), which this is not.
 *
 * A duplicated constant that must match is only safe if a mismatch is loud,
 * so it is pinned where a drift fails rather than hides: the dormant unit
 * test's own case, and — the one that runs today — `BlockPort.stories.tsx`'s
 * `ClassicDag`, which MEASURES a rendered `[data-slot="port-edge-member"]`
 * box and asserts it equals this number. Change `EMPTY_SLOT_MIN_PX` without
 * changing this and that story goes red.
 */
export const PORT_EDGE_SLOT_MIN_PX = 24;

/** The gap between adjacent slot boxes on an `aligned` rail — PortEdge's
 *  own default align gap, reused rather than a second number. */
export const RAIL_GAP_PX = DEFAULT_ALIGN_GAP;

/**
 * Constant clearance between a wall's first/last dot and the block's corner,
 * on a spread rail. Donor `RAIL_END_MARGIN_PX` (`layoutBlock.ts:115`, used
 * by `placeHorizontalRails`); the donor's own test pins the *property* that
 * this margin stays constant regardless of block size
 * (`portLensPlacement.test.ts:189-198`), which is why it is a constant here
 * too and not a fraction of the wall.
 */
export const RAIL_END_MARGIN_PX = 18;

/** How far into a `PortEdge` track's border box its first slot box starts:
 *  the track's own border plus its own padding. */
export const RAIL_MAIN_INSET_PX = CONTAINER_BORDER + CONTAINER_PADDING;

/**
 * The rail's CROSS-axis size. Half of it is what the rail is pushed out by,
 * so the track's cross centre — which `alignItems: center` already puts
 * every dot on (`portEdge.tsx`'s track style) — lands exactly on the
 * Block's border line. Derived, never a literal.
 */
export const RAIL_CROSS_PX = PORT_EDGE_SLOT_MIN_PX + 2 * RAIL_MAIN_INSET_PX;

/**
 * Which edge `portLayout: "offset"` pushes down. The donor offsets the
 * OUTPUT lane (`outputStart = slot + inputs.length`, `layoutBlock.ts:461`)
 * and outputs live on the right wall (`portSideForDirection`), so "offset"
 * is a statement about the right edge specifically — not about "whichever
 * edge you happened to declare second".
 */
export const OFFSET_TRAILING_EDGE: BlockSide = "right";

export function railAxisFor(edge: BlockSide): "row" | "column" {
  return edge === "left" || edge === "right" ? "column" : "row";
}

/** Centre-to-centre distance between adjacent dots on an `aligned` rail. */
export function railPitchPx(slotMainPx: number = PORT_EDGE_SLOT_MIN_PX, gap: number = RAIL_GAP_PX): number {
  return slotMainPx + gap;
}

/**
 * §4b·S4 / D-A3 — the EXACT push-in that puts the trailing lane's first
 * port one full pitch below the leading lane's last port, which is what the
 * donor's `outputStart = slot + inputs.length` means in pixels.
 *
 * `portEdge.layout.ts`'s `offsetPaddingFor` used to be a self-described
 * approximation (`count * gap`, ignoring the slots themselves — 72px short
 * on a three-port lane, enough that the two lanes visibly interleaved) with
 * zero call sites. FIXED 2026-09-17 (docs/PROPOSALS-2026-09-17.md P9a): it
 * now computes this exact same `count * (slotMainPx + gap)` formula, given
 * the same `slotMainPx`. Still a separate function, not a re-export — this
 * one defaults `slotMainPx`/`gap` to BlockPort's own constants, the other
 * has no default (PortEdge's generic module owns no slot-size constant).
 */
export function offsetEdgePaddingPx(
  leadCount: number,
  slotMainPx: number = PORT_EDGE_SLOT_MIN_PX,
  gap: number = RAIL_GAP_PX,
): number {
  return Math.max(0, leadCount) * (slotMainPx + gap);
}

/* ------------------------------------------------------------------ */
/* railPlanFor — the view→placement table, as PortEdge props           */
/* ------------------------------------------------------------------ */

/**
 * Which of the Block's bands a rail's content box spans.
 *
 * `"header"` (2026-09-22) is the band between `headerTop` and `bodyTop` —
 * the header strip itself. Zach, annotating a Block drawn as Header / Body /
 * Footer: *"Ports on Header, inputs and outputs…"*, and then the same block
 * with the header shrunk to a tab carrying a port on each of ITS edges
 * (`Pasted image 20260922184406.png`, `…184423.png`).
 *
 * WHY this is a general Block capability and not a region-only one: an arm
 * row's header, a region's corner card and an ordinary Block that simply
 * wants its interface on the title bar are the same geometry — a rail boxed
 * against the header strip instead of the body. Zach's own conclusion from
 * that sketch is the reason it lives here: *"So everything really is then
 * just a block, definitely no need for a separate BlockRegion."* WHAT THIS
 * REJECTS: a `headerPorts` flag on `BlockRegion` (or on an arm), which would
 * make the same dot mean a different thing depending on who drew it, and
 * would leave an ordinary Block unable to do it at all.
 */
export type RailBand = "block" | "body" | "header";

export interface RailPlanInput {
  view: BlockView;
  /** Port view only; ignored elsewhere. */
  portLayout: BlockPortLayout;
  edge: BlockSide;
  /** Every port id on THIS edge, in order. */
  itemIds: string[];
  /** Ports on the lane this edge is offset behind — the left edge's count,
   *  when planning the right edge under `portLayout: "offset"`. */
  leadCount: number;
  /** `view === "simple"` by default; the async gallery passes false so a
   *  Simple face spreads its ports along the walls instead of collapsing
   *  them (donor `layoutBlock.ts:1286-1296`). */
  collapsePorts: boolean;
  /**
   * E-3 (Zach, 2026-09-17): every populated edge on the BLOCK, not just this
   * one — "port" view's spacing default depends on the SET ("if port edges
   * on all 4 sides... distribute and around. if port edges just on left or
   * right... aligned to edge and to the start"), and a single edge cannot
   * see its siblings to answer that on its own. Optional, defaulting to
   * `[edge]` (this edge and no sibling), so an existing caller that only
   * ever planned one edge at a time — `blockPort.layout.test.ts`'s own
   * fixtures, `BlockPortLane.stories.tsx`'s lane-availability probe — keeps
   * its prior single-edge reading with no call-site change required.
   * `BlockPort` (blockPort.tsx) is the one caller that DOES see every edge,
   * and always passes the real set.
   */
  populatedEdges?: BlockSide[];
}

/** Exactly the subset of `PortEdgeProps` a view rule decides, plus the two
 *  geometry facts `railBoxFor` needs. Nothing here is a new layout
 *  primitive — every field is a prop `PortEdge` already shipped. */
export interface RailPlan {
  distribution: Distribution;
  groups: string;
  groupMode: "off" | "grouped" | "collapsed";
  band: RailBand;
  /** Main-axis inset applied to the rail's CONTENT box at both ends. */
  endMarginPx: number;
  /** True when this rail draws one stand-in dot for the whole wall. */
  collapsed: boolean;
}

/**
 * The four view rules of docs/BLOCK-PORT-EDGES-PLAN.md §3, and nothing else.
 * Every branch returns props `PortEdge` already understands.
 *
 * | rule             | donor spec (target behaviour)                        | props returned here                                       |
 * |------------------|------------------------------------------------------|-----------------------------------------------------------|
 * | simple           | all ports coincident at `height / 2`                 | `groupMode:"collapsed"` + a groups line naming every id,   |
 * |                  | (`layoutBlock.ts:1282,1301-1330`)                    | `distribute / space-evenly`, rail over the whole block     |
 * | port + inline    | input row i and output row i share a slot            | both rails `aligned / start / gap`, `edgePadding: 0`       |
 * |                  | (`planBodySlots`, `:461`), packed from the body top  |                                                            |
 * |                  | (`:1434-1435`)                                       |                                                            |
 * | port + offset    | outputs start at slot `inputs.length` (`:461`)       | right rail's `edgePadding = leadCount * (slot + gap)`      |
 * | port + populated | a populated top/bottom wall anywhere on the block    | EVERY edge `distribute / space-around` (E-3 below)         |
 * | top/bottom       |                                                       |                                                             |
 * | expanded         | evenly across the section (`:592`)                   | both rails `distribute / space-evenly`, body band          |
 * | spread-on-simple | walls, constant 18px end margin (`:1286-1296`)       | `distribute / space-between` + `RAIL_END_MARGIN_PX`        |
 *
 * WHY `space-evenly` and not `space-between` for the collapsed slot: with a
 * single box `mainAxisPositions` returns `[0]` for `space-between` (pinning
 * it to the top of the rail) and `[free / 2]` for `space-evenly` — and the
 * donor's midpoint is the entire point of simple view.
 *
 * WHY top/bottom walls ignore `view` when choosing their BAND (not their
 * distribution — see E-3 below): a horizontal rail has no "body band" to
 * speak of — the donor spreads them along the full wall with a constant end
 * margin in every view (`placeHorizontalRails`). Only the collapse case
 * differs, and it differs the same way on every wall.
 *
 * E-3 (Zach, 2026-09-17): "if port edges on all 4 sides. then the edges
 * should all be distribute and around. if port edges just on left or right,
 * then it should be aligned to edge and to the start... (thats the classic
 * port view of course then in expanded we do distribute)." So in PORT view
 * specifically, the whole block's set of populated edges — `populatedEdges`
 * — decides every populated edge's distribution, not the view alone: a
 * populated top or bottom wall (including a row-axis edge's own trivial
 * membership in that set — a top rail's plan IS itself "a populated top
 * wall") switches every populated edge, left/right included, to
 * `distribute/space-around`; left/right-only stays the existing
 * `aligned/start` pairing. "if there is only 1 port it should be in the
 * middle" needs no special case — `mainAxisPositions`' own `space-around`
 * branch already centres a lone box (`portEdge.layout.ts`'s own docblock
 * quotes the CSS spec on exactly this). "in expanded we do distribute" is
 * an acknowledgement, not a second case to build — `view === "expanded"`
 * already always distributes, below, untouched by this rule.
 */
export function railPlanFor(input: RailPlanInput): RailPlan {
  const { view, portLayout, edge, itemIds, leadCount, collapsePorts, populatedEdges = [edge] } = input;

  if (view === "simple" && collapsePorts) {
    return {
      // Every id on one line: `computeSlots` clusters them into ONE slot, so
      // the whole wall renders as a single box. A line naming fewer than two
      // known ids is dropped by the parser (a group of one is just an
      // ungrouped port) — harmless, because a one-port wall is already one
      // slot, and `BlockPort` draws it the same bare dot either way.
      groups: itemIds.join(", "),
      groupMode: "collapsed",
      distribution: { mode: "distribute", scheme: "space-evenly" },
      band: "block",
      endMarginPx: 0,
      collapsed: true,
    };
  }

  if (view === "port") {
    const hasHorizontalWall = populatedEdges.some((e) => e === "top" || e === "bottom");
    if (hasHorizontalWall) {
      const row = railAxisFor(edge) === "row";
      return {
        groups: "",
        groupMode: "off",
        // ONE rule, not a second copy: `defaultDistributionForEdges`
        // (portEdge.layout.ts) is the single source of truth for WHICH
        // distribution a population implies. Lanes E and D landed the same
        // rule independently — E exported it, D inlined the literals — and
        // two correct implementations of one rule is how they silently
        // diverge later. Read it here instead.
        distribution: defaultDistributionForEdges(true),
        // Row-axis rails keep spanning the whole block — the band a
        // horizontal wall has always used (see the WHY above); column-axis
        // rails stay in the body band exactly as the left/right-only case
        // below does. Only the SCHEME changed, never where the rail sits.
        band: row ? "block" : "body",
        endMarginPx: row ? RAIL_END_MARGIN_PX : 0,
        collapsed: false,
      };
    }
    // Left/right only, no sibling top/bottom wall — the pre-E-3 pairing,
    // unchanged.
    const offset = portLayout === "offset" && edge === OFFSET_TRAILING_EDGE;
    return {
      groups: "",
      groupMode: "off",
      // Same source of truth for the MODE; the two block-specific numbers
      // are layered on top, and they are the reason this is a spread rather
      // than a bare call. `RAIL_GAP_PX` is the Block's own rail pitch (not
      // PortEdge's standalone `DEFAULT_ALIGN_GAP`), and `edgePadding` is the
      // offset-lane inset that only exists when a Block pushes its trailing
      // edge clear of the wire. Neither belongs in a function that knows
      // nothing about Blocks.
      distribution: {
        ...defaultDistributionForEdges(false),
        gap: RAIL_GAP_PX,
        edgePadding: offset ? offsetEdgePaddingPx(leadCount) : 0,
      },
      band: "body",
      endMarginPx: 0,
      collapsed: false,
    };
  }

  // Spread-on-simple, and every horizontal wall OUTSIDE port view: along
  // the whole wall, with the donor's constant corner clearance.
  //
  // WHY `band: "block"` is right here even for a COLUMN-axis edge, and is
  // NOT the cause of a label colliding with a block's title (investigated
  // and reverted 2026-09-17): a *simple face* has no visible header/body
  // divide — that is what makes it simple — so its side walls are meant to
  // span the block's whole height. Zach's own reference for this view
  // ("FOUR WALLS AT ONCE · SIMPLE FACE, PORTS SPREAD") shows exactly that:
  // the left wall's ports run from near the top corner to near the bottom
  // one, not confined to a body band. `BlockPort.stories.tsx`'s `FourEdges`
  // pins it at 30px from the leading corner and correctly rejected a change
  // to `"body"` (which measured 12px).
  //
  // So when a caller puts a simple-view rail on a block that DOES draw a
  // header — as `AsyncRegion.stories.tsx` does — an inward label can land
  // on the title. That is the fixture reaching for two things at once, not
  // this rule being wrong, and it is fixed there via the caller-facing
  // override seams (`BlockEdgeSpec.distribution`, `portEdgeProps.textLayout`).
  if (view === "simple" || railAxisFor(edge) === "row") {
    return {
      groups: "",
      groupMode: "off",
      distribution: { mode: "distribute", scheme: "space-between" },
      band: "block",
      endMarginPx: RAIL_END_MARGIN_PX,
      collapsed: false,
    };
  }

  // view === "expanded", column axis (row axis was already handled above)
  return {
    groups: "",
    groupMode: "off",
    distribution: { mode: "distribute", scheme: "space-evenly" },
    band: "body",
    endMarginPx: 0,
    collapsed: false,
  };
}

/* ------------------------------------------------------------------ */
/* railBoxFor — where the rail sits, from the Block's measured bands    */
/* ------------------------------------------------------------------ */

/**
 * The Block's geometry as `BlockPort`'s wrapper sees it — every number in
 * WRAPPER-LOCAL pixels, so a rail can be positioned with plain `left`/`top`.
 * `bodyTop`/`bodyBottom` bound the band between header and footer (the
 * region holding body and members), which is what the donor calls the body
 * section. `headerTop` is undefined when the Block renders no header at
 * all — the function port (see `functionPortCenterPx` below) has nowhere
 * to sit in that case and stays unrendered rather than degrading to some
 * other line.
 */
export interface BlockBands {
  blockLeft: number;
  blockTop: number;
  blockWidth: number;
  blockHeight: number;
  bodyTop: number;
  bodyBottom: number;
  headerTop?: number;
  /**
   * The header strip's own right edge, when it is NARROWER than the block —
   * the "head tab" (Zach, 2026-09-22, `Pasted image 20260922184414.png`:
   * *"Head Tab View"*). Undefined means the header spans the full width, so
   * a `header`-band right rail falls back to the block's right edge and a
   * full-width header behaves exactly as it always has.
   *
   * WHY measured rather than derived from a prop: the tab hugs its content
   * (a chevron, a title, maybe a badge), so only the DOM knows how wide it
   * ended up — the same reason `headerTop` is measured and not computed.
   */
  headerRight?: number;
}

export interface RailBox {
  left: number;
  top: number;
  width: number;
  height: number;
}

/**
 * The rail's border box, positioned so that (a) its cross centre lands on
 * the Block's border line and (b) its CONTENT box spans exactly the planned
 * band, inset by `endMarginPx` at each end.
 */
export function railBoxFor(edge: BlockSide, plan: RailPlan, bands: BlockBands): RailBox {
  const axis = railAxisFor(edge);

  // The header band runs `headerTop`..`bodyTop`, and its right-hand border
  // line is the TAB's right edge when the header hugs. A block with no
  // header measures no `headerTop`, so the band degrades to the block band
  // rather than collapsing to a zero-height rail at the top edge — the same
  // "nowhere to sit, so do not degrade to some other line" rule the function
  // port follows, except a wall rail always has the block's own wall to fall
  // back to.
  const headerBand = plan.band === "header" && bands.headerTop != null;
  const headerRightLine = bands.headerRight ?? bands.blockLeft + bands.blockWidth;

  if (axis === "column") {
    const bandStart = headerBand ? bands.headerTop! : plan.band === "body" ? bands.bodyTop : bands.blockTop;
    const bandEnd = headerBand ? bands.bodyTop : plan.band === "body" ? bands.bodyBottom : bands.blockTop + bands.blockHeight;
    const contentStart = bandStart + plan.endMarginPx;
    const contentEnd = bandEnd - plan.endMarginPx;
    const borderLine =
      edge === "left" ? bands.blockLeft : headerBand ? headerRightLine : bands.blockLeft + bands.blockWidth;
    return {
      left: borderLine - RAIL_CROSS_PX / 2,
      top: contentStart - RAIL_MAIN_INSET_PX,
      width: RAIL_CROSS_PX,
      height: Math.max(contentEnd - contentStart, 0) + 2 * RAIL_MAIN_INSET_PX,
    };
  }

  // Row axis. In the header band a `top` rail rides the header's own top
  // line and a `bottom` rail the line the header shares with the body —
  // and both span the TAB's width, not the block's, so a hugged header's
  // row rail stops where the tab does.
  const rowRight = headerBand ? headerRightLine : bands.blockLeft + bands.blockWidth;
  const contentStart = bands.blockLeft + plan.endMarginPx;
  const contentEnd = rowRight - plan.endMarginPx;
  const borderLine = headerBand
    ? edge === "top"
      ? bands.headerTop!
      : bands.bodyTop
    : edge === "top"
      ? bands.blockTop
      : bands.blockTop + bands.blockHeight;
  return {
    left: contentStart - RAIL_MAIN_INSET_PX,
    top: borderLine - RAIL_CROSS_PX / 2,
    width: Math.max(contentEnd - contentStart, 0) + 2 * RAIL_MAIN_INSET_PX,
    height: RAIL_CROSS_PX,
  };
}

/**
 * Where an `aligned` rail's first dot CENTRE lands along the main axis, in
 * wrapper-local px — the closed form the stories assert against, so the
 * stated rule ("packed from the body top") and the measured rule are the
 * same sentence. Returns `null` for a `distribute` plan, whose positions
 * depend on the rail's own length and are measured instead.
 */
export function alignedFirstCentrePx(
  plan: RailPlan,
  bands: BlockBands,
  slotMainPx: number = PORT_EDGE_SLOT_MIN_PX,
): number | null {
  if (plan.distribution.mode !== "aligned") return null;
  const bandStart = plan.band === "body" ? bands.bodyTop : bands.blockTop;
  return bandStart + plan.endMarginPx + plan.distribution.edgePadding + slotMainPx / 2;
}

/* ------------------------------------------------------------------ */
/* functionPortCenterPx — the header's reserved pin-1 port              */
/* ------------------------------------------------------------------ */

/**
 * Where the function port's dot CENTRE lands, in wrapper-local px: on the
 * Block's left border line (`blockLeft`, the same wall convention every
 * rail dot straddles — see `railBoxFor`'s column-axis case), vertically at
 * the header band's own centre line (`headerTop`..`bodyTop`, since
 * `bodyTop` IS the header's bottom edge whenever a header exists — see
 * `BlockBands`'s own doc).
 *
 * Zach, 2026-09-17 (a variable that is itself a function reserves "a
 * special port on the header left edge... at most 1 port there and you
 * cannot move it"): position is what carries the meaning, so this is a
 * closed form, not a slot in a `PortEdge` distribution — there is no
 * `RailPlan` for it and it never becomes one.
 *
 * Returns `null` when the Block renders no header (`headerTop` absent) —
 * there is no header centre line to sit on.
 */
export function functionPortCenterPx(bands: BlockBands): { x: number; y: number } | null {
  if (bands.headerTop == null) return null;
  return { x: bands.blockLeft, y: (bands.headerTop + bands.bodyTop) / 2 };
}

/* ------------------------------------------------------------------ */
/* collapsedWallCenterPx — where a collapsed wall's one dot sits         */
/* ------------------------------------------------------------------ */

/**
 * Where a wall's SINGLE collapsed stand-in dot centres, in wrapper-local
 * px, given only the Block's box and which wall — the closed form of the
 * `railPlanFor` "simple" branch's own geometry, restated so the invariant
 * ("every wire into a hidden wall lands on ITS centre, never drops") is
 * provable without a DOM.
 *
 * Zach, 2026-09-17, on a screenshot of exactly this: "expanded view to
 * simple view is not an issue. All of the ports collapse to one that is
 * centered in the block body." — every populated wall in "simple" gets one
 * dot, and it sits on that wall's own midline, full stop.
 *
 * Derivation, not a new rule: the "simple" branch of `railPlanFor` always
 * returns `band: "block"` and `endMarginPx: 0`, so (via `railBoxFor`) the
 * rail's CONTENT box spans the wall's own full length with no inset; a
 * `distribute / space-evenly` plan centres a single box in that span
 * (`railPlanFor`'s own WHY on why `space-evenly`, not `space-between`, is
 * what makes a lone box land at the midpoint). This function is that
 * arithmetic without a `RailPlan` or a rendered `PortEdge` in the loop —
 * `column`-axis walls (left/right) land at `blockTop + blockHeight / 2`;
 * `row`-axis walls (top/bottom) land at `blockLeft + blockWidth / 2`. The
 * cross-axis coordinate is the wall's own border line, the same convention
 * every rail dot straddles (`railBoxFor`'s column-axis case;
 * `functionPortCenterPx`'s note above).
 *
 * SystemSketch's own analogue for "this wall has nothing placed on it, so
 * every port here shares one fallback anchor" is
 * `projectBlockConnectionPorts`'s `fallback` (`blockPorts.ts:141-145`):
 * `{ x: side === "input" ? 0 : layout.bounds.w, y: layout.bounds.h / 2 }` —
 * left/right only, vertical midpoint, exactly this formula's column-axis
 * case in the donor's own local (0,0)-origin coordinates. Its dedicated
 * "simple view" collapse (`layoutBlock.ts:1282,1301-1330`, already the
 * citation for `railPlanFor`'s "simple" branch above) computes the SAME
 * `midpoint = height / 2` with `x: 0` / `x: width` per side — so this is
 * class (b), a known technique with real prior art, not invented here; the
 * row-axis (top/bottom) case has no donor citation and is this repo's own
 * symmetric extension, needed because `railPlanFor` collapses a horizontal
 * wall in "simple" too (`blockPort.layout.test.ts`'s "still collapses on a
 * horizontal wall" case) and the donor's own ports never populate that
 * wall.
 *
 * Used to PROVE the rendered stand-in dot is where the rule says it must
 * be (`blockPort.layout.test.ts`, and `CollapseWireEndpoints.stories.tsx`'s
 * play functions measure the real DOM against this closed form) — not
 * consumed by `wireLayer.tsx` as a synthetic fallback. Every wall this
 * function describes already renders a real, measurable stand-in dot
 * (`blockPort.tsx`'s `renderCollapsed`/`renderItem`), so `resolveDot`'s
 * existing `[data-collapsed-ports]` reading (wireLayer.tsx:86-90) already
 * finds it; inventing a second, computed answer there would contradict
 * that file's own stated rule — "WireLayer never invents a point" — for a
 * case that never actually goes unresolved in this kit.
 */
export function collapsedWallCenterPx(bands: BlockBands, edge: BlockSide): { x: number; y: number } {
  if (railAxisFor(edge) === "column") {
    return {
      x: edge === "left" ? bands.blockLeft : bands.blockLeft + bands.blockWidth,
      y: bands.blockTop + bands.blockHeight / 2,
    };
  }
  return {
    x: bands.blockLeft + bands.blockWidth / 2,
    y: edge === "top" ? bands.blockTop : bands.blockTop + bands.blockHeight,
  };
}

/* ------------------------------------------------------------------ */
/* functionPortHeaderInsetPx — where the header's OWN content starts     */
/* (D-5)                                                                */
/* ------------------------------------------------------------------ */

/**
 * How far a header's own content must sit from the Block's left wall so it
 * starts exactly where a body port's LABEL would start — not where the
 * port's DOT does. Zach's screenshot (153855) draws this literally: a red
 * line runs through "Planner" and through "gain"/"reset"/"pose" below it —
 * the labels, not the dots — captioned "offset is same as ports.."
 *
 * A body port on the left wall centres its DOT on `blockLeft`
 * (`functionPortCenterPx`'s own note; `railBoxFor`'s column-axis case puts
 * every rail's cross-centre on the same line), and `LabeledPort`
 * (labeledPort.tsx) anchors its label `PORT_RING_OVERHANG_PX +
 * PORT_LABEL_GAP` clear of the dot's own RING, past the dot's radius — so
 * the label's left edge sits exactly `radius + PORT_RING_OVERHANG_PX +
 * PORT_LABEL_GAP` past `blockLeft`. That delta does not depend on the
 * Block's box at all — the dot and the header both start flush on the same
 * wall — so it is a closed form over the port's OWN diameter, not a value
 * read off `BlockBands`, and it is exactly what "if there is no label then
 * the bar content should start where the label WOULD start" asks for: the
 * number is the same whether a real label is rendered or not.
 *
 * `BlockPort` itself never touches a header's content (D-A1's own rule —
 * `Block` is composed from the outside) — this is the number a CALLER
 * applies to its own header content, e.g. as a `<Bar style={{ paddingLeft:
 * functionPortHeaderInsetPx(diameter) }}>`'s explicit inline override of
 * `Bar`'s own `px-3` gutter (bar.tsx's own public `style` escape hatch,
 * not a hardcoded pixel — see `BlockPort.stories.tsx`'s
 * `FunctionPortHeaderInset`).
 */
export function functionPortHeaderInsetPx(diameter: PortSize = "md"): number {
  const diameterPx = typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  return diameterPx / 2 + PORT_RING_OVERHANG_PX + PORT_LABEL_GAP;
}

/* ------------------------------------------------------------------ */
/* The band a rail needs — the inverse of the clamp                    */
/* (moved here verbatim from `scene/fitToContent.ts`, which re-exports) */
/* ------------------------------------------------------------------ */

export interface RailBandMetrics {
  /** Main-axis size of one slot box. Default: the rail's own slot size. */
  slotMainPx?: number;
  /** The port-to-port gap the band must be able to afford. */
  gapPx?: number;
  /** `RailPlan.endMarginPx` — the inset applied at BOTH ends of the rail's
   *  content box. Zero for a body-band rail, `RAIL_END_MARGIN_PX` for a
   *  wall-spanning one. */
  endMarginPx?: number;
  /**
   * The rail's own `Distribution`. Omit for `aligned`, which is port
   * view's left/right-only default.
   *
   * WHY this is a parameter at all — a finding, not a guess: the required
   * band is NOT the same for every distribution, because the space-*
   * schemes spend some of the band on END gaps that `aligned` does not
   * have. Sizing a band for `aligned` and then rendering it
   * `space-around` drops the real pitch from 42px to 33px, a silent 21%
   * squeeze — measured by `fitToContent.test.ts`'s
   * "holds the full pitch in EVERY distribution", which failed exactly
   * this way on its first run and is the reason this field exists.
   */
  distribution?: Distribution;
}

/**
 * How many gap-widths a distribution spends across `slotCount` boxes.
 *
 * Straight from CSS Box Alignment Level 3's normative definitions, already
 * quoted in `portEdge.layout.ts`'s `mainAxisPositions` docblock (spec read
 * 2026-09-17 at https://www.w3.org/TR/css-align-3/) — read the gap count
 * off each definition rather than re-deriving it:
 *
 *   • `aligned`       — a real flexbox `gap`, only BETWEEN boxes → n-1.
 *   • `space-between` — flush at both ends, gaps only between     → n-1.
 *   • `space-around`  — a HALF gap at each end (two halves = one)  → n.
 *   • `space-evenly`  — a FULL gap at each end                     → n+1.
 */
function gapCountFor(slotCount: number, distribution?: Distribution): number {
  if (slotCount <= 0) return 0;
  // `anchored` (`AnchoredConfig`) spends no end gaps either — its slots sit
  // at the host's own offsets — so it floors the band exactly as `aligned`
  // does; any wider spread the host's offsets need is the host's to size.
  if (distribution == null || distribution.mode !== "distribute") return slotCount - 1;
  switch (distribution.scheme) {
    case "space-between":
      return slotCount - 1;
    case "space-around":
      return slotCount;
    case "space-evenly":
      return slotCount + 1;
  }
}

/**
 * The band height at which `slotCount` slots all keep their FULL pitch.
 *
 * ── The derivation, because it is the whole point of this function ──
 *
 * `blockPort.layout.ts`'s `railBoxFor` turns a band into a track box:
 *
 *     trackMain = (bandEnd - endMargin) - (bandStart + endMargin)
 *                 + 2 * RAIL_MAIN_INSET_PX
 *
 * and `portEdge.tsx`'s track then spends `CONTAINER_BORDER` +
 * `CONTAINER_PADDING` on each side before its first slot box. Since
 * `RAIL_MAIN_INSET_PX` is DEFINED as `CONTAINER_BORDER + CONTAINER_PADDING`
 * (blockPort.layout.ts:101), those two cancel exactly and the usable
 * content main is simply:
 *
 *     contentMain = band - 2 * endMargin
 *
 * `n` slot boxes at full pitch need `n*slot + (n-1)*gap`. Setting the two
 * equal and solving for the band gives the return value below.
 *
 * ── WHY: the coupling this docblock would otherwise only warn about ──
 *
 * The donor's own comment at `layoutBlock.ts:497-501` says it plainly:
 * "`layoutBlock` compresses `pitch` to whatever room is left, so adding a
 * port to a full box silently squeezes every existing row. This is the
 * exact inverse of that clamp and therefore lives beside it: any change to
 * the body's padding or to the footer has to move both numbers together or
 * neither."
 *
 * A comment cannot enforce that. So the cancellation above is pinned as a
 * ROUND-TRIP TEST instead (`fitToContent.test.ts`, "the RAIL_MAIN_INSET_PX
 * cancellation"): the test feeds this function's output through the REAL
 * `railBoxFor` and the REAL `CONTAINER_BORDER`/`CONTAINER_PADDING`, and
 * asserts the content main lands on exactly `n*slot + (n-1)*gap`. Change
 * `CONTAINER_PADDING` without `railBoxFor` following — or hardcode `16`
 * where `RAIL_MAIN_INSET_PX` belongs — and that test goes red instead of
 * this file quietly disagreeing with the renderer.
 *
 * Returns 0 for `slotCount <= 0`: an unpopulated edge imposes no floor at
 * all, which is what keeps `Block`'s "omit height to hug" contract intact
 * for every Block that has no ports (see `resolveBlockHeight`).
 */
export function railBandHeightForSlots(slotCount: number, metrics: RailBandMetrics = {}): number {
  const { slotMainPx = PORT_EDGE_SLOT_MIN_PX, gapPx = RAIL_GAP_PX, endMarginPx = 0, distribution } = metrics;
  if (slotCount <= 0) return 0;
  return slotCount * slotMainPx + gapCountFor(slotCount, distribution) * gapPx + 2 * endMarginPx;
}

/* ------------------------------------------------------------------ */
/* minBlockHeightFor — the floor a Block's ports impose on its height  */
/* ------------------------------------------------------------------ */

export interface MinBlockHeightInput {
  view: BlockView;
  /** Port view only; ignored elsewhere, exactly as `railPlanFor` ignores it. */
  portLayout?: BlockPortLayout;
  /** Port COUNT per wall. Top/bottom walls never set a height floor — their
   *  rails run along the width — but they are still read, because a
   *  populated top/bottom wall switches port view's side rails to
   *  `space-around` (E-3), which needs more band than `aligned`. */
  ports: Partial<Record<BlockSide, number>>;
  /** Defaults to `view === "simple"`, `BlockPort`'s own default. */
  collapsePorts?: boolean;
  /** A caller's explicit per-wall `distribution` — `BlockEdgeSpec.
   *  distribution`, the one field of the plan a caller may reach past. */
  distributions?: Partial<Record<BlockSide, Distribution>>;
  /** MEASURED header band, px (block top → body top). 0 when headerless. */
  headerPx?: number;
  /** MEASURED footer band, px (body bottom → block bottom). 0 when footerless. */
  footerPx?: number;
}

/**
 * The shortest box a Block can have without a single port on its left or
 * right wall hanging past its bottom edge, px. 0 when neither side wall has
 * a port, so a portless Block keeps hugging.
 *
 * WHY: Zach, 2026-09-22 — "Please enforce a minimum height on the blocks …
 * that can be calculated from the minimum port spacing. You should never
 * have a rendering issue like this", on a `src` block whose third right-wall
 * port hung below the card. An `aligned` rail never compresses (its slots are
 * `flexShrink: 0`, see `railPitchForBand`), so a box shorter than its rail
 * does not squeeze the ports — it drops the last ones off the bottom. The
 * truthful-rendering rule forbids hiding or overlapping them, so the box
 * grows instead.
 *
 * WHY built from `railPlanFor` + `railBandHeightForSlots` and nothing else:
 * those are the SAME two functions the renderer places ports with (the
 * plan) and the fit-to-content floor sizes bands with (the band, pinned
 * against the real `railBoxFor` by a round-trip test). A floor that
 * restated the spacing would be a second copy of the rule, free to drift
 * the day `RAIL_GAP_PX` or a view rule changes. Per wall:
 *
 *   band   = edgePadding (an `offset` lane's push-down) +
 *            railBandHeightForSlots(slots, the plan's own margin + scheme)
 *   height = band                       for a `block`-band rail
 *          = header + band + footer     for a `body`-band rail
 *
 * and the Block's floor is the largest of those. A collapsed wall (simple
 * view) is ONE slot, whatever its count — that is what collapsing means.
 *
 * DEVIATION from the brief's "(max ports) × pitch", stated: that sum is
 * `n·(slot + gap)`, one gap MORE than the rail actually occupies (`n·slot +
 * (n−1)·gap` for `aligned`). This returns the rail's own length, so the floor
 * is exactly the box at which the last dot's slot meets the body's bottom
 * edge — never shorter (the bug), never an arbitrary gap taller.
 *
 * Provenance: class (c), ours — composition of this file's own two
 * functions; the rule it enforces is SystemSketch's
 * `blockPortViewHeightForSlots` (`layoutBlock.ts:495-517`), already cited by
 * `scene/fitToContent.ts`'s `blockPortViewMinHeight`, which is the
 * port-view-only special case of this function.
 */
export function minBlockHeightFor(input: MinBlockHeightInput): number {
  const { view, portLayout = "inline", ports, collapsePorts = view === "simple", distributions, headerPx = 0, footerPx = 0 } = input;
  const count = (side: BlockSide) => Math.max(0, ports[side] ?? 0);
  const populatedEdges = BLOCK_SIDES.filter((side) => count(side) > 0);
  let floor = 0;
  for (const edge of ["left", "right"] as const) {
    const n = count(edge);
    if (n === 0) continue;
    const plan = railPlanFor({
      view,
      portLayout,
      edge,
      itemIds: Array.from({ length: n }, (_, i) => `${edge}-${i}`),
      leadCount: count("left"),
      collapsePorts,
      populatedEdges,
    });
    const distribution = distributions?.[edge] ?? plan.distribution;
    // An `aligned` rail spends its OWN gap and push-down; a distributed one
    // has neither, and is floored at the Block's rail gap (the full pitch —
    // `railBandHeightForSlots`' own "holds the full pitch in EVERY
    // distribution" finding).
    //
    // A LONE dot — a collapsed wall, or a wall with one port — has no
    // neighbour to keep a pitch from, so it needs one slot and none of a
    // space-* scheme's END gaps: `space-evenly` would otherwise demand
    // 24 + 2·18 = 60px for a single centred dot and inflate a 46px value
    // capsule into a circle (measured on the tldraw scene bench).
    const aligned = distribution.mode === "aligned" ? distribution : null;
    const slots = plan.collapsed ? 1 : n;
    const band =
      (aligned?.edgePadding ?? 0) +
      (slots === 1
        ? railBandHeightForSlots(1, { endMarginPx: plan.endMarginPx })
        : railBandHeightForSlots(slots, {
            endMarginPx: plan.endMarginPx,
            distribution,
            ...(aligned ? { gapPx: aligned.gap } : null),
          }));
    floor = Math.max(floor, plan.band === "body" ? headerPx + band + footerPx : band);
  }
  return floor;
}

/**
 * The `min-height` a Block gets once its port floor is applied on top of
 * whatever its caller already asked for: the LARGER of the two. A caller's
 * `style={{ minHeight: 300 }}` must survive a 146px floor — the floor only
 * ever raises a box (`resolveBlockHeight`'s "floored, never overridden").
 * A non-numeric caller value (`"10rem"`, `"50%"`, `calc(…)`) cannot be
 * compared here, so CSS compares it: `max(10rem, 146px)`.
 *
 * WHY a keyword gets the floor alone (re-judge of d97f5ec, 2026-09-22):
 * CSS `max()` takes lengths, percentages and math, never a keyword. An
 * intrinsic keyword (`auto`, `min-content`, `max-content`, `fit-content`,
 * `fit-content(…)`) or a CSS-wide one (`inherit`, `initial`, `unset`,
 * `revert`, `revert-layer`) inside it makes the whole declaration invalid,
 * so the browser DROPS it and both the caller's value and the port floor
 * are lost — the one thing this function exists to guarantee. The floor px
 * is kept instead: a keyword `min-height` asks the box to hug its content,
 * and a Block's `height` is still content-sized, so content taller than the
 * floor still grows it; what the keyword cannot do is fall below the ports.
 */
export function floorMinHeight(callerMinHeight: number | string | undefined, floorPx: number): number | string {
  if (callerMinHeight === undefined || callerMinHeight === "") return floorPx;
  if (typeof callerMinHeight === "number") return Math.max(callerMinHeight, floorPx);
  if (!CSS_MATH_OPERAND.test(callerMinHeight.trim())) return floorPx;
  return `max(${callerMinHeight}, ${floorPx}px)`;
}

/** A value CSS `max()` accepts as an operand: a length or percentage
 *  (`0`, `10rem`, `50%`, `-2.5px`) or a math/substitution function
 *  (`calc`, `min`, `max`, `clamp`, `var`, `env`). Everything else — every
 *  keyword, and `fit-content(…)`, which is a sizing function, not math —
 *  is not. */
const CSS_MATH_OPERAND = /^(?:0|[+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?(?:%|[a-z]+))$|^(?:calc|min|max|clamp|var|env)\(.*\)$/i;

"use client";

/**
 * src/components/blockPort.tsx — `BlockPort`: a Block with real
 * `PortEdge` rails mounted on its walls (docs/BLOCK-PORT-EDGES-PLAN.md §2,
 * phase A1).
 *
 * Zach, 2026-09-17: "the port edge is literally just a line. **its Z level
 * should be above the block.** The classic is the input output dag view — we
 * should put a port edge on the left body edge and one on the right body
 * edge."
 *
 * WHY a wrapper and not new `Block` props (D-A1): `Block`'s root IS the
 * `overflow-hidden rounded-lg` card (block.tsx:100-103). A rail drawn inside
 * it is clipped at the border — and a rail's dots deliberately STRADDLE the
 * border line, so half of every dot, the whole 40px hit halo, and the lane
 * overlay would vanish. Giving Block an outer wrapper div would instead
 * change its DOM contract under every landed story (`[data-slot="block"]`
 * box assertions, CollapsibleHeader's height-shrink check). So `Block` stays
 * a stock seam, untouched, and this wrapper owns the overlay geometry.
 * Reversible: if a host ever wants `<Block ports>`, this body folds in
 * behind a prop.
 *
 * WHY the rails paint ABOVE the block, reversing the donor (D-B1):
 * SystemSketch pins cables UNDER blocks (`keepConnectionsAtBottom.ts`:
 * "Cables paint under Blocks, per parent"). Zach's brief says the opposite
 * for this component, and it has to be the opposite — a wire attaches to a
 * dot that sits on the wall, so a dot painting under the block would have
 * its inner half swallowed by the card.
 *
 * WHAT ACTUALLY IMPLEMENTS IT — corrected against the plan, which says "DOM
 * order is the z-rule; the explicit index exists solely so the lane overlay
 * stacks". Measured, that is not the mechanism. The rail is ABSOLUTELY
 * POSITIONED and the Block is static, so the rail already paints in CSS's
 * positioned-descendants step, after every step the static Block's
 * background and content occupy — DOM order never enters into it, because
 * the two are not at the same painting step. Proven by mutation: rendering
 * the rails BEFORE `children` leaves the hit test green, and only
 * `zIndex: -1` (the donor's posture) turns it red. So `zIndex: 1` is doing
 * real work — it is what a future `position: static` rail, or a Block that
 * grows its own stacking context, would still be held up by — and it is
 * additionally what lets the lane overlay's `zIndex: 5` clear block content
 * (D-A6). DOM order is kept as a third, redundant guarantee, and asserted
 * as a structural invariant by `StackingAboveBlock`. Do not "fix" any of
 * the three back to the donor.
 *
 * WHAT IS NOT HERE, on purpose: no layout engine. Every placement rule is a
 * `PortEdge` prop combination computed by `./blockPort.layout.ts`; the
 * donor's `layoutBlock.ts` is the spec for the behaviour and the source of
 * exactly zero lines. No wires either — `Trace` and the wire layer are
 * Group B, and no file in Group A imports them.
 *
 * WHY this is its own component and not `Block` itself (the reciprocal of
 * block.tsx's own note): Zach, 2026-09-17 — "just the Block itself can be
 * used even without the ports" and this is "starting to add more and more
 * things to" — a plain Block should stay exactly a header/body/footer card.
 * `Block` stays a stock seam this file composes from the outside, never a
 * file this one edits.
 */
