/* BlockPort                                                         */
/* ------------------------------------------------------------------ */

export function BlockPort({
  children,
  view,
  portLayout = "inline",
  edges,
  collapsePorts,
  diameter,
  id,
  functionPort = false,
  variant,
  sideEffects,
  mutations,
}: BlockPortProps) {
  const wrapperRef = useRef<HTMLDivElement | null>(null);
  const collapse = collapsePorts ?? view === "simple";

  const populated = BLOCK_SIDES.filter((side) => (edges[side]?.items.length ?? 0) > 0);
  // Re-measure whenever anything that can move a band changes. Counts are in
  // the key because a rail's own length depends on them through the view
  // rule, and `ResizeObserver` fires on the BLOCK's box — which does not
  // move when only a rail does.
  const layoutKey = [view, portLayout, String(collapse), ...BLOCK_SIDES.map((s) => `${s}:${edges[s]?.items.length ?? 0}`)].join("|");
  const bands = useBlockBands(wrapperRef, layoutKey);

  // The lane the `offset` rule pushes the trailing lane below (donor:
  // `outputStart = slot + inputs.length`, i.e. the INPUT count).
  const leadCount = edges.left?.items.length ?? 0;

  // The floor the walls' ports impose (`minBlockHeightFor`), from the
  // MEASURED header/footer bands and the same plan the rails are placed
  // with. Handed to the Block as a CSS `min-height`, so an authored or
  // stored `height` that is too short renders clamped UP and every other
  // height is untouched.
  //
  // WHY: Zach, 2026-09-22 — "Please enforce a minimum height on the blocks
  // … that can be calculated from the minimum port spacing. You should never
  // have a rendering issue like this", on a port hanging below its block.
  // WHY here, once, rather than in each host: every host (DOM canvas, React
  // Flow node, tldraw bench, the SystemSketch app's `ss-block`) mounts its
  // Block inside a `BlockPort`, and this is the one place that already
  // knows both the walls and the measured bands. WHY `min-height` and not a
  // replaced `height`: a floor RAISES a short box and leaves a taller one
  // alone (`resolveBlockHeight`'s own rule) — a deliberately tall block is
  // never "corrected". Growing the box is the truthful-rendering answer;
  // clipping or overlapping the ports is not.
  //
  // Depends only on header/footer, never on the Block's own height, so the
  // clamp cannot feed back into itself: measure → floor → grow → re-measure
  // yields the same floor.
  const floorPx = bands
    ? minBlockHeightFor({
        view,
        portLayout,
        collapsePorts: collapse,
        ports: Object.fromEntries(BLOCK_SIDES.map((side) => [side, edges[side]?.items.length ?? 0])),
        distributions: Object.fromEntries(
          BLOCK_SIDES.flatMap((side) => (edges[side]?.distribution ? [[side, edges[side]!.distribution!]] : [])),
        ),
        headerPx: bands.bodyTop - bands.blockTop,
        footerPx: bands.blockTop + bands.blockHeight - bands.bodyBottom,
      })
    : 0;
  // `cloneElement` adds ONE style key to the caller's own element and
  // changes nothing else about it — `children` stays "composed, never rebuilt
  // from props" (`BlockPortProps.children`). `Block` spreads its caller's
  // `style` last, so this lands on its root.
  const floored =
    floorPx > 0 && isValidElement<{ style?: CSSProperties }>(children)
      ? cloneElement(children as ReactElement<{ style?: CSSProperties }>, {
          // Never LOWER a caller's own larger `minHeight` — the floor only
          // ever raises (`floorMinHeight`).
          style: {
            ...(children.props as { style?: CSSProperties }).style,
            minHeight: floorMinHeight((children.props as { style?: CSSProperties }).style?.minHeight, floorPx),
          },
        })
      : children;

  const mutationSplit = partitionMutations(
    mutations,
    sideEffects,
    (edges.left?.items ?? []).map((item) => item.id),
  );

  // "Multiple returns": every populated edge that carries at least one
  // sanitized divider position, gathered once here so
  // `BlockPortReturnDividers` never has to re-derive `populated` or reach
  // back into `edges` itself.
  const returnDividerEdges = populated
    .map((side) => {
      const spec = edges[side]!;
      const sanitized = sanitizeDividers(spec.dividerAfter ?? [], spec.items.length);
      return sanitized.length > 0 ? { edge: side, dividerAfter: sanitized } : null;
    })
    .filter((entry): entry is { edge: BlockSide; dividerAfter: number[] } => entry != null);

  return (
    <div
      data-slot="block-port"
      data-view={view}
      data-port-layout={portLayout}
      data-block-id={id}
      data-unresolved-mutations={mutations ? mutationSplit.unresolved.map((link) => `${link.from}→${link.to}`).join(",") : undefined}
      ref={wrapperRef}
      // The isolation invariant (paintOrder.ts): this wrapper emits the
      // `portDot` tier below (the function port and every rail), so it
      // must wall that off from anything outside it, same reasoning as
      // Block's own root.
      style={{ ...ISOLATED_ROOT_STYLE, position: "relative", width: "max-content" }}
    >
      {floored}
      {bands &&
        populated.map((side) => {
          const spec = edges[side]!;
          const plan = railPlanFor({
            view,
            portLayout,
            edge: side,
            itemIds: spec.items.map((i) => i.id),
            leadCount,
            collapsePorts: collapse,
            // E-3: the whole block's populated set, not just `side` — see
            // blockPort.layout.ts's own note on why a single edge cannot
            // decide this alone.
            populatedEdges: populated,
          });
          // E-3: an explicit caller `distribution` always wins over the
          // population default above — the one field of the derived plan a
          // caller may reach past (`BlockEdgeSpec.distribution`'s own doc).
          const finalPlan = {
            ...plan,
            ...(spec.distribution ? { distribution: spec.distribution } : null),
            ...(spec.groups !== undefined ? { groups: spec.groups } : null),
            ...(spec.groupMode !== undefined ? { groupMode: spec.groupMode } : null),
            // `BlockEdgeSpec.band`'s own seam: an explicit per-edge band
            // always wins over the view rule's derived one.
            band: spec.band ?? plan.band,
          };
          return <BlockPortRail key={side} edge={side} spec={spec} plan={finalPlan} bands={bands} diameter={diameter} variant={variant} />;
        })}
      {bands && functionPort && <BlockFunctionPort bands={bands} diameter={diameter} variant={variant} />}
      {bands && hasSideEffects(sideEffects) && <BlockSideEffectRail effects={sideEffects!} bands={bands} diameter={diameter} variant={variant} />}
      {bands && mutationSplit.resolved.length > 0 && (
        <MutationLines wrapperRef={wrapperRef} links={mutationSplit.resolved} bands={bands} measureKey={layoutKey} />
      )}
      {bands && returnDividerEdges.length > 0 && (
        <BlockPortReturnDividers wrapperRef={wrapperRef} view={view} bands={bands} edgeSpecs={returnDividerEdges} measureKey={layoutKey} />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Side effects — the top wall's own row                               */
/* ------------------------------------------------------------------ */

/**
 * Every side-effect dot and the divider tick, on the Block's top border
 * line. Positions come from `sideEffectWallLayout` alone.
 *
 * WHY this element is stamped `data-slot="block-port-rail"` +
 * `data-edge="top"` although it is not a `PortEdge`: that pair is the
 * kit's one published answer to "which wall is this dot on", and three
 * readers already ask it — `wireLayer.tsx`'s `railEdgeOf` (a wire leaves
 * or arrives along the wall's normal), `hosts/portDotSightings.ts`, and
 * the drag policy's `"block-port-rail": "owns-pointer"`. Stamped, an
 * effect dot is wireable, host-resolvable and pointer-owning with zero
 * code in any of them. `data-rail-kind` is what tells the two kinds of
 * top-wall row apart for anyone who needs to.
 *
 * WHY it paints at `portDot`, above the Block, like every rail: the dots
 * straddle the border and the labels and divider sit wholly OUTSIDE it,
 * so inside the Block's `overflow: clip` card they would be cut in half
 * or vanish, and under the header chrome they would not be hittable.
 */
function BlockSideEffectRail({
  effects,
  bands,
  diameter,
  variant,
}: {
  effects: BlockSideEffects;
  bands: BlockBands;
  diameter?: PortSize;
  variant?: PortVariantId;
}) {
  const inputs = effects.inputs ?? [];
  const outputs = effects.outputs ?? [];
  const layout = sideEffectWallLayout(bands.blockWidth, inputs.length, outputs.length);
  return (
    <div
      data-slot="block-port-rail"
      data-edge="top"
      data-rail-kind="side-effects"
      style={{ position: "absolute", left: bands.blockLeft, top: bands.blockTop, width: bands.blockWidth, height: 0, zIndex: paintTier("portDot") }}
    >
      <SideEffectDivider x={layout.dividerX} />
      {inputs.map((effect, index) => (
        <SideEffectDot key={effect.id} effect={effect} direction="input" x={layout.inputXs[index]} diameter={diameter} variant={variant} />
      ))}
      {outputs.map((effect, index) => (
        <SideEffectDot key={effect.id} effect={effect} direction="output" x={layout.outputXs[index]} diameter={diameter} variant={variant} />
      ))}
    </div>
  );
}

/**
 * One side-effect dot, centred on the wall line at `x`. The holder is
 * EXACTLY the dot's box (the label is absolutely positioned off it, the
 * same pattern as `renderCollapsed`'s count below), so a wire resolving
 * `[data-port-id]` measures the dot's own centre and nothing else.
 */
function SideEffectDot({
  effect,
  direction,
  x,
  diameter,
  variant,
}: {
  effect: SideEffectPort;
  direction: SideEffectDirection;
  x: number;
  diameter?: PortSize;
  variant?: PortVariantId;
}) {
  return (
    <span
      data-slot="block-side-effect"
      data-side-effect-direction={direction}
      data-port-id={effect.id}
      style={{ position: "absolute", left: x, top: 0, display: "flex", transform: "translate(-50%, -50%)" }}
    >
      <Port state={effect.state ?? "empty"} diameter={diameter} variant={variant} />
      {effect.label !== undefined && (
        <span
          data-slot="block-side-effect-label"
          style={{
            position: "absolute",
            // Beside the dot and wholly above the wall: its bottom edge
            // clears the wall line (the dot's own centre) by the ring's
            // overhang, and it starts past the dot's painted ring.
            //
            // WHY an input's label reads LEFT of its dot and an output's
            // RIGHT: both grow AWAY from the divider. Measured on the
            // gallery, an input label written rightward ("input port" at
            // the quarter point of a 240px wall) ran straight through the
            // divider tick into the outputs' half — the one ambiguity the
            // divider exists to remove.
            ...(direction === "input" ? { right: `calc(100% + ${PORT_RING_OVERHANG_PX + 2}px)` } : { left: `calc(100% + ${PORT_RING_OVERHANG_PX + 2}px)` }),
            bottom: `calc(50% + ${PORT_RING_OVERHANG_PX}px)`,
            fontSize: 11,
            lineHeight: 1,
            // `pre`, not `nowrap`: every authored character — a double
            // space included — survives exactly as typed.
            whiteSpace: "pre",
            color: "var(--foreground)",
            pointerEvents: "none",
          }}
        >
          {effect.label}
        </span>
      )}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* Mutation lines — drawn INSIDE the Block, under its content           */
/* ------------------------------------------------------------------ */

/** The dot a mutation end sits on, owned by THIS wrapper (never a member's
 *  own nested BlockPort — the same ownership rule `wireLayer.tsx`'s
 *  `resolveDot` applies). */
function ownDot(wrapper: HTMLElement, selector: string): HTMLElement | null {
  for (const holder of wrapper.querySelectorAll<HTMLElement>(selector)) {
    if (holder.closest('[data-slot="block-port"]') !== wrapper) continue;
    return holder.querySelector<HTMLElement>('[data-slot="port-dot"]');
  }
  return null;
}

interface DrawnMutation {
  link: MutationLink;
  route: MutationRoute;
}

function sameRoutes(a: DrawnMutation[], b: DrawnMutation[]): boolean {
  return (
    a.length === b.length &&
    a.every(
      (drawn, i) =>
        drawn.link.from === b[i].link.from &&
        drawn.link.to === b[i].link.to &&
        drawn.route.points.every((p, j) => Math.abs(p.x - b[i].route.points[j].x) < 0.25 && Math.abs(p.y - b[i].route.points[j].y) < 0.25),
    )
  );
}

/**
 * Every resolved mutation link as a dotted orthogonal line with a small
 * arrowhead at the effect end, routed by `mutationRoute`.
 *
 * WHY it is portalled INTO the Block, at the `underlay` tier, when every
 * other thing this wrapper draws sits beside the Block above it: the line
 * runs through the Block's interior, and in an expanded Block that
 * interior is member cards. Drawn in this wrapper it could only paint
 * wholly above the Block (over every member) or wholly below it (under the
 * card's own opaque surface, i.e. invisible) — the Block is an isolated
 * root, so nothing outside it can slot in between its surface and its
 * content. Inside it, a negative tier paints after the card's own
 * background and before the header, body and members, so the line reads
 * on the card and disappears behind a member, never across one.
 *
 * Measured, not computed: both ends are rendered dots whose position the
 * rail and the side-effect row already decided, so reading them back is
 * the one derivation (the rule `wireLayer.tsx` states for itself: it never
 * invents a point). Coordinates are the Block's PADDING box, which is what
 * an absolutely-positioned child of it is laid out against.
 */
function MutationLines({
  wrapperRef,
  links,
  bands,
  measureKey,
}: {
  wrapperRef: RefObject<HTMLDivElement | null>;
  links: MutationLink[];
  bands: BlockBands;
  measureKey: string;
}) {
  const [block, setBlock] = useState<HTMLElement | null>(null);
  const [routes, setRoutes] = useState<DrawnMutation[]>([]);
  const linkKey = links.map((link) => `${link.from}>${link.to}`).join(",");

  useLayoutEffect(() => {
    const wrapper = wrapperRef.current;
    if (!wrapper) return;
    const blockElement = wrapper.querySelector<HTMLElement>('[data-slot="block"]');
    setBlock(blockElement);
    if (!blockElement) return;

    const measure = () => {
      const blockRect = blockElement.getBoundingClientRect();
      const originX = blockRect.left + blockElement.clientLeft;
      const originY = blockRect.top + blockElement.clientTop;
      const next: DrawnMutation[] = [];
      for (const link of links) {
        const fromDot = ownDot(wrapper, `[data-slot="block-port-rail"][data-edge="left"] [data-port-id="${link.from}"]`);
        const toDot = ownDot(wrapper, `[data-slot="block-side-effect"][data-port-id="${link.to}"]`);
        if (!fromDot || !toDot) continue;
        const fromRect = fromDot.getBoundingClientRect();
        const toRect = toDot.getBoundingClientRect();
        next.push({
          link,
          route: mutationRoute(
            { x: fromRect.left + fromRect.width / 2 - originX, y: fromRect.top + fromRect.height / 2 - originY },
            { x: toRect.left + toRect.width / 2 - originX, y: toRect.top + toRect.height / 2 - originY },
            fromRect.width / 2,
            toRect.height / 2,
          ),
        });
      }
      setRoutes((previous) => (sameRoutes(previous, next) ? previous : next));
    };

    // The rails' dots land one pass after `bands` does (the same race
    // `wireLayer.tsx` documents), so measure now AND once more next frame.
    measure();
    const frame = requestAnimationFrame(measure);
    const observer = new ResizeObserver(measure);
    observer.observe(wrapper);
    observer.observe(blockElement);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wrapperRef, bands, measureKey, linkKey]);

  if (!block || routes.length === 0) return null;
  return createPortal(
    <svg
      data-slot="block-mutation-lines"
      aria-hidden
      width="100%"
      height="100%"
      style={{ position: "absolute", left: 0, top: 0, overflow: "visible", pointerEvents: "none", zIndex: paintTier("underlay") }}
    >
      {routes.map(({ link, route }) => (
        <MutationLineMark key={`${link.from}>${link.to}`} from={link.from} to={link.to} route={route} />
      ))}
    </svg>,
    block,
  );
}

/* ------------------------------------------------------------------ */
/* Return dividers — "multiple returns" (Daily Note 2026-09-22): the       */
/* union-return-type mark between two groups of output ports.              */
/* ------------------------------------------------------------------ */

/**
 * FIXED (judge finding 4, 2026-09-22): this used to be scoped to COLUMN-axis
 * edges (left/right) only — every one of Zach's sketches draws the mark on
 * the right wall — and silently drew NOTHING for a `dividerAfter` set on a
 * row edge (top/bottom), which is the actual defect: `PortEdge`/`BlockPort`
 * both accept `dividerAfter` on any `BlockSide`, so a caller had no way to
 * learn a top/bottom rail's dividers were being thrown away short of
 * noticing the missing pixels. Axis-aware turned out to be the "small step"
 * the finding asked to prefer: the geometry is a 90° rotation of the
 * column-axis case (swap which coordinate is "along the wall" vs "across
 * it"), not a new drawing, so every wall now renders — see
 * `BlockPortReturnDividers`'s own doc for the two drawings' formulas on
 * both axes.
 */

/**
 * Measures the REAL rendered dot centres either side of each divider —
 * D-A5's own reasoning (`useBlockBands`'s doc): there is no closed form for
 * "where two dots ended up" the way there is for the rail's own pitch
 * (labels wrap, distributions differ), so this reads the DOM the same way
 * `GroupSlotBody`'s `useEnclosingCircleBox` and `MutationLines` already do
 * for their own marks, via the exported `railDotCentres` this file already
 * ships for stories to assert against.
 *
 * `at` is the divider's position ALONG the wall, wrapper-local: the
 * midpoint of the two flanking dots' Y centres on a column edge (left/
 * right), or their X centres on a row edge (top/bottom) — whichever
 * coordinate the rail's own main axis actually varies.
 */
function useReturnDividerRows(
  wrapperRef: RefObject<HTMLDivElement | null>,
  edgeSpecs: { edge: BlockSide; dividerAfter: number[] }[],
  measureKey: string,
): { edge: BlockSide; at: number }[] {
  const [rows, setRows] = useState<{ edge: BlockSide; at: number }[]>([]);
  const specKey = edgeSpecs.map((s) => `${s.edge}:${s.dividerAfter.join(",")}`).join("|");

  useLayoutEffect(() => {
    const wrapper = wrapperRef.current;
    if (!wrapper || edgeSpecs.length === 0) {
      setRows((prev) => (prev.length === 0 ? prev : []));
      return;
    }
    const measure = () => {
      const wrapperRect = wrapper.getBoundingClientRect();
      const next: { edge: BlockSide; at: number }[] = [];
      for (const spec of edgeSpecs) {
        const rail = wrapper.querySelector<HTMLElement>(`[data-slot="block-port-rail"][data-edge="${spec.edge}"]`);
        if (!rail) continue;
        const centres = railDotCentres(rail);
        const axis = railAxisFor(spec.edge);
        for (const index of spec.dividerAfter) {
          const a = centres[index];
          const b = centres[index + 1];
          if (!a || !b) continue;
          const at = axis === "column" ? (a.y + b.y) / 2 - wrapperRect.top : (a.x + b.x) / 2 - wrapperRect.left;
          next.push({ edge: spec.edge, at });
        }
      }
      setRows((prev) =>
        prev.length === next.length && prev.every((p, i) => p.edge === next[i].edge && Math.abs(p.at - next[i].at) < 0.25) ? prev : next,
      );
    };
    measure();
    // Same race `MutationLines` documents: a rail's own dots land one pass
    // after `bands` does.
    const frame = requestAnimationFrame(measure);
    const observer = new ResizeObserver(measure);
    observer.observe(wrapper);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wrapperRef, measureKey, specKey]);

  return rows;
}

/**
 * Two drawings of ONE mark, decided by `view` — Zach's own words (Daily
 * Note 2026-09-22, "Multiple returns"), generalized to every wall (finding
 * 4, see this section's own header note for why axis-aware rather than a
 * runtime rejection):
 *
 *  - Expanded: "a | in the output type hint corresponds to a little dash on
 *    the outside" — a short dash OUTSIDE the wall. Length and stroke are
 *    `SIDE_EFFECT_DIVIDER_PX`/`2`, `sideEffectMarks.tsx`'s `SideEffectDivider`
 *    own numbers for its OWN "little grey line on the outside" (Zach's
 *    phrase for that mark too) — the same idiom, reused rather than a
 *    second invented size. Inset is 0: like that divider's own foot, this
 *    one starts flush ON the wall line and sticks OUTWARD from there — "on
 *    the outside" needs no further push-in. On a column edge (left/right)
 *    that dash is HORIZONTAL, sized `SIDE_EFFECT_DIVIDER_PX × 2`; on a row
 *    edge (top/bottom) it is the 90°-rotated twin, `2 × SIDE_EFFECT_DIVIDER_PX`
 *    — the same two numbers, the axes swapped.
 *  - Port view: "the line going to half way of the width of the block" — a
 *    line from the wall inward to `bands.blockWidth / 2` on a column edge, a
 *    MEASURED formula (never a stored constant — a Block has no fixed
 *    width) that lands the inner end exactly on the block's own vertical
 *    centre line. A row edge has no sketch to cite, so this is the file's
 *    own symmetric extension of the SAME rule ("to the block's own centre
 *    line") rather than a second one: the line runs inward to
 *    `bands.blockHeight / 2`, landing on the block's HORIZONTAL centre line
 *    instead. Stroke 1px either way, matching `EdgeLineMark`'s own
 *    dev-guide line weight — this is a thin rule INSIDE the block, not a
 *    tick standing off it.
 *
 * Neither drawing is a `PortEdge` slot: no id, no dot, no `data-port-id` —
 * so `wireLayer.tsx`'s `resolveDot` (which only ever looks for
 * `[data-port-id]`) can never resolve a wire onto one. `data-slot`
 * (`block-port-return-divider`) is one name for the mark; `data-mark-view`
 * tells the two drawings apart and keeps this mark structurally distinct
 * from the unrelated full-width rule that separates MEMBER sections
 * (`block.tsx`'s own header/footer `border-b`/`border-t`) — different
 * `data-slot`, different length, different reason to exist.
 */
function BlockPortReturnDividers({
  wrapperRef,
  view,
  bands,
  edgeSpecs,
  measureKey,
}: {
  wrapperRef: RefObject<HTMLDivElement | null>;
  view: BlockView;
  bands: BlockBands;
  edgeSpecs: { edge: BlockSide; dividerAfter: number[] }[];
  measureKey: string;
}) {
  const rows = useReturnDividerRows(wrapperRef, edgeSpecs, measureKey);
  // Simple view collapses every wall to one stand-in dot — there is no
  // "between two ports" left to mark. Only Expanded and Port view ever draw
  // this (the two drawings this function's own doc names); nothing else is
  // improvised for `view === "simple"`.
  if (view === "simple" || rows.length === 0) return null;

  return (
    <>
      {rows.map((row, index) => {
        const axis = railAxisFor(row.edge);
        // The wall this divider sits on is at the TRAILING coordinate
        // (right/bottom) for those two edges, the LEADING one (left/top)
        // for the other two — the "which side of the block" fact every
        // rail already keys off (`railBoxFor`'s own `edge === "right" ? …`
        // pattern, generalized to `bottom` the same way).
        const trailing = row.edge === "right" || row.edge === "bottom";
        const wallCoord =
          axis === "column"
            ? trailing
              ? bands.blockLeft + bands.blockWidth
              : bands.blockLeft
            : trailing
              ? bands.blockTop + bands.blockHeight
              : bands.blockTop;

        // Position/size ONLY — the paint (`background`) is
        // `ReturnDividerMark`'s own (`returnDividerMarks.tsx`'s header:
        // `skin.test.ts`'s S4 coverage holds this file to "paints nothing
        // of its own").
        if (view === "expanded") {
          const outStart = trailing ? wallCoord : wallCoord - SIDE_EFFECT_DIVIDER_PX;
          const style: CSSProperties =
            axis === "column"
              ? { position: "absolute", left: outStart, top: row.at - 1, width: SIDE_EFFECT_DIVIDER_PX, height: 2, zIndex: paintTier("portDot") }
              : { position: "absolute", top: outStart, left: row.at - 1, height: SIDE_EFFECT_DIVIDER_PX, width: 2, zIndex: paintTier("portDot") };
          return <ReturnDividerMark key={`${row.edge}-${index}`} edge={row.edge} markView="expanded" style={style} />;
        }
        // Port view: from the wall inward to half the block's OWN
        // dimension ALONG the line's run — width for a column edge
        // (Zach's own sketch), height for a row edge (this function's own
        // symmetric extension — see its doc).
        const halfSpan = axis === "column" ? bands.blockWidth / 2 : bands.blockHeight / 2;
        const inStart = trailing ? wallCoord - halfSpan : wallCoord;
        const style: CSSProperties =
          axis === "column"
            ? { position: "absolute", left: inStart, top: row.at - 0.5, width: halfSpan, height: 1, zIndex: paintTier("portDot") }
            : { position: "absolute", top: inStart, left: row.at - 0.5, height: halfSpan, width: 1, zIndex: paintTier("portDot") };
        return <ReturnDividerMark key={`${row.edge}-${index}`} edge={row.edge} markView="port" style={style} />;
      })}
    </>
  );
}

/* ------------------------------------------------------------------ */
/* The function port — the header's pin 1                              */
/* ------------------------------------------------------------------ */

/**
 * Renders the header's single reserved port, positioned by
 * `functionPortCenterPx` alone — no `PortEdge`, no rail, no distribution.
 * `LabeledPort` with `labelSlot={null}` is the donor-decided shape ("make
 * that a labeled port, just without a label for now, or disable the
 * label" — Zach, 2026-09-17): the label slot exists in the DOM contract
 * from day one, present-but-empty, so a real label is later one prop
 * change here, not a second component.
 */
function BlockFunctionPort({ bands, diameter, variant }: { bands: BlockBands; diameter?: PortSize; variant?: PortVariantId }) {
  const center = functionPortCenterPx(bands);
  if (center == null) return null;
  return (
    <div
      data-slot="block-port-function"
      // WHY `display: flex` (lane `ports`, 2026-09-19): as a plain block this
      // holder was a LINE BOX — 24px tall from the inherited strut, with the
      // port sitting on its baseline — so `translate(-50%, -50%)` centred
      // the line, not the dot. The 12px `md` dot happened to land at the
      // line's middle; the 6px default landed 3px low (measured). A flex
      // holder is exactly the port's own box, so the translate centres the
      // dot at any diameter.
      style={{ position: "absolute", display: "flex", left: center.x, top: center.y, transform: "translate(-50%, -50%)", zIndex: paintTier("portDot") }}
    >
      <LabeledPort edge="left" diameter={diameter} variant={variant} labelSlot={null} />
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* One rail                                                            */
/* ------------------------------------------------------------------ */

/**
 * Exported (lane `collapsed-members`, 2026-09-22) so `blockPortMembers.tsx`
 * can mount a collapsed member's rail on its PARENT's wall with this exact
 * fill — the same `data-port-id` stamp, the same `LabeledPort` — instead of
 * a second copy of it. `BlockPort` itself is unchanged.
 */
export function BlockPortRail({
  edge,
  spec,
  plan,
  bands,
  diameter,
  variant,
}: {
  edge: BlockSide;
  spec: BlockEdgeSpec;
  plan: RailPlan;
  bands: BlockBands;
  diameter?: PortSize;
  variant?: PortVariantId;
}) {
  const box = railBoxFor(edge, plan, bands);
  const axis = railAxisFor(edge);

  // Just a default — the wrapper deliberately adds no gating of its own.
  // `laneAvailability` already refuses a lane a wall cannot host (a
  // collapsed real family, i.e. exactly simple view) and D12/A12 already
  // closes one whose availability lapses mid-edit. Re-deciding that here
  // would be a second, divergent copy of a predicate PortEdge owns; A2
  // re-proves the lane ON a rail rather than re-implementing its gate.
  const editing = spec.editing ?? false;

  /**
   * The default fill. Two jobs beyond `PortEdge`'s own default: stamp
   * `data-port-id` (plan §5 — how a wire end resolves to a dot), and, in a
   * collapsed view, draw the donor's bare label-less midpoint dot instead
   * of a labelled port.
   *
   * The one-member collapsed case comes through HERE rather than through
   * `renderCollapsed`, because a groups line naming a single id is dropped
   * by the parser (a group of one is just an ungrouped port) — so a
   * one-port wall never reaches the collapsed branch at all. Drawing it the
   * same bare dot, with the same `data-collapsed-ports` stamp, is what
   * makes "exactly one dot per wall, carrying every id it stands for" true
   * for EVERY wall in simple view rather than only the crowded ones.
   *
   * A HEADER-band item is the third bare-dot case, for a different reason
   * than the collapsed one above: the header band is chrome, and the
   * header's own content IS the label — a tab is sized to hug a title, not
   * to hold a second naming of the same thing underneath it. Zach,
   * captured live off this story's first render (`hdr-5-tab-with-ports.png`
   * etc.): "in"/"out" painted directly on top of "Planner", all three
   * glyphs unreadable, and a bare-header chevron with a label sitting on
   * top of it. The precedent already exists in this file —
   * `BlockFunctionPort` below is a `LabeledPort` with `labelSlot={null}`
   * for exactly this reason, the header-left function port never having
   * room for a name either. A caller who genuinely needs labels IN the
   * header band can still get them — supply a `portEdgeProps.renderItem` of
   * their own (see the reach-past below, at the `<PortEdge>` call) and
   * inset their own header content with `functionPortHeaderInsetPx()` to
   * make room — but that is an opt-in, not the default, because one
   * specimen having room to fit them is not the general case.
   */
  const renderItem: PortEdgeProps["renderItem"] = (item, ctx) =>
    plan.collapsed ? (
      <span data-slot="block-port-item" data-port-id={item.id} data-collapsed-ports={item.id} style={{ display: "inline-flex" }}>
        <Port state={item.state ?? "empty"} diameter={diameter} variant={variant} diagnostics={item.diagnostics} availability={item.availability} producers={item.producers} selected={item.selected} />
      </span>
    ) : (
      // `data-editable` (ported from claude/notebook-lab-work-order-472c22
      // `23ab20e`): marks the port whose label a click will edit, so a host
      // can tell "click edits the name" from "press starts a cable" without
      // re-deriving the gate. It mirrors the SAME boolean as `disabled`
      // below — the P-037 gate, "the host said where the text should go" —
      // and deliberately not the donor's `ctx.editable` (this edge's
      // `editing` arming): on a Block the two can disagree, and a DOM flag
      // that disagreed with the label it describes would be a lie.
      <span data-slot="block-port-item" data-port-id={item.id} data-editable={spec.onItemsChange ? true : undefined} style={{ display: "inline-flex" }}>
        <LabeledPort
          edge={edge}
          state={item.state ?? "empty"}
          diameter={diameter}
          variant={variant}
          textLayout={ctx.textLayout}
          diagnostics={item.diagnostics}
          availability={item.availability}
          // Lane `ports` (2026-09-19): the type run, the fan-in count and
          // selection travel from the item exactly as `diagnostics` does —
          // the PORT is the subject, the rail is furniture.
          type={item.type}
          typeColor={item.typeColor}
          producers={item.producers}
          selected={item.selected}
          // Header band: dot only, no label — see this function's own WHY
          // above. `labelSlot={null}` (not omitting `children`) is what
          // `BlockFunctionPort` already does for the same reason: it skips
          // `LabeledPort`'s built-in `DefaultPortLabel` branch entirely
          // (labeledPort.tsx's own `labelSlot !== undefined` gate) rather
          // than rendering an empty editable field in its place.
          labelSlot={plan.band === "header" ? null : undefined}
          // P-037. `LabeledPort`'s built-in label is click-to-edit by DEFAULT
          // (`DefaultPortLabel`'s `disabled = false`) and its `onLabelWrite` is
          // optional, so a rail whose host never wired one opened a real
          // `CodeEditor`, took every keystroke and dropped them on the floor —
          // "an unwired label simply reflects whatever the host passes", which
          // is a fine preview in a story and a lie on a board. Measured in the
          // real app 2026-09-21: double-clicking a rail label of a port storing
          // `gain_x: float`, typing `gain_y`, and finding the record unchanged
          // and the label snapped back.
          //
          // WHY this pair is needed HERE at all, when `PortEdge` already
          // threads `editingEnabled`/`onLabelWrite` through its own default
          // fill: this `renderItem` REPLACES that fill (portEdge.tsx:553), so
          // everything the fill forwards has to be forwarded again — the same
          // trap this file already records for `diagnostics`/`availability`.
          //
          // WHY the write routes through `onItemsChange` rather than a new
          // `onLabelWrite` on `BlockEdgeSpec`: that is exactly what `PortEdge`
          // does with its own (`handlePortLabelWrite`, portEdge.tsx:1340), so a
          // rail and a bare edge report a rename identically and a host needs
          // one handler, not two. It also makes the gate honest — a label is
          // editable exactly when the host said where the text should go.
          disabled={!spec.onItemsChange}
          onLabelWrite={spec.onItemsChange ? (value) => spec.onItemsChange?.(spec.items.map((it) => (it.id === item.id ? { ...it, label: value } : it))) : undefined}
          // The SAME forwarding trap as `disabled`/`onLabelWrite` just above,
          // for the `reorderChord` hotkey (`ctx.onReorderKey`, added to
          // `renderItem`'s own ctx for "multiple returns" so a rail's ports
          // can be moved past a divider with Ctrl+arrow, same as any other
          // rail — see `PortEdgeProps.renderItem`'s own doc).
          onLabelKeyDown={ctx.onReorderKey}
        >
          {item.label}
        </LabeledPort>
      </span>
    );

  /**
   * D-A7's seam: simple view's bare centred dot, standing for the wall —
   * plus the "+X ports" count (Zach, 2026-09-17, screenshot 153001: "In
   * simple view perhaps have option to show text here showing +X ports").
   * `members` is every port this ONE dot stands in for, so `members.length`
   * IS the true hidden count — no separate accounting needed, and nothing
   * to keep in sync if a caller adds or removes an item on this wall.
   *
   * The count is an ABSOLUTELY POSITIONED overlay off the dot's own box —
   * `LabeledPort`'s own pattern (labeledPort.tsx's B4 note), not a flex
   * sibling. A flex sibling would widen this span, and the RAIL centres
   * this whole span on the wall line (`alignItems:"center"` on the
   * track's cross axis) — so the DOT itself would drift off the wall the
   * moment the label made the span asymmetric (measured live: 23px off,
   * failing `SimpleView`'s own wall-line assertion). Absolute positioning
   * keeps the span's LAYOUT box exactly the dot's box, same as before this
   * label existed.
   */
  const renderCollapsed: PortEdgeProps["renderCollapsed"] = (members) => (
    <span
      data-slot="block-port-collapsed"
      data-collapsed-ports={members.map((m) => m.id).join(",")}
      style={{ position: "relative", display: "inline-flex" }}
    >
      <Port
        state={collapsedState(members)}
        diameter={diameter}
        variant={variant}
        diagnostics={collapsedDiagnostics(members)}
        availability={collapsedAvailability(members)}
      />
      <span
        data-slot="block-port-collapsed-count"
        data-collapsed-count={members.length}
        style={{
          position: "absolute",
          left: "calc(100% + 4px)",
          top: "50%",
          transform: "translateY(-50%)",
          fontSize: 11,
          lineHeight: 1,
          whiteSpace: "nowrap",
          color: "var(--muted-foreground)",
        }}
      >
        +{members.length} ports
      </span>
    </span>
  );

  const style: CSSProperties = {
    position: "absolute",
    left: box.left,
    top: box.top,
    // D-A6, with the module doc's correction: `position: absolute` is what
    // already lifts this above the static Block, and this index is what
    // keeps that true if either of those facts ever changes — plus it is
    // the stacking context the lane overlay's own `laneOverlay` tier
    // needs. Named `portDot` (paintOrder.ts) — same tier as the function
    // port above; a rail IS a run of port dots.
    zIndex: paintTier("portDot"),
    // WHY `pointer-events: none` HERE, at the rail's own box: `railBoxFor`
    // deliberately makes this box `RAIL_CROSS_PX` (56px) wide/tall so its
    // CROSS centre lands on the Block's border line — which means HALF of
    // it, by construction, sits outside the Block, over whatever the host
    // paints underneath (a cable, the canvas). Only the dots/labels/rail
    // controls PortEdge actually draws inside this box are real content;
    // the surrounding `CONTAINER_PADDING` margin is empty on purpose (it's
    // what keeps the dots centred on the wall). Before this, the whole box
    // was hit-testable, so a press on that empty margin resolved its
    // `elementFromPoint` target to THIS div — and every host's
    // `contentOwnsPress`/`pointerOwnership` reads `.closest('[data-slot=
    // "block-port-rail"]')` as "content owns it", so the press never
    // reached the cable or the canvas underneath (measured 2026-09-22:
    // `wireGrab.smoke.test.tsx`'s curved-cable press at (475, 206) landing
    // in this margin, after 4b49cd4 moved a trace's endpoint onto the
    // dot's own ring and out from under the rail). `PortEdgeSlotBox`'s
    // sortable card (`data-slot="port-edge-card"`), the lane's own editor
    // overlay (`data-slot="port-edge-lane"`) and the "+N more" chrome each
    // re-arm `pointer-events: auto` on themselves — the only parts of this
    // box a press should ever resolve to.
    pointerEvents: "none",
  };

  return (
    <div data-slot="block-port-rail" data-edge={edge} data-rail-band={plan.band} data-collapsed={plan.collapsed || undefined} style={style}>
      <PortEdge
        {...spec.portEdgeProps}
        id={`${edge}-rail`}
        edge={edge}
        items={spec.items}
        onItemsChange={spec.onItemsChange}
        editing={editing}
        onEditingChange={spec.onEditingChange}
        // The Block's own border IS the line, and its own card IS the
        // container — `portEdge.tsx:151-155` documents exactly this intent
        // for both dev-time guides.
        showContainer={false}
        showCenterLine={false}
        showCard={false}
        size={axis === "column" ? { width: RAIL_CROSS_PX, height: box.height } : { width: box.width, height: RAIL_CROSS_PX }}
        distribution={plan.distribution}
        groups={plan.groups}
        groupMode={plan.groupMode}
        // `BlockEdgeSpec.portEdgeProps`'s own doc already claims `renderItem`
        // is one of the reach-past overrides a caller can win with — before
        // this it was a dead claim: the spread above lands first in the
        // props object and this explicit prop always followed it, so a
        // caller's own `renderItem` (e.g. one that wants LABELS drawn on a
        // header-band rail, opting back out of this file's default above)
        // was silently discarded. A caller's own function, when supplied,
        // now wins outright — it replaces this component's fill entirely
        // rather than being merged with it, the same all-or-nothing contract
        // `PortEdge`'s own `renderItem` prop already has.
        renderItem={spec.portEdgeProps?.renderItem ?? renderItem}
        renderCollapsed={renderCollapsed}
        dividerAfter={spec.dividerAfter}
        onDividerAfterChange={spec.onDividerAfterChange}
      />
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Measurement helpers the stories assert with — exported so the same   */
/* reading is used by every acceptance rather than re-typed per story.  */
/* ------------------------------------------------------------------ */

/** Every rendered dot centre on one rail, in viewport coordinates, in
 *  visual order. */
export function railDotCentres(rail: Element): { x: number; y: number }[] {
  return Array.from(rail.querySelectorAll<HTMLElement>('[data-slot="port-dot"]')).map((dot) => {
    const rect = dot.getBoundingClientRect();
    return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
  });
}

/** Consecutive centre-to-centre deltas along a rail's MAIN axis — every
 *  one of them, which is what "uniform pitch" has to be measured over.
 *  Sampling two of them cannot tell a uniform rail from a drifting one. */
export function railPitches(rail: Element, axis: "row" | "column"): number[] {
  const centres = railDotCentres(rail);
  const pitches: number[] = [];
  for (let i = 1; i < centres.length; i++) {
    pitches.push(axis === "column" ? centres[i].y - centres[i - 1].y : centres[i].x - centres[i - 1].x);
  }
  return pitches;
}

export const RAIL_SLOT_MAIN_PX = PORT_EDGE_SLOT_MIN_PX;

"use client";
/**
 * src/components/blockRegion.labeledGroup.tsx — the Labeled Group: a PRESET
 * of BlockRegion, not a component of its own.
 *
 * Zach, 2026-09-22: "labeled group should be a preset of Block Region", "its a
 * region with only a title showing." The look is React Flow UI's Labeled Group
 * Node, the reference he pasted: a thin rounded frame, and a label inside it
 * at the top-left that shares the frame's rounding there, is square where it
 * meets the frame, and rounds its own bottom-right corner.
 *
 * WHY the label is a real Block and not a text chip: BlockRegion draws the
 * `title` as a header-only Block with `shape="region-corner"`, the same card
 * a loop wears in its corner. So there is ONE frame renderer and ONE corner
 * card, every region drawing in `skin/regionVariants` styles a labeled group
 * too, and a group that later needs ports passes a full `corner` without
 * changing component. The first version of this preset drew its own chip,
 * and repeated the corner radii by hand; this replaces it.
 */
import { BlockRegion, type BlockRegionProps, type RegionText } from "./blockRegion";

/**
 * WHY every corner prop is omitted, `cornerCard` included (Codex re-judge,
 * 2026-09-22): BlockRegion gives `cornerCard` precedence over `title`, so a
 * `cornerCard` let through here silently replaced the label this preset
 * exists to draw. And `label` is TEXT: it is the auto-measured corner
 * (`RegionCornerProps`), whose hidden measuring copy must never render a node.
 */
export type LabeledGroupProps = Omit<BlockRegionProps, "title" | "type" | "corner" | "cornerCard" | "cornerSize" | "kind" | "arms"> & {
  /** The group's title. Rendered as authored — no trimming or casing. */
  label: RegionText;
  // `never`, not just omitted: `Omit` does not stop an object SPREAD from
  // carrying these back in (re-judge 4). Stripped at runtime below too.
  title?: never;
  type?: never;
  corner?: never;
  cornerCard?: never;
  cornerSize?: never;
  kind?: never;
  arms?: never;
};

export function LabeledGroup(props: LabeledGroupProps) {
  // Destructured OUT, whatever the types said: a spread from plain JS or an
  // `any` must never reach BlockRegion, which would let `cornerCard`/`corner`
  // silently replace the label this preset exists to draw.
  const { label, title: _title, type: _type, corner: _corner, cornerCard: _cornerCard, cornerSize: _cornerSize, kind: _kind, arms: _arms, ...region } = props;
  return <BlockRegion {...region} kind="group" title={label} />;
}

// src/components/blockRegion.layout.ts — BlockRegion's vertical geometry as a PURE
// function: where the corner block sits, where the free body starts, and
// how arms stack. CONTRACT STUB — docs/CONTROL-FLOW-PLAN.md, lane A.
// Signatures and constants frozen by `blockRegion.layout.test.ts`.
//
// PROVENANCE: the stacking rule is SystemSketch's `branchLayout`
// (`/home/bam/systemsketch/src/branch/branchModel.ts:161-230`, read
// 2026-09-18): rows are a running cursor, `bodyTop = rowTop + header`,
// `bodyH = open ? h : 0`, `bottom = bodyTop + bodyH`, next row's top is
// this row's bottom, and the region's height is the cursor plus a bottom
// pad. Ported by VALUE (restated in this repo's names), not by import. The
// one deliberate change: the first row starts under the CORNER BLOCK, not
// under a full-width band — Zach's 2026-09-18 ruling replaced the band with
// a real Block in the frame's top-left corner ("OLD: BAD / NEW: GOOD",
// `Pasted image 20260918150916.png`).
//
// WHY a pure twin exists when the DOM could stack arms with flexbox: the
// component positions arm rows from THIS function (with a measured corner
// height), so a host that needs arm geometry WITHOUT rendering — a drop
// target, an SVG export, stream 2's tldraw shape — reads the same numbers
// the paint used. SystemSketch's own reason (branchModel.ts:14-16): "a
// fold, an added arm and a tldraw resize all agree about where every row
// is."
//
// Pure: no React, no DOM.

/** Donor `BRANCH_ARM_HEADER_HEIGHT` (branchModel.ts:29). */
export const REGION_ARM_HEADER_PX = 32;
/** Donor `BRANCH_DEFAULT_ARM_HEIGHT` (branchModel.ts:31). */
export const REGION_ARM_DEFAULT_BODY_PX = 180;
/** Donor `BRANCH_MIN_ARM_HEIGHT` (branchModel.ts:32). */
export const REGION_ARM_MIN_BODY_PX = 48;
/** Ours: an empty loop/group still shows a body to drop into. */
export const REGION_BODY_MIN_PX = 120;
/** `BLOCK_MEMBER_INSET_PX` (blockMembers.tsx) — the same 12 the members
 *  region already breathes by; the donor's own pad was 10. */
export const REGION_PAD_BOTTOM_PX = 12;
/** Donor `BRANCH_MIN_WIDTH` (branchModel.ts:33). */
export const REGION_MIN_WIDTH_PX = 240;
/** Donor `BRANCH_FADE_OPACITY` (branchModel.ts:38-39): "Non-active arms,
 *  their Blocks and their cables fade to this. One token." */
export const REGION_ARM_FADE_OPACITY = 0.18;
/** The corner block's width in the expanded view — Zach's "NEW GOOD"
 *  sketch draws a compact port-view block (~140px) in the frame's corner,
 *  not a full 320px Block. Height hugs the ports. */
export const REGION_CORNER_WIDTH_PX = 160;
/** The opaque card's width (P5): wider than the corner because it also
 *  carries the promoted boundary ports and a footer. Height hugs. */
export const REGION_CARD_WIDTH_PX = 220;

export interface RegionRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface RegionArmInput {
  id: string;
  open: boolean;
  /** Body height while open; remembered while folded. Default
   *  `REGION_ARM_DEFAULT_BODY_PX`; never below `REGION_ARM_MIN_BODY_PX`. */
  bodyHeight?: number;
}

export interface RegionLayoutInput {
  width: number;
  /** Explicit outer height. Omitted = hug: the last row's bottom plus
   *  `REGION_PAD_BOTTOM_PX` (or `corner.h + REGION_BODY_MIN_PX` with no arms).
   *  Given but too small for the arms = the arms win (the donor's
   *  `reconcileBranchProps` rule: `h` is kept in step with the arms). */
  height?: number;
  /** The corner block's measured (or declared) size. */
  corner: { w: number; h: number };
  arms?: readonly RegionArmInput[];
  /**
   * The arm header row's height. Default `REGION_ARM_HEADER_PX` (the
   * donor's 32). A region VARIANT may draw a shorter or taller header
   * (`skin/regionVariants.ts`, `arms.headerPx`) — and because this twin is
   * read by hosts that never render (a tldraw shape's geometry), the number
   * has to arrive as an input rather than be read off a computed style. A
   * host that switches variants passes
   * `REGION_VARIANTS[readRegionVariant()].arms.headerPx` here, or its rows
   * and the component's rows disagree by the difference.
   */
  armHeaderPx?: number;
}

export interface RegionArmLayout {
  id: string;
  index: number;
  open: boolean;
  /** The row = header + body. `rowTop` of arm 0 is `corner.h`. */
  rowTop: number;
  headerTop: number;
  bodyTop: number;
  /** 0 while folded. */
  bodyHeight: number;
  bottom: number;
}

export interface RegionLayout {
  width: number;
  height: number;
  /** Always `{x: 0, y: 0, w, h}` — the corner block IS the origin. */
  corner: RegionRect;
  /** The free body under the corner block. With arms present it has zero
   *  height (a branch has no free body; its arms are its body). */
  body: RegionRect;
  arms: RegionArmLayout[];
}

export function regionLayout(input: RegionLayoutInput): RegionLayout {
  const width = Math.max(input.width, REGION_MIN_WIDTH_PX);
  const corner = { x: 0, y: 0, w: input.corner.w, h: input.corner.h };

  // The donor's running cursor (branchModel.ts:161-230), restated: one row
  // is header + body, the body costs nothing while folded, and the next
  // row starts exactly where this one ended. The ONE change from the donor
  // is where the cursor starts — under the CORNER BLOCK, not under a
  // full-width band (Zach's 2026-09-18 "OLD: BAD / NEW: GOOD" ruling).
  const headerPx = input.armHeaderPx ?? REGION_ARM_HEADER_PX;
  let cursor = corner.h;
  const arms: RegionArmLayout[] = (input.arms ?? []).map((arm, index) => {
    const rowTop = cursor;
    const bodyTop = rowTop + headerPx;
    // WHY the clamp only applies while OPEN: `bodyHeight` is the height an
    // arm remembers, and a folded arm must remember the number it will
    // re-open at — clamping a folded arm to the minimum would silently
    // rewrite an authored 10 into 48 the moment someone folded it.
    const bodyHeight = arm.open ? Math.max(arm.bodyHeight ?? REGION_ARM_DEFAULT_BODY_PX, REGION_ARM_MIN_BODY_PX) : 0;
    const bottom = bodyTop + bodyHeight;
    cursor = bottom;
    return { id: arm.id, index, open: arm.open, rowTop, headerTop: rowTop, bodyTop, bodyHeight, bottom };
  });

  // Hug: the last row's bottom plus the pad, or — with no arms — enough
  // room for the free body a loop/group drops into. An explicit `height`
  // may only ever make the region TALLER; the donor's own
  // `reconcileBranchProps` keeps `h` in step with the arms for the same
  // reason, and a frame shorter than its own rows would paint arms outside
  // the border they are supposed to live in.
  const hugged = arms.length > 0 ? cursor + REGION_PAD_BOTTOM_PX : corner.h + REGION_BODY_MIN_PX;
  const height = Math.max(input.height ?? 0, hugged);

  return {
    width,
    height,
    corner,
    // A branch has no free body: its arms ARE its body (plan §3.2). Kept as
    // a zero-height rect at the same origin rather than omitted, so a
    // caller reads one shape either way.
    body: { x: 0, y: corner.h, w: width, h: arms.length > 0 ? 0 : height - corner.h },
    arms,
  };
}

"use client";

// src/components/blockRegion.tsx — BlockRegion: a thin scope FRAME with a
// real Block integral to its top-left corner, an optional free body, and an
// ordered list of arm rows. Props in, DOM out (docs/CONTROL-FLOW-PLAN.md
// §3.2); it imports no scene module and no canvas engine, so the same
// element renders under the DOM canvas, React Flow and tldraw unchanged.
//
// WHY "BlockRegion" and a composite rather than a frame with a slot (Zach,
// 2026-09-22: "Block Region is stanadlone component that composes the Block
// with a 'region'"): the corner IS a Block. Give it a `title` and this
// component draws that Block itself, `shape="region-corner"`, so the square
// junctions come with it. The Labeled Group is exactly that with nothing
// else (`blockRegion.labeledGroup.tsx`). A host that needs ports on the card
// still passes its own `BlockPort`-wrapped Block as `corner`, and gives that
// Block the same shape: the shape is the Block's, not the region's
// (block.tsx, `BlockShape`).
//
// ── ONE NODE, TWO PIECES OF PAINT (plan §2.A, Zach's "everything is a
//    block" made structural) ──────────────────────────────────────────
// A region is ONE scene node. The FRAME is how that node renders its
// SCOPE; the CORNER BLOCK is how it renders its INTERFACE. There is no
// second node, no head child, and the frame carries no value ports of its
// own — a loop's `Iterable`/`Iter` and a branch's conditions are ports on
// the corner card, resolved by exactly the same `[data-block-id]` ->
// `[data-port-id]` walk as any other block's.
//
// WHY the root and the frame carry `data-region-id` and NEVER
// `data-block-id`: `wireLayer.tsx`'s `resolveDot` takes the FIRST
// `[data-block-id="<id>"]` in document order (wireLayer.tsx:81). If the
// frame carried the region's id it would win that lookup, and every wire
// into the corner card would resolve against a box that owns no dot. The
// corner card owns the id; the frame owns the region id. The tempting
// alternative — stamping both and "letting the more specific one win" —
// cannot work, because document order, not specificity, is the rule.
//
// LOOK: React Flow UI's Labeled Group Node (`Pasted image 20260918192040.png`,
// the reference Zach named): a thin rounded frame with a transparent fill
// and a label chip INSIDE the frame at its top-left, sharing the frame's
// rounding there and square where it meets the frame. Ours is a whole
// Block rather than a text chip, which is the entire point.
//
// ── FIVE DRAWINGS, ONE COMPONENT (2026-09-19, `skin/regionVariants.ts`) ──
// Zach asked for five proposals for how a region could be drawn
// differently. They are NOT five components and not five props: every
// paint value below is a CSS custom property (`--bbox-region-*`) read with
// today's value as its `var()` fallback, and a variant is a block of those
// properties keyed on `data-bbox-region-variant` on any ancestor
// (`skin/regionVariants.css`, the skin.css mechanism). The two things CSS
// cannot drive — the arm header's height, which the pure layout twin must
// be told, and the fold chevron's `reveal`, which is a prop — come from
// the TS spec via `useRegionVariant`, keyed on the SAME attribute. So no
// variant is ever a fork of this file, and a consumer who never imports
// the CSS renders the pixels this component rendered before variants
// existed (`v1`).
//
// What every variant keeps, because Zach's ruling is not a variant axis:
// the corner block flush with the frame's top-left; its dots ON the frame
// edge and never clipped; arms stacked under it and folded by the chevron;
// the opaque card untouched.
//
// ── THE VIEWS (Zach, 2026-09-22, `BlockRegionViews.stories.tsx`) ─────────
// "regions do not have a simple view. they just have port, expanded and
// expanded opaque view." So `view` is `port` | `expanded` | `opaque`, and
// there is deliberately no `simple`. `opaque` keeps its original meaning, the
// P5 card every host already draws, unless `opaqueFace="frame"` asks for
// Expanded Opaque: the frame at its expanded size, the members hidden, glyph +
// Title + Type centred. `onToggleView` draws the Blackbox toggle in the
// frame's top-right corner. Every one of these defaults to what this component
// drew before, so no host changes. The views are ported from the sibling
// branch's `region.tsx` (`view: "port"`, `opaqueFace: "frame"`,
// `RegionViewToggle`) and its `blockOpaqueTitle.tsx`, trimmed to the corner
// header this component already has.
//
// ── THE HEADER DRAWINGS (merge, 2026-09-22) ─────────────────────────────
// That trim said "no `headerStyle`, no `crossings`" — true while the two
// lineages were separate, and wrong the moment they merged, because both are
// Zach's own 2026-09-22 sketches and only this file survives to draw them.
// They are back, as two independent props that BOTH default to what this
// component already drew:
//   • `headerStyle` — how the expanded frame marks its top edge: today's
//     corner card (`corner-card`, the default), a small title tab
//     (`corner-tab` / `corner-tab-full`), or a header bar across the whole
//     top (`full-width`). The id rule survives every one: whichever element
//     owns the region's PORTS carries the ONE `data-block-id`; the root and
//     the frame carry only `data-region-id`; a tab owns no port and carries
//     neither.
//   • `crossings` — the small hollow circles where a cable crosses the
//     frame's wall, frame-local (`blockRegion.views.layout.ts`'s
//     `wallCrossings`, measured per host by `hosts/regionCrossings.ts`).
//     Decorative: no id, no pointer events, so nothing can bind to one. They
//     emit the `portDot` paint tier, which is why the expanded and opaque
//     roots spread `ISOLATED_ROOT_STYLE` (paintOrder.ts's invariant).
//
// WHY no region-level chevron anywhere in this file (Zach, 2026-09-22):
// "Please do not put chevron drop downs on the regions." The region's view
// changes through the Blackbox toggle and the host's view selector, never
// through a chevron on its corner. The chevrons that remain are the ARM
// rows' own fold controls (`ArmRow`), which fold one arm of a branch and
// never collapse the region itself.
//
// Pure: no React state beyond two measurements (the corner's box and the
// variant in force), no DOM outside its own subtree, no scene import (the
// `layering.test.ts` import wall).

import { useLayoutEffect, useState, type CSSProperties, type ReactNode } from "react";
import { flushSync } from "react-dom";
import { Square } from "lucide-react";

import { Bar } from "./bar";
import { Block, REGION_FRAME_RADIUS } from "./block";
import { BlockMembers, type BlockMember } from "./blockMembers";
import { BlockPort, type BlockEdgeSpec } from "./blockPort";
import { offsetEdgePaddingPx, RAIL_CROSS_PX, RAIL_GAP_PX, railAxisFor, railBoxFor, railPlanFor, type BlockBands } from "./blockPort.layout";
import { Button } from "./button";
import { FoldingChevron } from "./foldingChevron";
import { ControlMark, isControlMarkKind, type ControlMarkKind } from "./controlMark";
import { Badge } from "./badge";
import { Glyph } from "./glyph";
import type { Diagnostic } from "./highlighter";
import { LabeledPort } from "./labeledPort";
import { cn } from "../lib/utils";
import { ISOLATED_ROOT_STYLE, paintTier } from "./paintOrder";
import type { BlockSide } from "./port.layout";
import { PortEdge, type PortEdgeItem, type PortEdgeProps } from "./portEdge";
import {
  REGION_ARM_FADE_OPACITY,
  REGION_CARD_WIDTH_PX,
  REGION_CORNER_WIDTH_PX,
  REGION_MIN_WIDTH_PX,
  regionLayout,
  type RegionLayout,
} from "./blockRegion.layout";
import {
  REGION_CONTROL_BOX_WIDTH_PX,
  regionControlSplitPx,
  regionHeaderBandPx,
  regionRailBandPx,
  type RegionPoint,
} from "./blockRegion.views.layout";
import {
  DEFAULT_REGION_VARIANT,
  REGION_VARIANT_ATTR,
  REGION_VARIANTS,
  readRegionVariant,
  type RegionVariantId,
} from "../skin/regionVariants";

export type { RegionPoint } from "./blockRegion.views.layout";

export type RegionKind = "loop" | "branch" | "group";
/**
 * `port` is the region collapsed all the way to a block. There is
 * deliberately no `simple` (Zach, 2026-09-22: "regions do not have a simple
 * view").
 */
export type RegionView = "expanded" | "opaque" | "port";

/**
 * What `view="opaque"` draws. `card` is the P5 card (the host's own
 * `corner`, or the title card) and stays the default, so every host keeps
 * what it drew. `frame` is Zach's "Expanded Opaque": the frame keeps its
 * size, the members go, and glyph + Title + Type sit centred.
 */
export type RegionOpaqueFace = "card" | "frame";

/**
 * How the expanded frame marks its top edge (Zach, 2026-09-22).
 *  • `corner-card` — the Block in the corner (the default; `corner`,
 *    `cornerCard` or `title` supplies it, exactly as before this prop
 *    existed).
 *  • `corner-tab` — a small tab at the top-left with just the title.
 *  • `corner-tab-full` — the same tab with glyph + title + type.
 *  • `full-width` — a header bar across the frame's whole top; glyph + title
 *    + type centred, control ports (if any) stacked at its left end.
 *
 * WHY only `corner-card` reads `corner`/`cornerCard`: the other three are
 * drawings BlockRegion makes for itself out of `glyph`/`title`/`type` and
 * `controlPorts`, so a host that picks one is not also handing in a card.
 */
export type RegionHeaderStyle = "corner-card" | "corner-tab" | "corner-tab-full" | "full-width";

export interface RegionArm {
  id: string;
  /** Free text, human readable — `if fast:`, `case "pet":`. Never code. */
  title: ReactNode;
  open: boolean;
  onOpenChange?(open: boolean): void;
  /** Absent is ACTIVE. Donor branchModel.ts:11-12 — "no active arm means
   *  every arm is active". */
  active?: boolean;
  /** Body height while open; remembered while folded (`regionLayout`). */
  bodyHeight?: number;
  members?: BlockMember[];
  /** This arm's OWN operand: the boolean it is selected by. `else` has none.
   *  Rendered as a port on the arm's header strip, left wall. */
  test?: { id: string; default?: string };
  /** Names this arm's PATTERN binds INTO its body (`case Point(x=0, y=y)`
   *  binds `y`) — a value the header PRODUCES, so it sits on the header's
   *  RIGHT edge, facing out of the tab. */
  captures?: readonly string[];
}

/** Text the measuring copy may render: a string or a number, never a node. */
export type RegionText = string | number;

/**
 * The chips a region corner's header carries on its right — a host's badge
 * ("iteration 3 of 7", `z⁻¹ = 0`) and control marks — as DATA, drawn by
 * BlockRegion itself (`Badge`, `ControlMark`). WHY data and not a node: see
 * `RegionCornerCard`.
 */
export interface RegionHeaderChips {
  badge?: RegionText;
  marks?: readonly ControlMarkKind[];
}

/**
 * The kit's own corner card, as DATA: BlockRegion renders it — a `BlockPort`
 * whose id is the region's, around a `Block` with `shape="region-corner"` —
 * so it can also render a measuring copy of it (see `RegionCornerProps`).
 *
 * `H` is what the header may hold: `RegionText` on the auto-measured path,
 * any node only where the caller gives `cornerSize` (`RegionCornerProps`).
 */
export interface RegionCornerCard<H extends ReactNode = RegionText> {
  header: H;
  chips?: RegionHeaderChips;
  /** Default `REGION_CORNER_WIDTH_PX`. */
  width?: number;
  /** The region's own ports, on the card's walls. */
  edges?: Partial<Record<BlockSide, BlockEdgeSpec>>;
  /** A body band under the header, px — room for a port-view rail. */
  bandHeight?: number;
  diagnostics?: Diagnostic[];
}

type CornerSize = { w: number; h: number };

/**
 * Where the corner comes from, and who sizes it.
 *
 * Expanded Opaque does not draw the corner, yet its box depends on the
 * corner's height (`regionLayout`). WHY the union and not an optional
 * `cornerSize` beside an optional `corner` (Codex audit + two re-judges,
 * 2026-09-22): the size either comes from content BlockRegion renders itself
 * — the `title` card or a `cornerCard` — which it can mount hidden and
 * measure, or it comes from the caller. What it must NEVER do is clone an
 * arbitrary `corner` ReactNode to measure it: a portal inside it (an open
 * Popover, a Tooltip) escapes every hiding ancestor and the copy shows up as
 * a second, visible, focusable widget. So an arbitrary `corner` whose region
 * can be opaque must carry `cornerSize` — enforced here by the types: with
 * `view` typed to allow `"opaque"`, the only branch that accepts a `corner`
 * requires `cornerSize`.
 */
export type RegionCornerProps =
  | {
      /** BlockRegion draws the corner itself: `cornerCard`, else `title` —
       *  PRIMITIVE text only, because this is the arm it measures by
       *  mounting a hidden copy (re-judge 3: a portal inside `title` or the
       *  header escapes every hiding ancestor, exactly as one inside
       *  `corner` did). */
      corner?: undefined;
      cornerCard?: RegionCornerCard<RegionText>;
      title?: RegionText;
      type?: RegionText;
      /** Skip the measurement when a host already knows the corner's box. */
      cornerSize?: CornerSize;
      view?: RegionView;
    }
  | {
      /** Rich title / type / header content: never copied, so the caller
       *  sizes the corner — whatever `view` says, because a view is runtime
       *  state a wrapper's default can flip to opaque (re-judge 4). */
      corner?: undefined;
      cornerCard?: RegionCornerCard<ReactNode>;
      title?: ReactNode;
      type?: ReactNode;
      cornerSize: CornerSize;
      view?: RegionView;
    }
  | {
      /** An arbitrary corner, supplied whole: never copied, so the caller
       *  sizes it — again regardless of `view`. */
      corner: ReactNode;
      cornerCard?: undefined;
      title?: ReactNode;
      type?: ReactNode;
      cornerSize: CornerSize;
      view?: RegionView;
    };

export type BlockRegionProps = BlockRegionBaseProps & RegionCornerProps;

interface BlockRegionBaseProps {
  /** Stamped as `data-region-id` on the root AND the frame — never
   *  `data-block-id`. See this file's header. */
  id: string;
  kind?: RegionKind;
  // `title` and `type` live in `RegionCornerProps`, typed per arm: the
  // corner card's title (with no `corner`/`cornerCard`, BlockRegion draws the
  // card itself, a header-only `Block` hugging it, rendered as authored), and
  // the secondary run beside it, muted.
  width?: number;
  /** Omitted = hug (`regionLayout`). */
  height?: number;
  /** The free body a loop/group drops into — `BlockMembers layout="free"`. */
  members?: BlockMember[];
  arms?: RegionArm[];
  /** `@bbox-ui/glyph-content` grammar (`lucide:repeat`). Drawn on the
   *  port card's header and, large, on the Expanded Opaque face. */
  glyph?: string;
  /**
   * The region's CONTROL ports (a loop's `Iterable`) when BlockRegion draws
   * its own corner from `title`: on the corner card's left wall while
   * expanded, above the split line in the `port` view, boxed into the
   * corner of the Expanded Opaque face. Ignored when `corner` is given (a
   * host's card already carries its ports).
   */
  controlPorts?: PortEdgeItem[];
  /**
   * The ORDINARY ports — the region's boundary. Drawn under the split in the
   * `port` view and on the walls of the Expanded Opaque face; the expanded
   * view never draws them, because there the cable crosses the wall itself.
   */
  boundaryPorts?: Partial<Record<"left" | "right", PortEdgeItem[]>>;
  /** Default `card`. */
  opaqueFace?: RegionOpaqueFace;
  /** Default `corner-card` — every caller that predates it renders exactly
   *  what it rendered before. See `RegionHeaderStyle`. */
  headerStyle?: RegionHeaderStyle;
  /**
   * Where wires cross the frame's border, FRAME-LOCAL (border-box top-left
   * is 0,0) — `blockRegion.views.layout.ts`'s `wallCrossings`, measured per
   * host by `hosts/regionCrossings.ts`. Each paints a small hollow circle on
   * the wall. Decorative only: not a port, no id, no pointer events, so
   * nothing can bind to one. Drawn in the EXPANDED view only — once the
   * inside is hidden a crossing is a real promoted port on the wall
   * (`boundaryPorts`), not a mark.
   */
  crossings?: readonly RegionPoint[];
  /** Present = draw the Blackbox toggle at the frame's top-right, in the
   *  expanded view and on the Expanded Opaque face. The caller owns the
   *  view; this only asks for it to flip. */
  onToggleView?(): void;
  /**
   * Extra class on the Blackbox toggle — a canvas host's pointer-ownership
   * marker (`nodrag`), the same seam `FoldingChevron`'s `className` gives
   * the hosts. This component never names the marker itself: which string
   * a host's drag filter reads is the host's business.
   */
  toggleClassName?: string;
  /** The footer of every view that hides the inside — the Expanded Opaque
   *  face AND the Port card: a host states what is hidden (`nodeViews.tsx`'s
   *  `region-hidden`, P5's "a card whose footer states what it hides").
   *  Omitted = no footer. */
  hiddenFooter?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

/** The frame's own border, px — the number the corner is pulled back by so
 *  the two borders sit on ONE line rather than doubling into a 2px rule.
 *  Every variant keeps this 1px of GEOMETRY (a variant may paint it
 *  transparent, never widen it), which is what keeps every row, member and
 *  dot exactly where it was under `v1`. */
const FRAME_BORDER_PX = 1;

/** The frame's shared top-left radius — the corner card's too, which is why
 *  it lives beside `Block`'s `"region-corner"` shape and is read from there:
 *  the frame and the card curve together only while they read one string. */
const FRAME_RADIUS = REGION_FRAME_RADIUS;

/**
 * The corner's measured box.
 *
 * WHY measured and not computed: the corner is a whole `Block` whose height
 * hugs its own header, ports and footer — there is no closed form for it
 * (the same reason `blockPort.tsx`'s `useBlockBands` measures rather than
 * derives). The first render has no box yet and falls back to
 * `{w: REGION_CORNER_WIDTH_PX, h: 0}`; `useLayoutEffect` corrects it BEFORE
 * the browser paints, so the guess is never on screen — the same
 * first-frame device `tldrawHost.tsx` uses, tightened one frame because
 * this measurement has no engine to wait for.
 */
function useCornerSize(given: { w: number; h: number } | undefined): {
  ref: (node: HTMLDivElement | null) => void;
  size: { w: number; h: number };
} {
  const [node, setNode] = useState<HTMLDivElement | null>(null);
  const [measured, setMeasured] = useState<{ w: number; h: number } | null>(null);
  const skip = given !== undefined;

  useLayoutEffect(() => {
    if (skip || !node) return;
    const read = () => {
      const rect = node.getBoundingClientRect();
      // Identity-preserving: a sub-pixel re-measure that says the same
      // thing must not re-render, or the observer feeds itself.
      setMeasured((previous) =>
        previous && Math.abs(previous.w - rect.width) < 0.5 && Math.abs(previous.h - rect.height) < 0.5
          ? previous
          : { w: rect.width, h: rect.height },
      );
    };
    read();
    const observer = new ResizeObserver(read);
    observer.observe(node);
    return () => observer.disconnect();
  }, [skip, node]);

  return { ref: setNode, size: given ?? measured ?? { w: REGION_CORNER_WIDTH_PX, h: 0 } };
}

/**
 * The variant in force for THIS region — the nearest ancestor carrying
 * `data-bbox-region-variant`, else `<html>`'s, else `v1`
 * (`readRegionVariant`).
 *
 * WHY it is measured off the DOM in a layout effect, like the corner, and
 * not passed as a prop or read from a context: the contract's switch is an
 * ATTRIBUTE (so the app's dropdown and Storybook's global are three lines
 * each, and CSS reads the same thing), and an attribute change re-renders
 * nothing here on its own. The CSS tokens follow it for free; the two
 * values that are not CSS — the header height the layout twin needs and
 * the chevron's `reveal` — follow it through the observer below, without
 * any React state outside this file. The first render assumes `v1` and the
 * layout effect corrects it before paint, the device `useCornerSize` uses.
 *
 * WHY the observer is shaped as it is — the failure it closes is a
 * HALF-SWITCHED region, CSS on the new drawing and layout/chevron on the
 * old (`RegionVariants.stories.tsx`'s `SwitchOnAncestor*` and
 * `SwitchNeverHalfPainted`, each red against the alternative named here):
 *   • It watches the WHOLE document (`subtree`), filtered to the one
 *     attribute — `<html>`'s dataset from an app dropdown, a wrapper
 *     written by hand, and a React-owned wrapper (the Storybook global)
 *     whether or not this region re-rendered with it. Observing only
 *     `<html>` (the first cut) left a nearer ancestor's switch unseen
 *     forever. The filter keeps it cheap: records exist only for this
 *     attribute, which changes when someone picks a drawing.
 *   • It applies the change with `flushSync`. Its callback is a microtask,
 *     and a plain `setState` from there is scheduled as a later TASK —
 *     after the browser has painted the new CSS over the old layout, one
 *     visible frame of jitter per switch. `flushSync` renders inside the
 *     same microtask checkpoint, before paint; when the resolved variant
 *     did not change (another subtree's switch) the same-value bail-out
 *     makes it a `closest()` walk and nothing else.
 */
function useRegionVariant(node: HTMLElement | null): RegionVariantId {
  const [variant, setVariant] = useState<RegionVariantId>(DEFAULT_REGION_VARIANT);
  useLayoutEffect(() => {
    if (!node) return;
    setVariant(readRegionVariant(node));
    const observer = new MutationObserver(() => {
      const next = readRegionVariant(node);
      flushSync(() => setVariant(next));
    });
    observer.observe(document.documentElement, { attributes: true, attributeFilter: [REGION_VARIANT_ATTR], subtree: true });
    return () => observer.disconnect();
  }, [node]);
  return variant;
}

/**
 * An arm's own header strip as `BlockBands`, NOT measured: `regionLayout`
 * already knows this geometry in closed form (`row.headerTop`/`row.bodyTop`),
 * the same reason `blockRegion.layout.ts` exists at all. `blockLeft`/
 * `headerTop` are 0, not `row.rowTop`, because this rail mounts INSIDE
 * `region-arm-header` itself (its own `position: relative` box, below) — an
 * absolutely positioned child's `left`/`top: 0` already land on that div's
 * own padding edge, so the bands are local to the header strip, not to the
 * frame. `bodyTop`/`bodyBottom` both equal the strip's own height: an arm
 * header has no body band of its own to distinguish, and `railBoxFor`'s
 * `band: "header"` case (blockPort.layout.ts) never reads `bodyBottom` for
 * a column-axis edge.
 */
export function armHeaderBands(headerHeightPx: number, widthPx: number): BlockBands {
  return {
    blockLeft: 0,
    blockTop: 0,
    blockWidth: widthPx,
    blockHeight: headerHeightPx,
    headerTop: 0,
    bodyTop: headerHeightPx,
    bodyBottom: headerHeightPx,
  };
}

/**
 * One wall's `RailPlan` for an arm header rail — `railPlanFor`'s own
 * "expanded, column axis" rule (`space-evenly`, which centres a LONE dot in
 * the band — see that function's own WHY), with `band` overridden to
 * `"header"` afterward: the same `RailBand` (`blockPort.layout.ts`) an
 * ordinary Block's function port sits on.
 */
export function armHeaderRailPlan(edge: BlockSide, itemIds: string[]) {
  return {
    ...railPlanFor({ view: "expanded", portLayout: "inline", edge, itemIds, leadCount: 0, collapsePorts: false }),
    band: "header" as const,
  };
}

/**
 * ONE wall's rendered rail on an arm's header strip: `railBoxFor` (this
 * file's own header, "one geometry, two mount points") positioned exactly
 * as `blockPort.tsx`'s `BlockPortRail` positions a Block's own wall rail —
 * SAME function, not a second copy of its arithmetic.
 *
 * WHY this is its OWN small renderer and not a call to `BlockPortRail`
 * itself (tried first, reverted): `blockPort.tsx`'s `renderItem` hardcodes
 * `labelSlot={plan.band === "header" ? null : undefined}` — deliberately
 * blank for an ordinary Block's function port, which never has room for a
 * name on a title bar it shares with the block's own header content. An
 * arm's header IS the port's only content, so that rule is exactly
 * backwards here: bullet 5 of this lane's own acceptance requires the
 * `valueSet` arm's default to show, verbatim, right where the dot sits —
 * measured red against `BlockPortRail` (`DEBUG` capture, 2026-09-22: the
 * rendered slot was `port-label-slot` — empty — not `DefaultPortLabel`'s
 * `port-label`). `blockPort.tsx`'s own comment names the sanctioned
 * reach-past for exactly this case: "a caller who genuinely needs labels IN
 * the header band can still get them — supply a `portEdgeProps.renderItem`
 * of their own" — except `BlockPortRail` places its OWN `renderItem` last in
 * the `<PortEdge>` spread, so `portEdgeProps.renderItem` can never reach
 * past it from outside. This function IS that reach-past, done the only way
 * left: skip `BlockPortRail`, keep `railBoxFor`.
 */
function ArmHeaderRail({ edge, items, bands }: { edge: BlockSide; items: PortEdgeItem[]; bands: BlockBands }) {
  const plan = armHeaderRailPlan(
    edge,
    items.map((item) => item.id),
  );
  const box = railBoxFor(edge, plan, bands);
  const axis = railAxisFor(edge);
  // A BARE DOT — no label. Corrected 2026-09-22 after looking at the
  // captures: this rail used to draw `item.label`, and the arm's own title
  // (`if:`) is drawn by `ArmRow`'s Bar starting at the SAME x, so the two
  // strings painted straight through each other — `mode == "fast"` over
  // `if:` rendered as `modif:e == "fast"` in all five region drawings, and
  // the fold chevron was overdrawn too. No measured assertion caught it;
  // they all check the DOT's box, never text collision.
  //
  // WHY a bare dot rather than insetting the title past the label: the
  // reading order has to be `if: mode == "fast"`, and the rail sits at the
  // frame's LEFT edge, so anything it draws necessarily comes first. The
  // expression therefore belongs to the arm's header TEXT (ArmRow composes
  // it after the title), and the dot goes back to being just a dot. That
  // also puts this rail back in line with the rule `blockPort.tsx` already
  // applies to every header-band rail — a header's own content is the
  // label — instead of standing as the one exception to it.
  const renderItem: PortEdgeProps["renderItem"] = (item, ctx) => (
    <span data-slot="block-port-item" data-port-id={item.id} style={{ display: "inline-flex" }}>
      {/* `disabled`: an arm's own operand/capture has no `onItemsChange` of
          its own yet — read-only, the same default `BlockPortRail` applies
          to an unwired rail (P-037's own WHY). */}
      <LabeledPort edge={edge} state={item.state ?? "empty"} textLayout={ctx.textLayout} disabled labelSlot={null} />
    </span>
  );
  return (
    <div
      data-slot="block-port-rail"
      data-edge={edge}
      data-rail-band={plan.band}
      style={{
        position: "absolute",
        left: box.left,
        top: box.top,
        zIndex: paintTier("portDot"),
        // `railBoxFor`'s own margin note (blockPort.tsx's identical style):
        // half this box sits outside the header strip by construction, so a
        // press there must fall through to whatever is underneath.
        pointerEvents: "none",
      }}
    >
      <PortEdge
        id={`${edge}-rail`}
        edge={edge}
        items={items}
        showContainer={false}
        showCenterLine={false}
        showCard={false}
        size={axis === "column" ? { width: RAIL_CROSS_PX, height: box.height } : { width: box.width, height: RAIL_CROSS_PX }}
        distribution={plan.distribution}
        groups={plan.groups}
        groupMode={plan.groupMode}
        renderItem={renderItem}
      />
    </div>
  );
}

function ArmRow({
  arm,
  row,
  index,
  chevron,
  frameWidth,
}: {
  arm: RegionArm;
  row: RegionLayout["arms"][number];
  index: number;
  chevron: "always" | "hover";
  /** `layout.width` — the FRAME's own width. Never measured: `region-arm`'s
   *  own `left:0; right:0` already hug the frame's padding edge, so the
   *  header strip's real width is this minus the frame's two borders
   *  (`FRAME_BORDER_PX` each side), computed once below. */
  frameWidth: number;
}) {
  const active = arm.active ?? true;
  const headerHeightPx = row.bodyTop - row.headerTop;
  // The header strip's own padding-edge width — see `frameWidth`'s own doc.
  const headerWidthPx = frameWidth - 2 * FRAME_BORDER_PX;
  return (
    <div
      data-slot="region-arm"
      data-arm-id={arm.id}
      data-open={String(row.open)}
      data-active={String(active)}
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: row.rowTop,
        height: row.bottom - row.rowTop,
        // WHY a single opacity token on the ROW and not per-element
        // styling: the donor fades "non-active arms, their Blocks and
        // their cables" with ONE number (branchModel.ts:38-39,
        // BRANCH_FADE_OPACITY = 0.18), and a row-level opacity carries the
        // arm's members with it for free. Cable fade is a follow-up — the
        // wires live in a sibling layer, not inside this box.
        opacity: active ? undefined : REGION_ARM_FADE_OPACITY,
      }}
    >
      {/*
        The arm's DECOR box — `v5`'s inset card, `v4`'s indent guide, nothing
        at all by default (`display: none`). WHY a real element and not a
        `::before`: this component is props in, DOM out, and a box the
        acceptance can measure (`RegionVariants.stories.tsx` reads its rect)
        has to be in the DOM. It is absolutely positioned and comes FIRST,
        and the header and body are positioned after it, so it paints
        BEHIND both in DOM order — no z-index, which the paint-order
        invariant (paintOrder.ts) would otherwise have to account for. The
        row's own box never moves for it: `expectArmsStacked` and every
        member's authored position hold in all five drawings.
      */}
      <div
        data-slot="region-arm-decor"
        aria-hidden
        style={{
          display: "var(--bbox-region-arm-decor-display, none)",
          position: "absolute",
          inset: "var(--bbox-region-arm-decor-inset, 0px)",
          width: "var(--bbox-region-arm-decor-width, auto)",
          borderStyle: "solid",
          borderWidth: "var(--bbox-region-arm-decor-stroke-widths, 0px)",
          borderColor: "var(--bbox-region-arm-decor-stroke, var(--border))",
          borderRadius: "var(--bbox-region-arm-decor-radius, 0px)",
          background: "var(--bbox-region-arm-decor-fill, transparent)",
          pointerEvents: "none",
        }}
      />
      <div
        data-slot="region-arm-header"
        // The ARM's own id, never the region's (this file's header, "the id
        // rule"): `wireLayer.tsx`'s `resolveDot` takes the FIRST
        // `[data-block-id="<id>"]` in document order, so a wire targeting
        // this arm's test/capture id has to find ITS dot inside ITS OWN
        // `[data-block-id]`, not the region's corner card.
        data-block-id={arm.id}
        style={{
          // Positioned so it paints after the decor box above (DOM order
          // among positioned boxes), never under it.
          position: "relative",
          height: row.bodyTop - row.headerTop,
          paddingLeft: "var(--bbox-region-arm-header-inset, 0px)",
          // `v3`'s band; transparent otherwise.
          background: "var(--bbox-region-arm-header-fill, transparent)",
          // A divider between rows only, never above the first — the
          // donor's own `dividerY: index === 0 ? null : rowTop`
          // (branchModel.ts). `v3`/`v4`/`v5` set its width to 0.
          borderTop: index > 0 ? "var(--bbox-region-arm-divider-width, 1px) solid var(--bbox-region-arm-divider-stroke, var(--border))" : undefined,
          // `v2`'s rule under every header; 0 otherwise.
          borderBottom: "var(--bbox-region-arm-header-rule-width, 0px) solid var(--bbox-region-arm-header-rule-stroke, var(--border))",
        }}
      >
        <Bar
          size="sm"
          // WHY `100%` and not the rung's own 28px: the header row is the
          // variant's height (26 for the bracket, 32 for the ruled), and
          // the strip fills it so the chevron and title are centred in the
          // row rather than top-biased by whatever the difference is.
          style={{ height: "100%" }}
          left={
            <>
              <FoldingChevron open={row.open} onClick={() => arm.onOpenChange?.(!row.open)} reveal={chevron} />
              <span
                data-slot="region-arm-title"
                className="truncate"
                // No fallbacks on purpose: an UNSET token is invalid at
                // computed-value time, and for these four inherited
                // properties that means `inherit` — the Bar's own text.
                // That is how `v1` says "leave the title alone" without
                // this file naming a font it does not own
                // (regionVariants.ts's own note on `initial`).
                style={{
                  fontSize: "var(--bbox-region-arm-title-size)",
                  fontWeight: "var(--bbox-region-arm-title-weight)",
                  fontFamily: "var(--bbox-region-arm-title-font)",
                  color: "var(--bbox-region-arm-title-color)",
                }}
              >
                {arm.title}
              </span>
              {/* The arm's operand, inline, AFTER its keyword — so the row
                  reads `if: mode == "fast"` in source order. This is Zach's
                  "in the title … we can support default variables so you
                  don't need to pass in everything with a pill": the dot on
                  the left wall says a value is expected and what state it is
                  in, this says what is in force while nothing is wired.
                  Rendered VERBATIM — spaces and quotes intact
                  (`feedback_truthful_property_rendering`); a cable landing
                  on the dot flips it to `wired` and this text is what the
                  cable overrides, never a second source of truth. */}
              {arm.test?.default === undefined ? null : (
                <span
                  data-slot="region-arm-test"
                  className="truncate"
                  style={{
                    fontFamily: "var(--bbox-region-arm-title-font)",
                    fontSize: "var(--bbox-region-arm-title-size)",
                    color: "var(--bbox-region-arm-title-color)",
                    opacity: 0.85,
                    // `pre` so the expression's OWN leading/trailing spaces
                    // survive (truthful property rendering) — which is also
                    // why the gap after the keyword is a margin and not a
                    // space character: a space here would be indistinguishable
                    // from one the author typed.
                    whiteSpace: "pre",
                    marginLeft: "0.4em",
                  }}
                >
                  {arm.test.default}
                </span>
              )}
            </>
          }
        />
        {/* This arm's OWN operand — `if`/`elif` only, `else` carries none
            (region.branch.ts's split). `label` is the default expression
            VERBATIM (truthful rendering: no trimming, no reformatting) —
            "" when there is none, which is how a wired-but-defaultless
            test renders no inline text at all. */}
        {arm.test !== undefined && (
          <ArmHeaderRail
            edge="left"
            items={[
              {
                id: arm.test.id,
                label: arm.test.default ?? "",
                state: arm.test.default !== undefined ? "valueSet" : "empty",
              },
            ]}
            bands={armHeaderBands(headerHeightPx, headerWidthPx)}
          />
        )}
        {/* The names this arm's PATTERN binds into its body — `match` only,
            mutually exclusive with `test` (region.branch.ts's split). One
            dot per capture, its own name as its label. */}
        {arm.captures !== undefined && arm.captures.length > 0 && (
          <ArmHeaderRail
            edge="right"
            items={arm.captures.map((name) => ({ id: name, label: name, state: "empty" }))}
            bands={armHeaderBands(headerHeightPx, headerWidthPx)}
          />
        )}
      </div>
      {row.open && (
        // WHY the body LEAVES THE DOM when folded rather than collapsing to
        // `height: 0`: `expectArmsStacked` measures a folded arm as "no
        // body", and a zero-height box that still contains members would
        // keep them hit-testable and focusable while invisible — a folded
        // arm has to be genuinely absent, not merely unpainted.
        <div
          data-slot="region-arm-body"
          style={{ position: "relative", height: row.bodyHeight }}
        >
          <BlockMembers
            layout="free"
            members={arm.members ?? []}
            gap={0}
            gutter={0}
            insetBackground="none"
            showMembers
            showCards={false}
          />
        </div>
      )}
    </div>
  );
}

/**
 * The corner card BlockRegion draws for itself when it is given a `title` and
 * no `corner`: a header-only Block that hugs its title.
 *
 * WHY no header divider: the header is the whole card, so its rule would sit
 * on the card's own bottom border and double it. WHY it hugs instead of taking
 * `REGION_CORNER_WIDTH_PX`: this is the Labeled Group's label, and React Flow's
 * reference label is as wide as its text. A region whose card carries ports
 * passes its own sized card as `corner`.
 */
function TitleCorner({
  id,
  title,
  type,
  controlPorts,
  opaque,
  measureOnly = false,
}: {
  id: string;
  title: ReactNode;
  type?: ReactNode;
  controlPorts: PortEdgeItem[];
  opaque: boolean;
  /** The measuring copy: the same Block with no `BlockPort` — so no id, no
   *  rail, no dot. Only ever used on content BlockRegion renders itself. */
  measureOnly?: boolean;
}) {
  // The copy renders primitive text only — `primitiveOnly`'s WHY.
  const titleText = measureOnly ? primitiveOnly(title) : title;
  const typeText = measureOnly && type !== undefined ? primitiveOnly(type) : type;
  const header =
    typeText === undefined ? (
      titleText
    ) : (
      <span data-slot="region-corner-heading" style={{ display: "inline-flex", gap: 6, whiteSpace: "nowrap" }}>
        <span>{titleText}</span>
        <span data-slot="region-corner-type" className="text-muted-foreground">
          {typeText}
        </span>
      </span>
    );
  if (controlPorts.length === 0) {
    return <Block header={header} showHeaderDivider={false} shape={opaque ? "card" : "region-corner"} style={{ width: "max-content" }} />;
  }
  // With control ports the card is the region's INTERFACE, so it carries the
  // region's id (this file's header: the element owning the ports owns the
  // id). WHY a body sized by the rail band: `BlockPort` places a port-view
  // rail against the Block's BODY band, so a header-only card would hang its
  // dots below itself, into the frame — the same reason `nodeViews.tsx` gives
  // its corner a `region-corner-band`.
  const card = (
    <Block
      header={header}
      width={REGION_CORNER_WIDTH_PX}
      body={<div data-slot="region-corner-band" style={{ height: regionRailBandPx(controlPorts.length) }} />}
      shape={opaque ? "card" : "region-corner"}
    />
  );
  if (measureOnly) return card;
  return (
    <BlockPort id={id} view="port" edges={{ left: { items: controlPorts } }}>
      {card}
    </BlockPort>
  );
}

/**
 * The measuring copy's content guard: a string or a number renders, anything
 * else renders NOTHING.
 *
 * WHY, when the types already limit the auto-measured arm to `RegionText`
 * (Codex re-judge 3, 2026-09-22): a cast or an `any` reaches past a type, and
 * the cost of a node reaching the copy is a portal (an open Popover, a
 * Tooltip) escaping `visibility: hidden`/`aria-hidden`/`inert` as a second,
 * visible, focusable widget. A wrong height is the lesser failure, so the copy
 * accepts it rather than ever rendering a node.
 */
function primitiveOnly(content: ReactNode): RegionText | null {
  return typeof content === "string" || typeof content === "number" ? content : null;
}

/** `RegionCornerCard` drawn. `measureOnly` is the same Block without the
 *  `BlockPort` — the id-free, dot-free measuring copy. */
function CornerCardView({
  id,
  card,
  opaque,
  measureOnly = false,
}: {
  id: string;
  card: RegionCornerCard<ReactNode>;
  opaque: boolean;
  measureOnly?: boolean;
}) {
  const text = measureOnly ? primitiveOnly(card.header) : card.header;
  // The copy's chips pass the same guard as its text: a badge that is not a
  // string/number, and any mark that is not a known `ControlMarkKind`, is
  // dropped from the copy — `primitiveOnly`'s WHY, for fields the types
  // already narrow but a cast, plain JS or a spread can still reach.
  const chips: RegionHeaderChips | undefined =
    measureOnly && card.chips !== undefined
      ? {
          badge: card.chips.badge === undefined ? undefined : (primitiveOnly(card.chips.badge) ?? undefined),
          marks: (Array.isArray(card.chips.marks) ? card.chips.marks : []).filter(isControlMarkKind),
        }
      : card.chips;
  const header =
    chips !== undefined && (chips.badge !== undefined || (chips.marks?.length ?? 0) > 0) ? (
      // The same Bar a block node's header takes when it has chips
      // (`nodeViews.tsx`'s `headerOf`): name left, chips right.
      <Bar
        size="md"
        left={text}
        right={
          <>
            {chips.badge !== undefined && (
              <Badge size="sm" variant="secondary">
                {chips.badge}
              </Badge>
            )}
            {(chips.marks ?? []).map((mark) => (
              <ControlMark key={mark} mark={mark} />
            ))}
          </>
        }
      />
    ) : (
      text
    );
  const block = (
    <Block
      header={header}
      width={card.width ?? REGION_CORNER_WIDTH_PX}
      body={card.bandHeight === undefined ? undefined : <div data-slot="region-corner-band" style={{ height: card.bandHeight }} />}
      shape={opaque ? "card" : "region-corner"}
      diagnostics={card.diagnostics}
    />
  );
  if (measureOnly) return block;
  return (
    <BlockPort id={id} view="port" edges={card.edges ?? {}}>
      {block}
    </BlockPort>
  );
}

/* ------------------------------------------------------------------ */
/* The views and the header drawings (Zach, 2026-09-22) — grown from    */
/* the sibling branch's `region.tsx`, which the 09-22 merge retired:    */
/* its RegionViewToggle is this file's BlockRegionBlackboxToggle, and   */
/* RegionPortCard / RegionOpaqueFrame / RegionTab / RegionHeaderCard /  */
/* RegionCrossingMarkers came across whole.                             */
/* ------------------------------------------------------------------ */

/** `block.tsx`'s body is `p-2`. The port card's section box cancels it with
 *  a negative margin so the split line is placed in the SAME coordinates
 *  the rail packs from (the body band's top), not 8px lower. */
const BLOCK_BODY_PADDING_PX = 8;

/** Inset of the Blackbox toggle from the frame's top-right corner. */
const REGION_TOGGLE_INSET_PX = 4;
/** `Button size="icon-xs"` is `size-6` — the toggle's own box, needed to
 *  centre it vertically in a full-width header band. */
const REGION_TOGGLE_PX = 24;

/** The wall-crossing marker's diameter and stroke — "a small HOLLOW CIRCLE
 *  sits on the wall". */
export const REGION_CROSSING_MARKER_PX = 10;
const REGION_CROSSING_STROKE_PX = 1.5;

const REGION_STROKE = "var(--bbox-region-frame-stroke, var(--border))";

/**
 * The Blackbox toggle: hollow square while expanded, FILLED while the
 * inside is hidden. The stock `Button`, so press and focus ring are
 * shadcn's.
 *
 * WHY no background behind the pressed state, only a hover ring (Zach,
 * 2026-09-22): "Once this toggle is toggled can you please not have the
 * background be a lighter grey? thats annoying. It should be more seamless."
 * The filled square alone says "pressed"; a grey plate behind it made the
 * toggle read as a button parked on the frame rather than part of it. So the
 * ghost variant's `hover:bg-muted` is replaced by a ring, at rest and pressed
 * alike. The tempting alternative, shadcn's `Toggle` with its
 * `data-pressed:bg-muted`, is exactly the lighter grey he rejected.
 *
 * WHY a square and not a `FoldingChevron`: a chevron reads "fold this row"
 * (the arms use it for exactly that), and Zach asked for no chevrons on
 * regions at all. The square is his mark for "show the inside / hide it".
 */
export function BlockRegionBlackboxToggle({
  pressed,
  onToggle,
  className,
  style,
}: {
  pressed: boolean;
  onToggle?(): void;
  className?: string;
  style?: CSSProperties;
}) {
  return (
    <Button
      data-slot="region-blackbox-toggle"
      data-state={pressed ? "opaque" : "expanded"}
      variant="ghost"
      size="icon-xs"
      aria-label="Blackbox toggle"
      aria-pressed={pressed}
      onClick={onToggle}
      className={cn("hover:bg-transparent hover:ring-1 hover:ring-ring/50 dark:hover:bg-transparent", className)}
      style={{ position: "absolute", top: REGION_TOGGLE_INSET_PX, right: REGION_TOGGLE_INSET_PX, ...style }}
    >
      <Square aria-hidden fill={pressed ? "currentColor" : "none"} />
    </Button>
  );
}

/** glyph · Title · Type on one line, centred — the port card's header. */
function RegionHeadingRow({ glyph, title, type }: { glyph?: string; title: ReactNode; type?: ReactNode }) {
  return (
    <div data-slot="region-heading" style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6, whiteSpace: "nowrap" }}>
      {glyph !== undefined && <Glyph content={glyph} sizePreset="sm" />}
      <span data-slot="region-heading-title" style={{ fontWeight: 600 }}>
        {title}
      </span>
      {type !== undefined && (
        <span data-slot="region-heading-type" className="text-muted-foreground">
          {type}
        </span>
      )}
    </div>
  );
}

/**
 * The corner TAB — Zach's sketches 2(a) and 2(b). Shaped like the corner card
 * (shares the frame's top-left radius, square where it meets the frame's
 * edges, rounded at its one free corner) but it is a LABEL, not a Block.
 *
 * WHY it carries no `data-block-id`: it owns no port. The id rule (this
 * file's header) is that the element holding the region's PORTS carries the
 * id; a tab-drawn region has no interface card, so there is nothing for a
 * wire to resolve and nothing may claim the id. A region that needs ports
 * uses `corner-card` or `full-width`.
 *
 * WHY the radii are written out rather than taken from `Block`'s
 * `shape="region-corner"`: this is not a Block. Restating the four corners
 * here is the whole of the duplication, and they read from the SAME
 * `FRAME_RADIUS` string the frame and the shape both read, so a drawing that
 * changes the region's radius moves all three together.
 */
function RegionTab({ glyph, title, type, full }: { glyph?: string; title: ReactNode; type?: ReactNode; full: boolean }) {
  return (
    <div
      data-slot="region-tab"
      data-tab={full ? "full" : "title"}
      style={{
        display: "inline-flex",
        alignItems: "center",
        padding: "3px 10px",
        fontSize: 12,
        lineHeight: "18px",
        borderStyle: "solid",
        borderWidth: FRAME_BORDER_PX,
        borderColor: REGION_STROKE,
        borderTopLeftRadius: FRAME_RADIUS,
        borderTopRightRadius: 0,
        borderBottomLeftRadius: 0,
        borderBottomRightRadius: FRAME_RADIUS,
      }}
    >
      <RegionHeadingRow glyph={full ? glyph : undefined} title={title} type={full ? type : undefined} />
    </div>
  );
}

/**
 * The FULL-WIDTH header — Zach's sketches 2(c), 5 and 6. A real `BlockPort`
 * whose id IS the region's, stretched across the frame, its control ports on
 * its own left wall (which is the frame's left wall).
 *
 * WHY this bar, and not the frame or the root, carries `data-block-id`:
 * the id rule is "the element that owns the region's ports owns its id".
 * With a full-width header the control ports live INSIDE the bar ("ONE
 * control port at the left end INSIDE the header bar"), so the bar is the
 * interface card — the corner card, grown to the frame's width, exactly the
 * `v10` "band" reading ("its just the block is stretch accross the entire
 * width of the region", Zach 2026-09-20). A wire into a control port
 * therefore resolves through the same `[data-block-id]` → `[data-port-id]`
 * walk as ever, and `wireLayer.tsx`'s first-match lookup still finds a box
 * that owns the dot. Stamping the frame instead would win that lookup and
 * strand every control-port wire — the failure this file's header names.
 */
function RegionHeaderCard({
  id,
  glyph,
  title,
  type,
  controlPorts,
  width,
}: {
  id: string;
  glyph?: string;
  title: ReactNode;
  type?: ReactNode;
  controlPorts: PortEdgeItem[];
  width: number;
}) {
  return (
    <BlockPort id={id} view="port" edges={controlPorts.length > 0 ? { left: { items: controlPorts } } : {}}>
      <Block
        width={width}
        // One band formula for this bar AND the opaque face's band, so the
        // rule does not jump when the toggle flips (`regionHeaderBandPx`).
        height={regionHeaderBandPx(controlPorts.length)}
        body={<RegionHeadingRow glyph={glyph} title={title} type={type} />}
        style={{
          borderTopLeftRadius: FRAME_RADIUS,
          borderTopRightRadius: FRAME_RADIUS,
          borderBottomLeftRadius: 0,
          borderBottomRightRadius: 0,
          boxShadow: "none",
        }}
      />
    </BlockPort>
  );
}

/**
 * The wall-crossing markers (Zach's sketches 4 and 6): a small hollow circle
 * wherever a cable crosses the frame. Laid over the frame's BORDER box
 * (`inset: -1px` from the padding box the frame's children see), so a
 * frame-local point from `wallCrossings` is used as-is.
 *
 * Painted at `portDot` (paintOrder.ts): the marker sits where a port WOULD
 * be — on the wall, above the frame's own content — and the region root that
 * emits the tier is `isolation: isolate`, so it can never climb over
 * anything outside this region.
 */
function RegionCrossingMarkers({ points }: { points: readonly RegionPoint[] }) {
  if (points.length === 0) return null;
  const radius = REGION_CROSSING_MARKER_PX / 2;
  return (
    <div
      data-slot="region-crossings"
      aria-hidden
      style={{ position: "absolute", inset: -FRAME_BORDER_PX, pointerEvents: "none", zIndex: paintTier("portDot") }}
    >
      {points.map((point, index) => (
        <span
          key={index}
          data-slot="region-crossing"
          style={{
            position: "absolute",
            left: point.x - radius,
            top: point.y - radius,
            width: REGION_CROSSING_MARKER_PX,
            height: REGION_CROSSING_MARKER_PX,
            boxSizing: "border-box",
            borderRadius: "50%",
            border: `${REGION_CROSSING_STROKE_PX}px solid var(--foreground)`,
            background: "transparent",
          }}
        />
      ))}
    </div>
  );
}

/**
 * The Expanded Opaque face's centre: a large glyph, then Title over Type.
 * Ported from the sibling branch's `blockOpaqueTitle.tsx` (`BlockOpaqueTitle`)
 * as a private piece, because this lineage has no such component and only
 * this face uses it.
 */
function RegionOpaqueTitle({ glyph, title, type }: { glyph?: string; title: ReactNode; type?: ReactNode }) {
  return (
    <div data-slot="region-opaque-title" style={{ display: "flex", alignItems: "center", gap: 8 }}>
      {glyph !== undefined && <Glyph content={glyph} sizePreset="lg" />}
      <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", lineHeight: 1.2 }}>
        <span data-slot="region-opaque-title-name" style={{ fontWeight: 600 }}>
          {title}
        </span>
        {type !== undefined && (
          <span data-slot="region-opaque-title-type" className="text-muted-foreground" style={{ fontSize: 12 }}>
            {type}
          </span>
        )}
      </div>
    </div>
  );
}

/** The ordinary ports' rails: left after the control ports, right pushed
 *  down to start at slot `ordinaryStart`. */
function sectionEdges(
  controlPorts: PortEdgeItem[],
  boundaryPorts: Partial<Record<"left" | "right", PortEdgeItem[]>>,
  ordinaryStart: number,
): Partial<Record<BlockSide, BlockEdgeSpec>> {
  const left = [...controlPorts, ...(boundaryPorts.left ?? [])];
  const right = boundaryPorts.right ?? [];
  const aligned = (slots: number) => ({ mode: "aligned" as const, anchor: "start" as const, gap: RAIL_GAP_PX, edgePadding: offsetEdgePaddingPx(slots) });
  const edges: Partial<Record<BlockSide, BlockEdgeSpec>> = {};
  if (left.length > 0) edges.left = { items: left, distribution: aligned(ordinaryStart - controlPorts.length) };
  if (right.length > 0) edges.right = { items: right, distribution: aligned(ordinaryStart) };
  return edges;
}

/**
 * The PORT view: the region collapsed to a block. Header row glyph + Title
 * Type; the control ports first; a ruled line; then the ordinary (boundary)
 * ports — the left ones under the control ports, the right ones starting
 * BELOW the line, not beside a control port.
 *
 * WHY the right rail is pushed down rather than sharing rows: the line is a
 * statement about the whole card — "above it is how you drive the region,
 * below it is what flows through" — so no ordinary port may sit above it on
 * either wall. The push is `offsetEdgePaddingPx`, the device
 * `portLayout: "offset"` already uses to put one lane below another.
 */
function RegionPortCard({
  id,
  glyph,
  title,
  type,
  controlPorts,
  boundaryPorts,
  footer,
}: {
  id: string;
  glyph?: string;
  title: ReactNode;
  type?: ReactNode;
  controlPorts: PortEdgeItem[];
  boundaryPorts: Partial<Record<"left" | "right", PortEdgeItem[]>>;
  footer?: ReactNode;
}) {
  const nControl = controlPorts.length;
  const slots = Math.max(nControl + (boundaryPorts.left?.length ?? 0), nControl + (boundaryPorts.right?.length ?? 0));
  const split = regionControlSplitPx(nControl);
  return (
    <BlockPort id={id} view="port" edges={sectionEdges(controlPorts, boundaryPorts, nControl)}>
      <Block
        width={REGION_CARD_WIDTH_PX}
        header={<RegionHeadingRow glyph={glyph} title={title} type={type} />}
        body={
          slots > 0 ? (
            <div
              data-slot="region-port-sections"
              // `flex: 1` (not `alignSelf: stretch`): the body is a flex ROW,
              // so stretch only reaches the height — the width has to grow
              // along the main axis, into the padding the margin gives back.
              style={{ position: "relative", flex: 1, margin: -BLOCK_BODY_PADDING_PX, height: regionRailBandPx(slots) }}
            >
              {split !== null && (
                <div
                  data-slot="region-control-split"
                  aria-hidden
                  style={{ position: "absolute", left: 0, right: 0, top: split - FRAME_BORDER_PX / 2, height: FRAME_BORDER_PX, background: REGION_STROKE }}
                />
              )}
            </div>
          ) : undefined
        }
        footer={footer}
      />
    </BlockPort>
  );
}

/**
 * The frame's own box paint — widths, dash, colour, radii, fill — shared by
 * the expanded frame and the Expanded Opaque face.
 *
 * WHY one function and not the face imitating the frame with a restyled
 * Block (Codex audit, 2026-09-22): a Block carries its own border on all
 * four sides and one radius on every corner, so under `v4`'s open bracket
 * (`1px 0 0 1px`, asymmetric radii) pressing the toggle closed the bracket
 * into a full box, and under the default skin the border jumped 1px → 2px.
 * Every token the frame reads, the face now reads through this ONE object,
 * so the two cannot drift. (BlockRegion is to become a Block preset — this
 * is the minimal local fix, not that refactor.)
 */
function frameBoxStyle(width: number, height: number): CSSProperties {
  return {
    position: "relative",
    width,
    height,
    // Four widths so the bracket (`v4`) can open the right and the
    // bottom; every variant keeps the top and the left at
    // FRAME_BORDER_PX, the corner card's home.
    borderWidth: `var(--bbox-region-frame-stroke-widths, ${FRAME_BORDER_PX}px)`,
    borderStyle: "var(--bbox-region-frame-dash, solid)",
    borderColor: "var(--bbox-region-frame-stroke, var(--border))",
    borderRadius: `var(--bbox-region-frame-radii, ${FRAME_RADIUS})`,
    // Transparent by default, so a cable routed UNDER the frame still
    // reads, and `visible` so the corner card's wall dots may
    // straddle the frame's own edge instead of being clipped off at
    // it (plan §9's "no clip" default — and Zach's `115050`, where
    // the app's frame cut a port in half).
    background: "var(--bbox-region-fill-here)",
    overflow: "visible",
  };
}

/**
 * The Expanded Opaque face: the frame at its expanded size, no members, the
 * boundary ports on its walls, the control ports boxed into the corner by an
 * L, and glyph / Title / Type centred.
 *
 * WHY ONE `BlockPort` + `Block` and not the frame div with ports stuck on:
 * the region's id must resolve to ONE box owning EVERY port the face shows,
 * because `wireLayer.tsx` takes the first `[data-block-id]` and looks only
 * inside it. Two id-carrying boxes would leave one set unresolvable.
 */
function RegionOpaqueFrame({
  id,
  glyph,
  title,
  type,
  fullWidth,
  controlPorts,
  boundaryPorts,
  width,
  height,
  toggle,
  footer,
}: {
  id: string;
  glyph?: string;
  title: ReactNode;
  type?: ReactNode;
  /** The expanded drawing was `headerStyle="full-width"`, so the face keeps
   *  its band instead of boxing the control ports into an L. */
  fullWidth: boolean;
  controlPorts: PortEdgeItem[];
  boundaryPorts: Partial<Record<"left" | "right", PortEdgeItem[]>>;
  width: number;
  height: number;
  toggle: ReactNode;
  footer?: ReactNode;
}) {
  // Full-width: the band is always there (it IS the header), so the ordinary
  // ports start under it even with no control ports at all.
  const ordinaryStart = fullWidth ? Math.max(controlPorts.length, 1) : controlPorts.length;
  const split = fullWidth ? regionHeaderBandPx(controlPorts.length) : regionControlSplitPx(controlPorts.length);
  return (
    // The paint is the FRAME's (`frameBoxStyle`) — the same box the expanded
    // view drew, only with its inside hidden, which is also why the pressed
    // toggle has no plate of its own to sit on.
    <div data-slot="region-opaque-face" style={frameBoxStyle(width, height)}>
      {/*
        The ports' owner: an INVISIBLE Block laid exactly over the frame's
        border box (pulled back by the top/left border every variant keeps at
        FRAME_BORDER_PX), so its rails put the dots ON the frame's walls. Its
        own border is transparent and keeps its width, so the box — and every
        dot — is where a visible one would be; what paints is the frame.
      */}
      <div style={{ position: "absolute", top: -FRAME_BORDER_PX, left: -FRAME_BORDER_PX }}>
        <BlockPort id={id} view="port" edges={sectionEdges(controlPorts, boundaryPorts, ordinaryStart)}>
          <Block
            width={width}
            height={height}
            // Full-width: the words live in the BAND below, not in the middle
            // of the face — the band is the header this drawing had while it
            // was expanded, so the toggle must not move them.
            body={fullWidth ? undefined : <RegionOpaqueTitle glyph={glyph} title={title} type={type} />}
            footer={footer}
            style={{ background: "transparent", boxShadow: "none", borderColor: "transparent", borderRadius: FRAME_RADIUS }}
          />
        </BlockPort>
      </div>
      {fullWidth ? (
        <>
          {/*
            WHY `split - 2 * FRAME_BORDER_PX` and not `split - ½px`: this line
            has to land on the exact pixel row the EXPANDED drawing's header
            card painted its own bottom border on, or the rule visibly jumps
            when the toggle is pressed. The band's box starts at
            `-FRAME_BORDER_PX` in this padding box (border-box y = 0) and is
            `split` tall, so its last border row is border-box
            `[split-1, split]` — which is `split - 2` here. It is the same
            expression `region-header-rule` uses against `layout.corner.h` in
            the expanded frame, for the same reason and against the same box
            (a full-width region's `corner.h` IS `regionHeaderBandPx`).
          */}
          <div
            data-slot="region-control-split"
            data-split="band"
            aria-hidden
            style={{
              position: "absolute",
              left: -FRAME_BORDER_PX,
              right: -FRAME_BORDER_PX,
              top: split! - 2 * FRAME_BORDER_PX,
              height: FRAME_BORDER_PX,
              background: REGION_STROKE,
              pointerEvents: "none",
            }}
          />
          <div
            data-slot="region-opaque-band"
            style={{
              position: "absolute",
              left: -FRAME_BORDER_PX,
              right: -FRAME_BORDER_PX,
              top: -FRAME_BORDER_PX,
              height: split!,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              pointerEvents: "none",
            }}
          >
            <RegionHeadingRow glyph={glyph} title={title} type={type} />
          </div>
        </>
      ) : (
        split !== null && (
          // An L — across under the control ports, then up to the top wall —
          // boxing them into the corner, split from the ordinary ports.
          <div
            data-slot="region-control-split"
            data-split="corner"
            aria-hidden
            style={{
              position: "absolute",
              left: -FRAME_BORDER_PX,
              top: -FRAME_BORDER_PX,
              width: REGION_CONTROL_BOX_WIDTH_PX,
              height: split + FRAME_BORDER_PX / 2,
              borderRight: `${FRAME_BORDER_PX}px solid ${REGION_STROKE}`,
              borderBottom: `${FRAME_BORDER_PX}px solid ${REGION_STROKE}`,
              pointerEvents: "none",
            }}
          />
        )
      )}
      {toggle}
    </div>
  );
}

export function BlockRegion({
  id,
  kind = "group",
  view = "expanded",
  title,
  corner: givenCorner,
  cornerCard,
  cornerSize,
  width,
  height,
  members,
  arms,
  glyph,
  type,
  controlPorts,
  boundaryPorts,
  opaqueFace = "card",
  headerStyle = "corner-card",
  crossings,
  onToggleView,
  toggleClassName,
  hiddenFooter,
  className,
  style,
}: BlockRegionProps) {
  const corner =
    givenCorner ??
    (cornerCard !== undefined ? (
      <CornerCardView id={id} card={cornerCard} opaque={view === "opaque"} />
    ) : title === undefined ? null : (
      <TitleCorner id={id} title={title} type={type} controlPorts={controlPorts ?? []} opaque={view === "opaque"} />
    ));
  const [root, setRoot] = useState<HTMLDivElement | null>(null);
  const variant = useRegionVariant(root);
  const spec = REGION_VARIANTS[variant];
  const fullWidthHeader = headerStyle === "full-width";
  // `regionLayout` applies exactly this clamp to `width`, so computing it
  // here cannot drift from `layout.width` — and the full-width header has to
  // know the frame's width BEFORE the layout runs, because it IS the corner
  // whose height the layout is waiting for.
  const frameWidth = Math.max(width ?? REGION_CORNER_WIDTH_PX, REGION_MIN_WIDTH_PX);
  // WHY a full-width header is never MEASURED: its height is a closed form
  // of the control-port count (`regionHeaderBandPx`), the same number the
  // Expanded Opaque band uses — so declaring it here keeps the two faces on
  // one formula AND removes the first-frame guess a measurement would need.
  // A tab and a corner card still measure: both hug their own content.
  const declaredCornerSize = fullWidthHeader ? { w: frameWidth, h: regionHeaderBandPx((controlPorts ?? []).length) } : cornerSize;
  const { ref: cornerRef, size } = useCornerSize(declaredCornerSize);
  const layout = regionLayout({
    width: frameWidth,
    ...(height === undefined ? null : { height }),
    corner: size,
    armHeaderPx: spec.arms.headerPx,
    arms: (arms ?? []).map((arm) => ({
      id: arm.id,
      open: arm.open,
      ...(arm.bodyHeight === undefined ? null : { bodyHeight: arm.bodyHeight }),
    })),
  });

  /** Does THIS region paint the header rule at all? See the rule's own WHY
   *  below for the two halves. Computed here so the frame and any future
   *  reader agree on one answer. */
  const drawsHeaderRuleHere = kind !== "loop" && layout.arms.length > 0;

  const rootProps = {
    "data-slot": "region",
    "data-region-id": id,
    "data-region-kind": kind,
    "data-region-view": view,
    // Informational — which drawing this region resolved to. NOT the switch
    // attribute (`data-bbox-region-variant`), which stays the host's to
    // stamp: writing it here would shadow every ancestor's choice.
    "data-region-variant": variant,
    "data-region-header-style": headerStyle,
  } as const;

  // The words the port card, the tab, the full-width bar and the opaque face
  // paint for themselves. The id is the fallback because it is the one
  // truthful name a region always has.
  const words = { glyph, title: title ?? id, type };

  /** The toggle, placed: vertically centred in a full-width header band,
   *  else in the frame's top-right corner (the toggle's own default inset).
   *  The band's box starts at `-FRAME_BORDER_PX` in the padding box it is
   *  placed in, which is where the subtraction comes from — and because a
   *  full-width region's `corner.h` IS `regionHeaderBandPx`, the expanded
   *  frame and the Expanded Opaque face read the identical expression, so
   *  the square does not move when pressed. */
  const toggleNode = onToggleView ? (
    <BlockRegionBlackboxToggle
      pressed={view === "opaque"}
      onToggle={onToggleView}
      className={toggleClassName}
      {...(fullWidthHeader ? { style: { top: (layout.corner.h - REGION_TOGGLE_PX) / 2 - FRAME_BORDER_PX } } : null)}
    />
  ) : null;

  // Expanded Opaque does not draw the corner, yet its size depends on the
  // corner's height (`regionLayout`), and a region loaded straight into it
  // was sized off the fallback height (0) and grew when toggled open and
  // shut. So, unless the caller already gave `cornerSize`, it mounts a
  // hidden copy of the expanded-view corner purely to measure it — and ONLY
  // of content it renders itself (`cornerCard`, the `title` card), built
  // without a `BlockPort`, so the copy has no id, rail or dot for
  // `wireLayer` to resolve. An arbitrary `corner` is never copied (it could
  // hold a portal); `RegionCornerProps` makes its caller pass `cornerSize`.
  //
  // A TAB is BlockRegion's own drawing too, so it is copied under the same
  // guard: its words go through `primitiveOnly`, never a caller's node. A
  // FULL-WIDTH header is never copied at all — `declaredCornerSize` already
  // knows its height in closed form.
  const measureCorner =
    headerStyle === "corner-tab" || headerStyle === "corner-tab-full" ? (
      <RegionTab
        glyph={glyph}
        title={primitiveOnly(words.title) ?? ""}
        type={words.type === undefined ? undefined : (primitiveOnly(words.type) ?? undefined)}
        full={headerStyle === "corner-tab-full"}
      />
    ) : givenCorner !== undefined ? null : cornerCard !== undefined ? (
      <CornerCardView id={id} card={cornerCard} opaque={false} measureOnly />
    ) : title === undefined ? null : (
      <TitleCorner id={id} title={title} type={type} controlPorts={controlPorts ?? []} opaque={false} measureOnly />
    );
  const measureTwin = declaredCornerSize === undefined && view === "opaque" && opaqueFace === "frame" ? measureCorner : null;

  // Port: the region as a block. The root keeps the region id; the card
  // carries the block id (the one-owner rule, `RegionPortCard`). No toggle:
  // the Blackbox toggle flips Expanded ⇄ Expanded Opaque, and leaving Port
  // is the host's view selector's job.
  if (view === "port") {
    return (
      <div {...rootProps} ref={setRoot} className={className} style={{ width: "max-content", ...style }}>
        <RegionPortCard id={id} {...words} controlPorts={controlPorts ?? []} boundaryPorts={boundaryPorts ?? {}} footer={hiddenFooter} />
      </div>
    );
  }

  // Expanded Opaque: the frame's box with its inside hidden, at the size the
  // expanded view laid out.
  if (view === "opaque" && opaqueFace === "frame") {
    return (
      <div
        {...rootProps}
        data-region-opaque-face="frame"
        ref={setRoot}
        className={className}
        style={{
          position: "relative",
          width: "max-content",
          ...({ "--bbox-region-fill-here": "var(--bbox-region-frame-fill, transparent)" } as CSSProperties),
          // The isolation invariant (paintOrder.ts): this root's subtree can
          // emit the `portDot` tier, so it walls it off. Harmless when it
          // does not — `isolation: isolate` changes nothing a root without a
          // z-indexed descendant could observe.
          ...ISOLATED_ROOT_STYLE,
          ...style,
        }}
      >
        <RegionOpaqueFrame
          id={id}
          {...words}
          fullWidth={fullWidthHeader}
          controlPorts={controlPorts ?? []}
          boundaryPorts={boundaryPorts ?? {}}
          width={layout.width}
          height={layout.height}
          footer={hiddenFooter}
          // Placed in the face's padding box, exactly as the expanded frame
          // places it — the face IS the frame's box now, so the square does
          // not move by a pixel when pressed.
          toggle={toggleNode}
        />
        {measureTwin !== null && (
          <div
            ref={cornerRef}
            data-slot="region-corner-measure"
            aria-hidden
            inert
            style={{ position: "absolute", top: 0, left: 0, width: "max-content", visibility: "hidden", pointerEvents: "none" }}
          >
            {measureTwin}
          </div>
        )}
      </div>
    );
  }

  // P5, opaque: the root wraps ONLY the corner card — the host's, or with
  // `title` the one `TitleCorner` draws, which turns itself back into a plain
  // `card` here. No frame, no arms, no body — the whole point of the view is
  // that the inside is not drawn. The card's own ports and footer are the
  // host's business (`nodeViews.tsx`), which is why this branch renders
  // `corner` untouched — and why no variant token is read here: the opaque
  // card reads the same in every drawing by design.
  if (view === "opaque") {
    return (
      <div {...rootProps} ref={setRoot} className={className} style={{ width: "max-content", ...style }}>
        {corner}
      </div>
    );
  }

  return (
    <div
      {...rootProps}
      ref={setRoot}
      className={className}
      style={{
        position: "relative",
        width: "max-content",
        // The fill THIS frame paints, captured at the root: the token as
        // inherited from outside this region. The frame below re-declares
        // `--bbox-region-frame-fill` for its DESCENDANTS as the variant's
        // nested fill, so a region inside this one reads "one tone deeper"
        // while this frame itself still reads the outer value — the
        // capture on the root is what breaks the self-reference.
        ...({ "--bbox-region-fill-here": "var(--bbox-region-frame-fill, transparent)" } as CSSProperties),
        // The isolation invariant (paintOrder.ts): the crossing markers below
        // emit the `portDot` tier, so this root walls it off.
        ...ISOLATED_ROOT_STYLE,
        ...style,
      }}
    >
      <div
        data-slot="region-frame"
        data-region-id={id}
        style={{
          ...frameBoxStyle(layout.width, layout.height),
          // For descendants only (see the root's note): a nested frame
          // reads the variant's nested fill, or this frame's own fill when
          // the variant draws no nesting contrast.
          ...({ "--bbox-region-frame-fill": "var(--bbox-region-nested-fill, var(--bbox-region-fill-here))" } as CSSProperties),
        }}
      >
        {/*
          `v2`'s header RULE — the line Zach pointed at in `Pasted image
          20260919115353.png`: the corner card's bottom edge continued across
          the full width of the frame. Rendered BEFORE the corner so the
          card paints over its left run, and placed on the card's own bottom
          border row — the card is pulled back by FRAME_BORDER_PX, so its
          last pixel row is `corner.h - 2 * FRAME_BORDER_PX` in the frame's
          padding box — so the two are one line, not two a pixel apart.
          `display: none` unless the variant turns it on.

          WHY it is ALSO gated on having arms (Zach, 2026-09-20, on v9: "For
          loop and while loops like this no inside lines", against a Branch
          shown WITH them): this rule is the bottom edge of the HEADER BAND —
          it exists to divide the header from the titled arm rows underneath.
          A `for`/`while` region has no arms at all (`FOR_LOOP_PRESET.arms:
          []`; its body is the frame itself), so under v2/v9/v10 — the three
          variants that set `--bbox-region-header-rule-display: block` — it
          was drawing a full-width line across an empty body, dividing
          nothing from nothing.

          BOTH halves of the predicate are load-bearing. `arms.length > 0`
          is the honest test — the arm rows are what the line separates, so a
          branch that lost its arms loses the rule with them. `kind !== "loop"`
          is the belt: a loop must never draw it even holding malformed data,
          and that case is REAL, not hypothetical — `variants.smoke.test.tsx`'s
          own `regionOfKind` helper mints every kind with one `body` arm, so an
          arms-only gate would have kept painting the rule on the very for/while
          regions Zach is complaining about. A future arm-bearing kind (match /
          case) still keeps its rule, because only `"loop"` is excluded.

          The tempting alternative — scoping the token in `regionVariants.css`
          off the already-stamped `[data-region-kind]` — cannot work: this
          display is an INLINE style, so it outranks any stylesheet rule no
          matter how specific.
        */}
        <div
          data-slot="region-header-rule"
          aria-hidden
          style={{
            display: drawsHeaderRuleHere ? "var(--bbox-region-header-rule-display, none)" : "none",
            position: "absolute",
            left: 0,
            right: 0,
            top: layout.corner.h - 2 * FRAME_BORDER_PX,
            height: FRAME_BORDER_PX,
            background: "var(--bbox-region-header-rule-stroke, var(--border))",
            pointerEvents: "none",
          }}
        />
        <div
          ref={cornerRef}
          data-slot="region-corner"
          style={{
            position: "absolute",
            // Pulled back by the frame's border so the two borders land on
            // one line: the corner reads as PART of the frame, which is the
            // whole Labeled Group Node look.
            top: -FRAME_BORDER_PX,
            left: -FRAME_BORDER_PX,
            width: "max-content",
          }}
        >
          {headerStyle === "corner-card" ? (
            corner
          ) : fullWidthHeader ? (
            <RegionHeaderCard id={id} {...words} controlPorts={controlPorts ?? []} width={layout.width} />
          ) : (
            <RegionTab {...words} full={headerStyle === "corner-tab-full"} />
          )}
        </div>
        <div
          data-slot="region-body"
          style={{ position: "absolute", left: 0, top: layout.body.y, width: "100%", height: layout.body.h }}
        >
          <BlockMembers
            layout="free"
            members={members ?? []}
            gap={0}
            gutter={0}
            insetBackground="none"
            showMembers
            showCards={false}
          />
        </div>
        {layout.arms.map((row, index) => (
          <ArmRow key={row.id} arm={(arms ?? [])[index]} row={row} index={index} chevron={spec.arms.chevron} frameWidth={layout.width} />
        ))}
        {/* Last in DOM order, so it paints over any member or arm row that
            reaches the top-right corner without needing a z-index. */}
        {toggleNode}
        <RegionCrossingMarkers points={crossings ?? []} />
      </div>
    </div>
  );
}

// src/components/blockRegion.views.layout.ts — the pure geometry under
// BlockRegion's VIEWS (Zach, 2026-09-22: "regions do not have a simple view.
// they just have port, expanded and expanded opaque view"): where the line
// splitting control ports from ordinary ports sits, how tall a rail band of
// `n` slots is, and how tall a full-width header band is.
//
// Pure: no React, no DOM. `blockRegion.tsx` paints from these numbers and
// `blockRegion.views.layout.test.ts` pins them without mounting anything.
//
// ── ONE MODULE, NOT TWO (merge, 2026-09-22) ─────────────────────────────
// This file and the sibling lineage's `regionViews.layout.ts` each held a
// byte-identical `regionControlSplitPx` / `regionRailBandPx`, because each
// lineage grew its own views on its own component. Two derivations of one
// number is exactly the failure `scene/portEdgeCrossing.ts`'s header warns
// about — a fix to one silently leaves the other painting the old line — so
// the merge folds `regionViews.layout.ts` in here rather than keeping both.
// `regionHeaderBandPx` arrives from that file unchanged; its `wallCrossings`
// lands in `blockRegion.crossings.ts` for the reason below.
//
// PROVENANCE (docs/ALGORITHM-PROVENANCE.md, "Region views"):
//   • `regionControlSplitPx` / `regionRailBandPx` / `regionHeaderBandPx` —
//     class (c), ours: the rail pitch arithmetic `blockPort.layout.ts`
//     already states (`railPitchPx`, `offsetEdgePaddingPx`,
//     `alignedFirstCentrePx`), read back as "where is the gap between slot
//     n-1 and slot n". No prior art claimed.
//
// WHY `wallCrossings` is NOT here but in `blockRegion.crossings.ts`, one file
// over: it needs the elbow clipper, and this module is inside
// `blockRegion.tsx`'s import closure, which is what `registry.json`'s
// `block-region` item ships. Pulling `./elbow` in behind the component made
// the generator's own sibling check fail — "this registry would install and
// then fail to compile", because `elbow/` is a directory the walk does not
// land as a sibling. Nothing the COMPONENT paints needs a clipper: it is
// handed points. Measured 2026-09-22 by `docs/build_menu_registry_items.py`.

import { PORT_EDGE_SLOT_MIN_PX, RAIL_GAP_PX, railPitchPx } from "./blockPort.layout";

/** A point in a region frame's OWN coordinates — its border-box top-left is
 *  0,0. What `BlockRegion`'s `crossings` prop paints in. */
export interface RegionPoint {
  x: number;
  y: number;
}

/** How far into the opaque frame the L-split corner box reaches — room for
 *  a `port Any` label beside its dot. A constant, not a measurement: a
 *  longer control-port label crosses the L's upright rather than moving it. */
export const REGION_CONTROL_BOX_WIDTH_PX = 112;

/**
 * The y, measured from the top of the band the rail packs from, of the line
 * that splits the first `controlCount` slots (the control ports) from the
 * ones after them (the ordinary ports) — the midpoint of the gap between
 * slot `n-1`'s bottom and slot `n`'s top on an `aligned`/`start` rail.
 * `null` when there are no control ports: no section, no line.
 *
 * WHY the gap's midpoint and not a slot edge: Zach's port-view sketch draws
 * the line BETWEEN the two groups with room on both sides; a line on slot
 * `n`'s top edge would touch the first ordinary port's label box.
 */
export function regionControlSplitPx(controlCount: number, slotMainPx: number = PORT_EDGE_SLOT_MIN_PX, gap: number = RAIL_GAP_PX): number | null {
  if (controlCount <= 0) return null;
  return controlCount * railPitchPx(slotMainPx, gap) - gap / 2;
}

/**
 * The band `slotCount` aligned slots need, px: `n` slots and `n-1` gaps
 * (0 for no slots) — the same sum `scene/fitToContent.ts`'s
 * `railBandHeightForSlots` makes, restated because `src/components` may not
 * import the scene kit (`layering.test.ts`'s import wall).
 * `blockRegion.views.layout.test.ts` pins the two against each other.
 */
export function regionRailBandPx(slotCount: number, slotMainPx: number = PORT_EDGE_SLOT_MIN_PX, gap: number = RAIL_GAP_PX): number {
  if (slotCount <= 0) return 0;
  return slotCount * slotMainPx + (slotCount - 1) * gap;
}

/**
 * The full-width header band's height for `controlCount` control ports
 * stacked inside it — exactly where the split line would fall under them,
 * with ONE slot's worth as the floor so a header with no ports (or one) is
 * still a bar a glyph and a title fit in.
 *
 * WHY it is the split and not a hugged box: the expanded header card and
 * the opaque face draw the same band (sketch 6's header, sketch 4's opaque
 * "w/ opaque toggled" when the drawing is full-width), and they must agree
 * to the pixel or the toggle visibly moves the rule. One formula, both
 * faces.
 */
export function regionHeaderBandPx(controlCount: number): number {
  return regionControlSplitPx(Math.max(controlCount, 1)) as number;
}

"use client";

// src/components/button.tsx — copied verbatim from
// apps/docs/src/registry/new-york-v4/ui/button.tsx (the stock shadcn `new-york`
// Button over Base UI), only the `cn` import path changed to match this app,
// plus the Bar size cascade (barSize.tsx) below.
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BUTTON_SIZE, useBarSize } from "./barSize";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a]:hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

// Sizes whose radius is already a deliberate, non-skin CLAMP —
// `rounded-[min(var(--radius-md),10-12px)]`, tuned so a tiny icon button
// never balloons toward a circle. The skin seam below does not reach these:
// letting `--bbox-skin-radius` win here would fight that clamp every render
// (a skin's radius could easily exceed the clamp's own ceiling) and, worse,
// silently drop it back to nothing on a "default"-fallback skin. Only the
// UNCLAMPED sizes — the ones that fall through to `buttonVariants`' own
// plain `rounded-lg` — get the token.
const CLAMPED_RADIUS_SIZES = new Set(["xs", "sm", "icon-xs", "icon-sm"]);

function Button({
  className,
  variant = "default",
  size,
  style,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  // Explicit `size` wins; the ambient Bar cascade (barSize.tsx) is only the
  // fallback when `size` itself is omitted, `"default"` (this component's
  // original default) is the floor when there is no Bar ancestor either.
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BUTTON_SIZE[barSize]) ?? "default";
  return (
    <ButtonPrimitive
      data-slot="button"
      data-size={resolvedSize}
      className={cn(buttonVariants({ variant, size: resolvedSize, className }))}
      style={{
        // The skin seam (src/skin/skin.ts + skin.css). `var(--radius-lg)`
        // is exactly what the base class's own `rounded-lg` resolves to,
        // so a consumer who never imports skin.css is byte-identical.
        ...(CLAMPED_RADIUS_SIZES.has(resolvedSize ?? "default") ? null : { borderRadius: "var(--bbox-skin-radius, var(--radius-lg))" }),
        // `outline` is the one variant with a REAL, visible border
        // (`border-border dark:border-input`) — every other variant is
        // `border-transparent` and has nothing for a skin to suppress.
        // Same split Badge's own `outline` variant makes for
        // `--bbox-skin-line-override`. Fallback is `--color-input`, not
        // `--color-border`, on purpose: this app's theme (`globals.css`)
        // gives `--input` the SAME value as `--border` in light mode and
        // the dark-mode-CORRECT value already (the exact value
        // `dark:border-input` supplied), so one literal is
        // byte-identical in both — an inline style can't express a media
        // query the way the two Tailwind classes did.
        ...(variant === "outline" ? { borderColor: "var(--bbox-skin-line-override, var(--color-input))" } : null),
        ...style,
      }}
      {...props}
    />
  );
}

export { Button, buttonVariants };

/*
 * CodeEditor — reconciled from packages/bbox-ui/src/codeField.css (current
 * on main: the box chrome, caret/selection/placeholder colours) and
 * claude/code-block-primitive's codeBlock.css (recovered: the opaque
 * gutter, the overflow/scroll variants, the tok-* syntax palette — all
 * deleted from main's codeField.css by 368a524's trim). Colours are stock
 * shadcn tokens (src/globals.css) — this app carries no bbox-* theme
 * tokens, so the `var(--bbox-accent, #4f6ee5)` shape below always falls
 * through to its literal, same pattern as editableText.tsx's
 * `var(--bbox-ring, currentColor)`.
 */

.bbox-code-editor {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 4px 6px;
  /*
   * The skin seam (src/skin/skin.ts + skin.css), same pattern this file's
   * own `--bbox-tok-*` lines already use one level down: a token read at
   * the call site with TODAY'S value (1px solid var(--color-border), 6px)
   * as its own `var()` fallback, so a consumer who never imports skin.css
   * renders exactly the pixels this replaced.
   */
  border: var(--bbox-skin-stroke-width, 1px) solid var(--bbox-skin-stroke, var(--color-border));
  border-radius: var(--bbox-skin-radius, 6px);
  /* `--bbox-tok-bg`/`--bbox-tok-fg` (codeEditorTheme.ts) still take
     precedence — a syntax theme is a background + foreground pair, not
     just token colours, and a Dark Modern editor on a sketch-skinned
     page is still Dark Modern. Only once NEITHER a theme nor a skin sets
     one does it fall through to today's literal, unchanged. */
  background: var(--bbox-tok-bg, var(--bbox-skin-surface, var(--color-card)));
  color: var(--bbox-tok-fg, var(--bbox-skin-fg, var(--color-foreground)));
  cursor: text;
  overflow: hidden;
}

/*
 * NO `SketchOutline` here, unlike Block/Badge/Port — a deliberate scope
 * boundary, not an oversight: CodeMirror's `EditorView` mounts itself
 * imperatively into `.bbox-code-editor` via `hostRef` (codeEditor.tsx),
 * which is the sole child React ever manages on that node. A drawn
 * outline needs to be a SIBLING (so React and CodeMirror never fight over
 * the same parent's children), which means wrapping the whole component in
 * a new root div — real surgery on a component nothing else in this port
 * touches, for a cosmetic layer, not a token-correctness one. So in the
 * sketch skin CodeEditor's border/background genuinely vanish (same
 * `--bbox-skin-stroke: transparent` / `-surface: transparent` every other
 * skinned component obeys) with no hand-drawn replacement — the field
 * reads as bare text on the canvas, which is honest for "no box", just
 * not as demonstrative as Block/Badge/Port's drawn ring. Matches
 * packages/bbox-ui/src/codeField.css's own scope exactly (it wires only
 * `--bbox-skin-font-mono`, nothing else) — this port already goes further
 * by wiring border/radius/surface/fg too.
 */

.bbox-code-editor[aria-disabled="true"] {
  opacity: 0.6;
  cursor: default;
}

.bbox-code-editor:focus-within {
  border-color: var(--color-primary);
}

.bbox-code-editor .cm-editor {
  outline: none;
  background: transparent;
  height: auto;
}

.bbox-code-editor .cm-scroller {
  /* Ported from packages/bbox-ui/src/codeField.css:90 (its ONLY skin-token
     line) — a code editor stays monospace by default and the sketch skin
     is the one place that's a real taste call, not a bug: Zach, D3,
     "a code field inherits the skin rather than pinning monospace." */
  font-family: var(--bbox-skin-font-mono, ui-monospace, "SF Mono", Menlo, Consolas, monospace);
  /* Inherits the box's own inline `fontSize` (`fontSizePx`) rather than
     hardcoding a copy — the only way a per-instance size reaches
     CodeMirror's internal DOM. */
  font-size: inherit;
  line-height: 1.4;
}

/*
 * `overflow` (codeEditor.tsx): what a line wider than the box does.
 * `clip` — an <input>-like port label: cut at the edge, no bar. `scroll` —
 * a real horizontal scrollbar once content is wider than the box (the IDE
 * feel of Zach's screenshot). `wrap` — CodeMirror's own `lineWrapping`
 * folds the line, so the scroller only ever needs to grow vertically.
 */
.bbox-code-editor[data-overflow="clip"] .cm-scroller {
  overflow: hidden;
}

.bbox-code-editor[data-overflow="scroll"] .cm-scroller,
.bbox-code-editor[data-overflow="wrap"] .cm-scroller {
  overflow: auto;
}

.bbox-code-editor .cm-content {
  padding: 0;
  caret-color: var(--color-primary);
}

/*
 * No `white-space` set on `.cm-content` above, on purpose — measured live (headless Chrome):
 * CodeMirror's OWN base theme already puts `white-space: pre` on
 * `.cm-content` at the SAME specificity as a plain `.bbox-code-editor
 * .cm-content` rule would be (two classes each), and CodeMirror's
 * stylesheet is injected at `EditorView` construction time, i.e. AFTER this
 * file's import — so it wins the cascade tie regardless of what this rule
 * declared. codeBlock.css's own `white-space: nowrap` here had the exact
 * same dead-on-arrival shape (confirmed: the recovered branch never beat
 * this tie either). It doesn't matter: `pre` already gives "no soft wrap"
 * (CodeMirror still renders one `.cm-line` per line regardless of this
 * property), and unlike `nowrap` it does NOT collapse a run of leading
 * spaces — which Python's indentation needs. Fighting the cascade for
 * `nowrap` here would have made indentation render wrong the moment it won.
 */

/* WHY this rule exists at all: CodeMirror's `lineWrapping` sets
   `white-space: pre-wrap` through its own `.ͼ1 .cm-lineWrapping` rule —
   specificity (0,2,0), the SAME as `.cm-content` alone, so which wins would
   otherwise depend on stylesheet order. Three classes settles it. */
.bbox-code-editor .cm-content.cm-lineWrapping {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.bbox-code-editor .cm-line {
  padding: 0;
}

/* The line-number gutter (`lineNumbers`): a hairline on its right, numbers
   in the faint ink, room for a few digits before the content's own padding.
   WHY it needs a REAL (opaque) background, not `transparent`: CodeMirror
   pins the gutter with its own `position: sticky; left: 0` so it stays put
   while `.cm-content`'s lines scroll underneath it horizontally
   (`data-overflow="scroll"`/`"wrap"` above). A transparent gutter lets that
   scrolled text show through behind the numbers as it passes — matching the
   editor's own surface colour, not the page's, keeps it opaque without
   drawing a visibly different panel. This is the fix codeBlock.css shipped
   and main's codeField.css trim lost along with the gutter entirely. */
.bbox-code-editor .cm-gutters {
  background: var(--color-card);
  color: var(--color-muted-foreground);
  border-right: 1px solid var(--color-border);
  min-width: 36px;
  justify-content: flex-end;
  margin-right: 12px;
}

.bbox-code-editor .cm-lineNumbers .cm-gutterElement {
  padding: 0 8px 0 6px;
}

.bbox-code-editor .cm-focused .cm-activeLine,
.bbox-code-editor .cm-focused .cm-activeLineGutter {
  background: color-mix(in srgb, var(--color-primary) 7%, transparent);
}

.bbox-code-editor .cm-placeholder {
  color: var(--color-muted-foreground);
  font-style: normal;
}

.bbox-code-editor .cm-selectionBackground,
.bbox-code-editor .cm-focused .cm-selectionBackground,
.bbox-code-editor ::selection {
  background: color-mix(in srgb, var(--color-primary) 30%, transparent);
}

.bbox-code-editor .cm-cursor {
  border-left-color: var(--color-primary);
}

/*
 * The syntax palette. `classHighlighter` (@lezer/highlight) emits stable
 * `tok-*` classes with no colour of its own; this is the one place they get
 * one, ported from codeBlock.css's `bbox-code-tokens` block.
 *
 * WHY every selector carries BOTH root classes (0,3,0): CodeMirror's own
 * fallback highlight style, when a host happens to mount it, paints tokens
 * through generated `.ͼN .ͼM` rules at (0,2,0) — a bare
 * `.bbox-code-tokens .tok-keyword` would tie on specificity and lose or win
 * by stylesheet order. Three classes settles it in this sheet's favour.
 *
 * WHY each rule now reads `var(--bbox-tok-*, <today's literal>)`
 * (docs/FEEDBACK-2026-09-17b-PLAN.md A-2, codeEditorTheme.ts): a VS Code
 * syntax theme is a PALETTE SWAP over this exact selector set, not a
 * second highlighter or a per-theme CodeMirror `EditorView.theme()` — see
 * codeEditor.tsx:297's own WHY. `codeEditorThemeVars()` sets the
 * `--bbox-tok-*` custom properties inline on the root; with none set (the
 * default, and any unrecognised theme id) every rule falls straight
 * through to the literal it had before this change, byte-identical.
 */
.bbox-code-editor.bbox-code-tokens .tok-keyword,
.bbox-code-editor.bbox-code-tokens .tok-operatorKeyword,
.bbox-code-editor.bbox-code-tokens .tok-definitionKeyword,
.bbox-code-editor.bbox-code-tokens .tok-moduleKeyword {
  color: var(--bbox-tok-keyword, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 78%, var(--color-foreground)));
  font-weight: 600;
}

/* Split from the group above so a theme's "control keyword" row
   (if/for/return/…) has somewhere to land — see codeEditorTheme.ts's own
   WHY on why `classHighlighter` never actually emits this class today. */
.bbox-code-editor.bbox-code-tokens .tok-controlKeyword {
  color: var(--bbox-tok-control-keyword, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 78%, var(--color-foreground)));
  font-weight: 600;
}

.bbox-code-editor.bbox-code-tokens .tok-string,
.bbox-code-editor.bbox-code-tokens .tok-docString,
.bbox-code-editor.bbox-code-tokens .tok-character,
.bbox-code-editor.bbox-code-tokens .tok-attributeValue {
  color: var(--bbox-tok-string, color-mix(in srgb, var(--bbox-success, #2f9e5a) 62%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-number,
.bbox-code-editor.bbox-code-tokens .tok-integer,
.bbox-code-editor.bbox-code-tokens .tok-float,
.bbox-code-editor.bbox-code-tokens .tok-bool,
.bbox-code-editor.bbox-code-tokens .tok-atom,
.bbox-code-editor.bbox-code-tokens .tok-null,
.bbox-code-editor.bbox-code-tokens .tok-unit {
  color: var(--bbox-tok-number, color-mix(in srgb, var(--bbox-warning, #c98a1b) 58%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-comment,
.bbox-code-editor.bbox-code-tokens .tok-lineComment,
.bbox-code-editor.bbox-code-tokens .tok-blockComment,
.bbox-code-editor.bbox-code-tokens .tok-meta {
  color: var(--bbox-tok-comment, var(--color-muted-foreground));
  font-style: italic;
}

.bbox-code-editor.bbox-code-tokens .tok-typeName,
.bbox-code-editor.bbox-code-tokens .tok-className,
.bbox-code-editor.bbox-code-tokens .tok-namespace {
  color: var(--bbox-tok-type, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 55%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-variableName,
.bbox-code-editor.bbox-code-tokens .tok-variableName2,
.bbox-code-editor.bbox-code-tokens .tok-definition,
.bbox-code-editor.bbox-code-tokens .tok-self {
  color: var(--bbox-tok-variable, var(--bbox-accent, #4f6ee5));
}

.bbox-code-editor.bbox-code-tokens .tok-propertyName,
.bbox-code-editor.bbox-code-tokens .tok-attributeName,
.bbox-code-editor.bbox-code-tokens .tok-labelName {
  color: color-mix(in srgb, var(--bbox-danger, #c94b3f) 42%, var(--color-foreground));
}

/* WHY the fallback reads `var(--bbox-accent, #4f6ee5))` (the tok-variableName
   rule's own default above) and not `var(--color-foreground)`: this
   selector was dead until codeEditorHighlight.ts (its own WHY) started
   actually emitting `tok-function` — nothing ever exercised this rule's
   own literal, so it was never noticed that it disagreed with what a
   function name actually rendered as (`.tok-variableName`'s colour, since
   `.tok-function`/`.tok-definition`/`.tok-variableName` are now emitted
   together on the SAME element — see that file's own WHY on unioning
   classes). Every theme sets `--bbox-tok-function` explicitly, so this
   fallback only matters with no theme selected, and it has to match
   tok-variableName's fallback exactly or turning the class "on" silently
   recolours every function name (and call site) the moment no theme is
   set — a real regression, not a fidelity gain. */
.bbox-code-editor.bbox-code-tokens .tok-function,
.bbox-code-editor.bbox-code-tokens .tok-macroName {
  color: var(--bbox-tok-function, var(--bbox-accent, #4f6ee5));
  font-weight: 600;
}

.bbox-code-editor.bbox-code-tokens .tok-operator,
.bbox-code-editor.bbox-code-tokens .tok-punctuation,
.bbox-code-editor.bbox-code-tokens .tok-separator,
.bbox-code-editor.bbox-code-tokens .tok-bracket {
  color: var(--bbox-tok-operator, var(--color-muted-foreground));
}

.bbox-code-editor.bbox-code-tokens .tok-invalid {
  color: var(--bbox-danger, #c94b3f);
}

/*
 * The diagnostic axis's squiggle (docs/INVALID-STATES-PLAN.md §5's
 * CodeEditor row, §7's stock-parts table). `@codemirror/lint`'s OWN
 * baseTheme already paints `.cm-lintRange-*` with a `background-image`
 * data-URI squiggle baked from a LITERAL hex at import time (`#f11`,
 * `orange`, `#999`) — no CSS variable can reach inside an already-encoded
 * SVG string, so retinting means replacing the whole declaration, not
 * overriding one property. This kit already draws its OTHER resting-text
 * marks (EditableText, LabeledPort) as a plain `text-decoration: underline
 * wavy/dotted` — reusing that recipe here, instead of hand-building a
 * second SVG squiggle, is one fewer visual language for the same mark.
 *
 * WHY three classes (0,3,0): identical tie-break to `.cm-content.
 * cm-lineWrapping` a few rules up in this file — CodeMirror injects its
 * own `.ͼN.cm-lintRange-error` rule at (0,2,0) when the `EditorView`
 * mounts, AFTER this stylesheet loads, so stylesheet order alone would
 * let it win a same-specificity tie. `info` reuses the wavy/dotted split
 * `diagnosticUnderlineStyle` already draws elsewhere in this kit — dotted,
 * not wavy, so a merely-informational range never LOOKS as urgent as an
 * error or warning range beside it.
 */
.bbox-code-editor.bbox-code-tokens .cm-lintRange-error,
.bbox-code-editor.bbox-code-tokens .cm-lintRange-warning,
.bbox-code-editor.bbox-code-tokens .cm-lintRange-info {
  background-image: none;
  text-decoration-line: underline;
  text-decoration-thickness: 1.5px;
  text-underline-offset: 2px;
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-error,
.bbox-code-editor.bbox-code-tokens .cm-lintRange-warning {
  text-decoration-style: wavy;
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-info {
  text-decoration-style: dotted;
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-error {
  text-decoration-color: var(--bbox-danger, #c94b3f);
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-warning {
  text-decoration-color: var(--bbox-warning, #c98a1b);
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-info {
  text-decoration-color: var(--bbox-accent, #4f6ee5);
}

"use client";

// src/components/codeEditor.tsx — ported by value from packages/bbox-ui's
// CodeMirror field, reconciling two lineages that diverged on main:
//
// - packages/bbox-ui/src/codeField.tsx (592 lines, current on main) is the
//   engine this keeps almost verbatim: the write policy (`onWrite` per
//   keystroke via `codeEditorGesture.ts`'s `FieldGesture`), the single-line
//   guard, the Enter/Escape exit contract, the external-value-sync effect,
//   the wheel/pointerdown host-interop effects.
// - packages/bbox-ui/src/codeBlock.tsx (900 lines, deleted on main by
//   368a524 "CodeBlock becomes CodeField", recovered from
//   claude/code-block-primitive) is where `lineNumbers`, the `columns` →
//   pixel width maths (now `codeEditorLayout.ts`), and the `overflow`
//   clip/wrap/scroll modes came from — main's rename trimmed all three
//   along with the `grammar`/`mode`/rows machinery.
//
// Dropped entirely, on both sides: `grammar` (slot decorations +
// completion — `codeGrammar.ts`/`completionMenu.ts`), the rendered/source
// `mode` toggle and `CodeEditorRows` (`codeFieldRows.tsx`/`codeBlockRows`),
// `flatten`/`codeBlockUnits.ts`'s Python-unit folding, and the `look`
// preset ladder (`codeBlock.presets.ts`) — this app has no FieldSpec /
// appearance-cascade machinery to hang any of that on (see CLAUDE.md).
// `language` survives as its own prop (a raw CodeMirror `LanguageSupport`)
// specifically BECAUSE dropping `grammar` wholesale would also have
// dropped syntax highlighting, which the PseudoCode story plainly needs.
//
// `tooltipParent`/the completion popup's `tooltips()` extension are also
// dropped — nothing here ever opens a tooltip without `grammar`'s
// completion source, so parenting one was dead plumbing.

import {
  copyLineDown,
  copyLineUp,
  defaultKeymap,
  history,
  historyKeymap,
  moveLineDown,
  moveLineUp,
} from "@codemirror/commands";
import { syntaxHighlighting, type LanguageSupport } from "@codemirror/language";
import { linter as cmLinter, setDiagnostics as cmSetDiagnostics, type Diagnostic as CMDiagnostic } from "@codemirror/lint";
import {
  Compartment,
  EditorState,
  Prec,
  type Extension,
} from "@codemirror/state";
import {
  EditorView,
  keymap,
  lineNumbers as lineNumbersExtension,
  placeholder as placeholderExtension,
} from "@codemirror/view";
import {
  forwardRef,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  type CSSProperties,
} from "react";

import "./codeEditor.css";

import { FieldGesture } from "./codeEditorGesture";
import { externalSync, singleLineGuard } from "./codeEditorGuards";
import { codeEditorHighlightStyle } from "./codeEditorHighlight";
import { codeEditorWidthPx } from "./codeEditorLayout";
import { codeEditorThemeVars, type CodeEditorTheme } from "./codeEditorTheme";
import type { DiagnosticSeverity } from "./highlighter";

/** The horizontal padding baked into `.bbox-code-editor` in codeEditor.css —
 * kept as a constant here too so `columns`'s pixel maths (codeEditorLayout.ts)
 * matches what actually renders, rather than guessing the stylesheet's number. */
const PADDING_X = 6;

/** What a line wider than the box does. `clip` (the default — an <input>-like
 * port label: cut at the edge, no bar) and `scroll` (a horizontal scrollbar,
 * CodeMirror's own scroller — the IDE feel Zach's screenshot wants) both keep
 * `columns`' fixed width; `wrap` folds the line onto new rows instead and
 * ignores `columns` for width purposes since the text no longer runs past it. */
export type CodeEditorOverflow = "clip" | "wrap" | "scroll";

/**
 * One diagnostic-marked RANGE (docs/INVALID-STATES-PLAN.md §5's CodeEditor
 * row). This is the one mark-bearing shape in this axis that stays
 * POSITIONAL rather than the shared `Diagnostic` list every other
 * component takes: several squiggles at different character offsets in
 * one field are not competing judgements about a single element, so there
 * is nothing to rank down to a `max(severity)` — every range paints its
 * own severity, independently.
 */
export interface CodeEditorDiagnostic {
  from: number;
  to: number;
  severity: DiagnosticSeverity;
  message?: string;
}

export interface CodeEditorProps {
  /** The document. The field follows it whenever nobody is editing. */
  value: string;
  /** Write, per keystroke — the field's one write policy (see `codeEditorGesture.ts`). */
  onWrite(value: string): void;
  /** Open one undo step so an edit is one Ctrl+Z, not one per character. */
  beginEdit?(): void;
  /** The commit boundary — one call per gesture, however the field was left. */
  onEditEnd?(value: string, startValue: string): void;
  /** The syntax parser, e.g. `python()`/`javascript()`/`json()`. Omit for plain text. */
  language?: LanguageSupport;
  /**
   * A VS Code syntax palette (codeEditorTheme.ts) — an id resolved against
   * `CODE_EDITOR_THEMES`, or a `CodeEditorTheme` object directly. Applied
   * as CSS custom properties on the root, UNDER any caller `style` (a
   * caller override still wins). Omit, or pass an id that doesn't match
   * any known theme, for the ambient default palette — never blanks the
   * editor.
   */
  theme?: CodeEditorTheme | string;
  /**
   * A lane/document: several lines, Enter inserts a line, Alt+↑/↓ move one,
   * Shift+Alt+↓ copies one (CodeMirror's default keymap); Ctrl/Cmd+Enter is
   * the exit that Enter is for a single line. `false` (the default): one
   * line — a typed or pasted newline is dropped rather than growing the box.
   */
  multiline?: boolean;
  /** The line-number gutter. Off by default (a bare port-label line has nothing to number). */
  lineNumbers?: boolean;
  /** What a line wider than the box does. Defaults to `"clip"`. */
  overflow?: CodeEditorOverflow;
  /**
   * Characters across. `> 0` fixes the box's width to that many mono cells
   * plus padding (and the gutter when `lineNumbers` is on) — see
   * `codeEditorLayout.ts`'s `codeEditorWidthPx`. `0` (the default) fills
   * whatever the host gives. Ignored when `overflow === "wrap"` — a
   * wrapped line has no fixed width to overflow.
   */
  columns?: number;
  /** The type size, in px — also what `columns`'s pixel maths is computed against. */
  fontSizePx?: number;
  /** Pin every line to this height so lines can sit on a host's own rows. */
  lineHeightPx?: number;
  align?: "left" | "right";
  disabled?: boolean;
  placeholder?: string;
  ariaLabel?: string;
  ariaDescribedBy?: string;
  /** Forced `true` when any `diagnostics` range is `severity: "error"` —
   *  a whole-field error still sets this existing attribute (§5's own
   *  words); an explicit `true` here is never downgraded by an absent
   *  error range. */
  ariaInvalid?: boolean;
  /**
   * The diagnostic axis's positional shape — see `CodeEditorDiagnostic`'s
   * own doc. Painted with the stock `@codemirror/lint` squiggle
   * (`setDiagnostics`/`linter`, §5's own choice), retinted to this kit's
   * three severity tokens in codeEditor.css rather than CodeMirror's
   * hardcoded reds/oranges. No gutter, no Problems panel — §8 stops this
   * kit at the component-scale mark.
   */
  diagnostics?: CodeEditorDiagnostic[];
  className?: string;
  testId?: string;
  style?: CSSProperties;
  /** Take focus on mount; `'select'` also selects the whole line/document. */
  autoFocus?: boolean | "select";
  /** With `autoFocus`, put the caret here instead of selecting everything. */
  cursorAt?: number;
  /** With `autoFocus`, select exactly this range. */
  selectRange?: { from: number; to: number };
  /**
   * Enter (single-line) / Ctrl+Enter (multi) and Escape both end the
   * gesture by leaving the field (the value is never discarded — Ctrl+Z is
   * the retract). A host that owns its own editing session supplies its
   * own exits instead of the default `leave`.
   */
  onEnter?(): void;
  onEscape?(): void;
  /**
   * A host's own key handling, consulted BEFORE every keymap in this file
   * (`Prec.highest`, above even the Enter/Escape exits). Return `true` to
   * claim the key — it is then prevented and stopped; `false` lets it reach
   * CodeMirror untouched. The seam `keyboardReorder.ts`'s move-this-item
   * chord rides: it has to win over the default keymap's Ctrl+←/→ word-jump
   * on a row, and it must lose to nothing it did not ask for.
   */
  onKeyDown?(event: KeyboardEvent, view: EditorView): boolean;
  onViewReady?(view: EditorView): void;
}

export interface CodeEditorHandle {
  setCaret(offset: number): void;
  focus(): void;
}

/**
 * `CodeEditor` — the code text box: one line (the shape `LabeledPort`'s
 * label needs) or a multi-line lane/document (the shape the multiline port
 * editor needs), the same engine wearing different props. A real CodeMirror
 * document, so highlighting, IME, undo and the caret all come from one
 * mature engine rather than a mirror-div.
 *
 * WHY `CodeEditor` and not `CodeField`/`CodeBlock` (Zach, 2026-09-16: "its
 * clear that refers to the component, CodeMirror is the library"): `Code`
 * alone collides with nothing here, `Field`/`Block` each already carry a
 * different meaning elsewhere in bbox-ui (`Block` is the canvas node this
 * app also ships; `CodeBlock` collides with a real Code node on the
 * SystemSketch canvas) — `Editor` says what it is without borrowing either.
 */
export const CodeEditor = forwardRef<CodeEditorHandle, CodeEditorProps>(function CodeEditor({
  value,
  onWrite,
  beginEdit,
  onEditEnd,
  language,
  theme,
  multiline = false,
  lineNumbers = false,
  overflow = "clip",
  columns = 0,
  fontSizePx = 13,
  lineHeightPx,
  align = "left",
  disabled = false,
  placeholder,
  ariaLabel,
  ariaDescribedBy,
  ariaInvalid,
  diagnostics,
  className,
  testId,
  style,
  autoFocus = false,
  cursorAt,
  selectRange,
  onEnter,
  onEscape,
  onKeyDown,
  onViewReady,
}, ref) {
  const wrap = overflow === "wrap";
  const hostRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const languageCompartment = useRef(new Compartment());
  const gutterCompartment = useRef(new Compartment());
  const editableCompartment = useRef(new Compartment());
  const placeholderCompartment = useRef(new Compartment());
  const metricsCompartment = useRef(new Compartment());

  const latest = useRef({
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    onKeyDown,
    value,
    disabled,
    multiline,
  });
  latest.current = {
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    onKeyDown,
    value,
    disabled,
    multiline,
  };

  const metrics = (): Extension => [
    EditorView.theme({
      ...(lineHeightPx
        ? { ".cm-line": { lineHeight: `${lineHeightPx}px`, height: `${lineHeightPx}px` } }
        : {}),
      ...(align === "right" ? { ".cm-content": { textAlign: "right" } } : {}),
    }),
    ...(wrap ? [EditorView.lineWrapping] : []),
  ];

  const gestureRef = useRef<FieldGesture | null>(null);
  if (!gestureRef.current) {
    gestureRef.current = new FieldGesture(
      {
        write: (next) => latest.current.onWrite(next),
        begin: () => latest.current.beginEdit?.(),
        end: (next, start) => latest.current.onEditEnd?.(next, start),
      },
      "live",
    );
  }
  const gesture = gestureRef.current;

  const leave = (view: EditorView) => {
    view.contentDOM.blur();
    gesture.commit();
  };

  useImperativeHandle(ref, () => ({
    setCaret: (offset) => {
      const view = viewRef.current;
      if (!view) return;
      const anchor = Math.max(0, Math.min(offset, view.state.doc.length));
      view.dispatch({ selection: { anchor }, effects: EditorView.scrollIntoView(anchor) });
      view.focus();
    },
    focus: () => viewRef.current?.focus(),
  }), []);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const view = new EditorView({
      state: EditorState.create({
        doc: value,
        extensions: [
          history(),
          Prec.highest(
            EditorView.domEventHandlers({
              keydown: (event, target) => {
                if (event.isComposing || !latest.current.onKeyDown) return false;
                if (!latest.current.onKeyDown(event, target)) return false;
                event.preventDefault();
                event.stopPropagation();
                return true;
              },
            }),
          ),
          // Enter and Escape are the field's exits, handled on the raw
          // event so the keystroke can be STOPPED — see codeField.tsx's own
          // WHY (unchanged here; there is no completion popup any more to
          // give first refusal to, so that branch is simply gone).
          Prec.high(
            EditorView.domEventHandlers({
              keydown: (event, target) => {
                if (event.isComposing) return false;
                if (event.key !== "Enter" && event.key !== "Escape") return false;
                const modifierEnter = event.key === "Enter" && (event.ctrlKey || event.metaKey);
                if (event.key === "Enter" && latest.current.multiline && !modifierEnter) {
                  return false;
                }
                event.preventDefault();
                event.stopPropagation();
                const exit = event.key === "Enter" ? latest.current.onEnter : latest.current.onEscape;
                if (exit) exit();
                else leave(target);
                return true;
              },
            }),
          ),
          singleLineGuard(() => latest.current.multiline),
          keymap.of([
            { key: "Ctrl-ArrowUp", run: moveLineUp },
            { key: "Ctrl-ArrowDown", run: moveLineDown },
            { key: "Ctrl-Shift-ArrowUp", run: copyLineUp },
            { key: "Ctrl-Shift-ArrowDown", run: copyLineDown },
            ...defaultKeymap,
            ...historyKeymap,
          ]),
          languageCompartment.current.of(language ?? []),
          // WHY `codeEditorHighlightStyle` and not the stock `classHighlighter`
          // this used to mount directly: see codeEditorHighlight.ts's own WHY.
          syntaxHighlighting(codeEditorHighlightStyle),
          // WHY `null`, not a no-op `() => []` (measured, not assumed —
          // see this lane's own report for the timeline): `linter()`'s
          // ViewPlugin schedules `source(view)` to run ONCE, UNCONDITIONALLY,
          // `delay`ms (default 750) after every mount/relevant update —
          // it is not "only on a real edit". A `() => []` source WOULD
          // run at that mark and dispatch `setDiagnostics(state, [])`,
          // silently ERASING whatever this file's own sync effect (below)
          // had written — reproduced live: a squiggle painted at t=0
          // vanished at exactly t=750ms in every run. `null` is filtered
          // out of the `sources` facet entirely (lintConfig's own
          // `combine`), so the plugin's scheduled `run()` finds
          // `sources.length === 0` and dispatches NOTHING — this
          // component's diagnostics are pushed in from OUTSIDE (a host/
          // producer), never computed by a live in-editor linter, so
          // there must be no active source at all. The state field and
          // decorations (`lintState`/`lintExtensions`) still mount
          // unconditionally either way, which is all `setDiagnostics`
          // (the sync effect below) needs to have somewhere to write.
          cmLinter(null),
          gutterCompartment.current.of(lineNumbers ? [lineNumbersExtension()] : []),
          editableCompartment.current.of(EditorView.editable.of(!disabled)),
          placeholderCompartment.current.of(placeholder ? placeholderExtension(placeholder) : []),
          metricsCompartment.current.of(metrics()),
          EditorView.inputHandler.of((target, from, to, insertedText) => {
            if (latest.current.multiline || !/[\r\n]/.test(insertedText)) return false;
            const cleaned = insertedText.replace(/[\r\n]+/g, "");
            target.dispatch({
              changes: { from, to, insert: cleaned },
              selection: { anchor: from + cleaned.length },
            });
            return true;
          }),
          EditorView.updateListener.of((update) => {
            if (!update.docChanged) return;
            if (update.transactions.every((tr) => tr.annotation(externalSync))) return;
            const text = update.state.doc.toString();
            gesture.focus(latest.current.value);
            gesture.change(text);
          }),
          EditorView.domEventHandlers({
            focus: () => {
              if (latest.current.disabled) return;
              gesture.focus(latest.current.value);
            },
            blur: () => {
              globalThis.setTimeout(() => {
                const current = viewRef.current;
                if (current && !current.hasFocus) gesture.commit();
              }, 0);
            },
          }),
        ],
      }),
      parent: host,
    });
    viewRef.current = view;
    onViewReady?.(view);
    let frame = 0;
    if (autoFocus) {
      const take = () => {
        if (view.hasFocus || !viewRef.current) return;
        view.focus();
        const length = view.state.doc.length;
        if (selectRange) {
          const anchor = Math.max(0, Math.min(selectRange.from, length));
          const head = Math.max(anchor, Math.min(selectRange.to, length));
          view.dispatch({ selection: { anchor, head } });
        } else if (cursorAt !== undefined) {
          const anchor = Math.max(0, Math.min(cursorAt, length));
          view.dispatch({ selection: { anchor } });
        } else if (autoFocus === "select") {
          view.dispatch({ selection: { anchor: 0, head: view.state.doc.length } });
        }
      };
      take();
      frame = requestAnimationFrame(take);
    }
    return () => {
      cancelAnimationFrame(frame);
      viewRef.current = null;
      view.destroy();
    };
    // One mount for the field's lifetime; content, language, chrome and
    // editability flow through compartments and dispatches so a re-render
    // never tears the document down mid-gesture.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The document follows the store whenever nobody is typing in it.
  useLayoutEffect(() => {
    const view = viewRef.current;
    if (!view || view.state.doc.toString() === value) return;
    if (gesture.isEditing && view.hasFocus) return;
    view.dispatch({
      changes: { from: 0, to: view.state.doc.length, insert: value },
      annotations: externalSync.of(true),
    });
  }, [value, gesture]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({ effects: languageCompartment.current.reconfigure(language ?? []) });
  }, [language]);

  // `setDiagnostics` REPLACES the lint state field wholesale — a plain
  // `Diagnostic[]`, not a compartment reconfigure, because it is data, not
  // an extension. `message` is required by `@codemirror/lint`'s own type
  // (ours is optional, §1's `Diagnostic.message` doc) — falling back to
  // the severity word keeps the squiggle's built-in hover from rendering
  // an empty popup when a producer marks a range before its prose exists.
  useLayoutEffect(() => {
    const view = viewRef.current;
    if (!view) return;
    const mapped: CMDiagnostic[] = (diagnostics ?? []).map((d) => ({
      from: d.from,
      to: d.to,
      severity: d.severity,
      message: d.message ?? d.severity,
    }));
    view.dispatch(cmSetDiagnostics(view.state, mapped));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [diagnostics]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: gutterCompartment.current.reconfigure(lineNumbers ? [lineNumbersExtension()] : []),
    });
  }, [lineNumbers]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: editableCompartment.current.reconfigure(EditorView.editable.of(!disabled)),
    });
  }, [disabled]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({ effects: metricsCompartment.current.reconfigure(metrics()) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lineHeightPx, align, wrap]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: placeholderCompartment.current.reconfigure(
        placeholder ? placeholderExtension(placeholder) : [],
      ),
    });
  }, [placeholder]);

  // See codeField.tsx's own WHY: a canvas host typically swallows the
  // native pointerdown/wheel a plain blur/scroll would rely on.
  useLayoutEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      const host = hostRef.current;
      const view = viewRef.current;
      if (!host || !view || !view.hasFocus) return;
      if (event.target instanceof Node && host.contains(event.target)) return;
      leave(view);
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    return () => document.removeEventListener("pointerdown", handlePointerDown, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const handleWheel = (event: WheelEvent) => {
      if (viewRef.current?.hasFocus) event.stopPropagation();
    };
    host.addEventListener("wheel", handleWheel, { passive: false });
    return () => host.removeEventListener("wheel", handleWheel);
  }, []);

  /**
   * The gesture's third boundary: the host tore the field down while it was
   * still being edited. `codeEditorGesture.ts`'s own doc explains why this
   * cannot be left to `blur` — no `blur` fires for a focused element removed
   * from the DOM, so a commit-on-blur field silently loses the last edit.
   *
   * DEFERRED BY A FRAME, AND CANCELLED IF THE EFFECT COMES BACK — which is a
   * fix for a real, reproducible bug, not defensive noise.
   *
   * React StrictMode (development) mounts every effect, cleans it up, and
   * mounts it again. The element is never removed from the document; only the
   * effects are replayed. A synchronous `gesture.commit()` in that cleanup
   * therefore fires `onEditEnd` a millisecond after the editor appears — and
   * `LabeledPort` uses `onEditEnd` to LEAVE edit mode, so clicking a port's
   * label opened an editor that closed itself on the next tick. Measured in
   * the notebook lab (now /home/bam/marimo-canvas; ported from
   * claude/notebook-lab-work-order-472c22 `23ab20e`): `data-editing` flipped
   * true at t and false at t+2ms, and dropping `<StrictMode>` alone made the
   * feature work. It was invisible because nothing wrapped a `CodeEditor`
   * story in StrictMode, and because "does the editor open" reads identically
   * to "does it stay open" in any assertion that does not wait.
   *
   * Deferring to the next frame distinguishes the two cases without guessing:
   * a StrictMode remount re-runs this effect immediately and cancels the
   * pending commit, while a genuine unmount has nothing to cancel it and the
   * commit lands one frame later — on callbacks held in a ref, so a late call
   * is exactly as valid as the synchronous one was. `gesture` is created once
   * per mount (`gestureRef`), so the only re-run this effect ever sees is the
   * StrictMode replay, never a swap that would cancel a different gesture's
   * commit.
   */
  const pendingCommit = useRef<number | null>(null);
  useLayoutEffect(() => {
    if (pendingCommit.current !== null) {
      cancelAnimationFrame(pendingCommit.current);
      pendingCommit.current = null;
    }
    return () => {
      pendingCommit.current = requestAnimationFrame(() => {
        pendingCommit.current = null;
        gesture.commit();
      });
    };
  }, [gesture]);

  const width = wrap ? undefined : codeEditorWidthPx(columns, fontSizePx, lineNumbers, PADDING_X, PADDING_X);
  // §5's own words: "whole-field error also sets the existing
  // `ariaInvalid`" — an explicit `true` is never downgraded by an absent
  // error range; an explicit `false`/omitted still turns on the instant
  // ANY range in the list is `severity: "error"`.
  const hasErrorDiagnostic = (diagnostics ?? []).some((d) => d.severity === "error");
  const resolvedAriaInvalid = ariaInvalid || hasErrorDiagnostic;

  const boxStyle: CSSProperties = {
    fontSize: fontSizePx,
    ...(width !== undefined ? { width } : {}),
  };

  return (
    <div
      data-slot="code-editor"
      data-multiline={multiline}
      data-line-numbers={lineNumbers}
      data-overflow={overflow}
      data-language={language ? "set" : undefined}
      data-theme={typeof theme === "string" ? theme : theme?.id}
      className={`bbox-code-editor bbox-code-tokens${className ? ` ${className}` : ""}`}
      ref={hostRef}
      role="textbox"
      aria-label={ariaLabel}
      aria-describedby={ariaDescribedBy}
      aria-invalid={resolvedAriaInvalid ? true : undefined}
      aria-disabled={disabled ? true : undefined}
      aria-multiline={multiline ? true : undefined}
      data-testid={testId}
      // Theme vars sit BETWEEN boxStyle and the caller's own `style` — a
      // caller override (including a caller's own --bbox-tok-* variable)
      // still wins over the theme, same as it always won over boxStyle.
      style={{ ...boxStyle, ...codeEditorThemeVars(theme), ...style }}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()}
    />
  );
});

// src/components/codeEditorGesture.ts — ported by value from
// packages/bbox-ui/src/fieldGesture.ts, unchanged apart from doc references
// (CodeField → CodeEditor). Pure state machine, no CodeMirror/React import,
// so it carries over with nothing to strip.

/**
 * The live-commit contract `CodeEditor` follows.
 *
 * WHY a gesture object instead of "call `onWrite` on change, `onEditEnd` on
 * blur": a text field's edit is a *gesture* with three boundaries — it
 * begins, it produces values, and it ends exactly once — and how the field
 * was left (blur, Enter, Escape, the host unmounting the panel) only
 * decides *when* the gesture ends, never *whether* the value survives. The
 * browser will not tell you about the last one: no `blur` fires for a
 * focused element removed from the DOM, so a naive commit-on-blur field
 * silently drops whatever was typed the instant its panel unmounts. This
 * class is driven from the React lifecycle instead (`CodeEditor`'s unmount
 * effect calls `commit()`), where that boundary is observable.
 *
 * Two write policies, both loss-free:
 *
 * - `live` — every keystroke writes straight into the caller's store, so
 *   the store is the only copy of the text and there is nothing left to
 *   lose. `CodeEditor` uses this exclusively.
 * - `exit` — the value is buffered and written once, at the end boundary,
 *   for a write that is genuinely expensive. Still loss-free, because
 *   unmount is itself an end boundary.
 *
 * `begin` fires lazily, on the first keystroke that actually changes the
 * value, so a field that was merely focused leaves no trace in undo
 * history. `end` is the commit boundary a caller can hang a semantic
 * "rename" or a debounced round trip off, without the live write ever
 * having to wait for it.
 */

export type FieldCommitMode = "live" | "exit";

export interface FieldGestureHooks {
  /** Write the value. Per keystroke in `live`, once at the end in `exit`. */
  write(value: string): void;
  /**
   * Open one undoable step. Called lazily — on the first keystroke that
   * really changes the value — so merely focusing a field leaves no trace.
   */
  begin?(): void;
  /** The commit boundary. Fires exactly once per gesture, whatever ended it. */
  end?(value: string, startValue: string): void;
}

export class FieldGesture {
  mode: FieldCommitMode;

  private readonly hooks: FieldGestureHooks;
  private editing = false;
  private began = false;
  private start = "";
  private current = "";

  constructor(hooks: FieldGestureHooks, mode: FieldCommitMode = "live") {
    this.hooks = hooks;
    this.mode = mode;
  }

  get isEditing(): boolean {
    return this.editing;
  }

  get startValue(): string {
    return this.start;
  }

  get value(): string {
    return this.current;
  }

  /** Enter the field. Idempotent: re-entering keeps the original pre-edit value. */
  focus(value: string): void {
    if (this.editing) return;
    this.editing = true;
    this.began = false;
    this.start = value;
    this.current = value;
  }

  /** One keystroke, paste, or IME commit. */
  change(value: string): void {
    if (!this.editing) this.focus(this.current);
    if (value === this.current) return;
    this.current = value;
    if (this.mode !== "live") return;
    this.ensureBegun();
    this.hooks.write(value);
  }

  /**
   * End the gesture and keep the value. Every exit route calls this — blur,
   * Enter, Escape, and the unmount cleanup — so it must stay idempotent.
   */
  commit(): void {
    if (!this.editing) return;
    if (this.mode === "exit" && this.current !== this.start) {
      this.ensureBegun();
      this.hooks.write(this.current);
    }
    const value = this.current;
    const start = this.start;
    this.editing = false;
    this.began = false;
    this.hooks.end?.(value, start);
  }

  private ensureBegun(): void {
    if (this.began) return;
    this.began = true;
    this.hooks.begin?.();
  }
}

// src/components/codeEditorGuards.ts — ported by value from
// packages/bbox-ui/src/codeFieldGuards.ts, unchanged apart from doc
// references (CodeField → CodeEditor). Pure CodeMirror state logic, no
// React, nothing to strip.

import {
  Annotation,
  EditorState,
  Transaction,
  type AnnotationType,
  type Extension,
} from "@codemirror/state";

/**
 * Marks `CodeEditor`'s own imperative doc swaps (the `value`-prop sync) so
 * the change listener never echoes them back as typing. Lives here, not in
 * `codeEditor.tsx`, so `singleLineGuard` below can recognise and re-apply it
 * on a transaction it has to rebuild — annotations are not part of
 * CodeMirror's public `Transaction` surface (only `.annotation(type)` for a
 * type you already know to ask for, never an enumerable list), so the only
 * ones a filter can honestly preserve are ones it knows about by name.
 */
export const externalSync = Annotation.define<boolean>();

/**
 * The named annotations this guard knows how to detect and re-apply on a
 * transaction it has to rebuild: CodeMirror's own `Transaction.time` /
 * `userEvent` / `addToHistory` / `remote`, plus `externalSync` above.
 *
 * WHY this matters beyond bookkeeping: `userEvent` and `addToHistory` are
 * what `history()` groups undo steps by. Losing them made a rebuilt
 * transaction look like an ORDINARY edit with no origin and no history
 * opinion — inside CodeMirror's 500ms `newGroupDelay`, that merged
 * silently into whatever adjacent edit was already open. Type `P`, then
 * paste `a\nb` (copying a lane line with an empty selection is linewise
 * and carries a trailing `\n`, so this is common here): one Ctrl+Z used to
 * discard the typing AND the paste together, leaving `t: ` instead of
 * undoing the paste alone. `time` matters too — it feeds the SAME grouping
 * window, so a rebuilt transaction stamped with a fresh `Date.now()`
 * instead of the original's timestamp can drift outside the window the
 * original edit was actually inside.
 */
function knownAnnotations(tr: Transaction): Annotation<unknown>[] {
  const carried: Annotation<unknown>[] = [];
  function add<T>(type: AnnotationType<T>): void {
    const value = tr.annotation(type);
    if (value !== undefined) carried.push(type.of(value));
  }
  add(Transaction.time);
  add(Transaction.userEvent);
  add(Transaction.addToHistory);
  add(Transaction.remote);
  add(externalSync);
  return carried;
}

/** How many `\r`/`\n` characters sit in `text` before `pos` — the amount a position must shift left to land on the equivalent spot once those characters are removed. */
function newlinesBefore(text: string, pos: number): number {
  let count = 0;
  for (let i = 0; i < pos; i++) {
    const code = text.charCodeAt(i);
    if (code === 10 || code === 13) count++;
  }
  return count;
}

/**
 * A single-line `CodeEditor` must never contain a newline, by ANY path —
 * not just typed or pasted text (`EditorView.inputHandler` catches that
 * one, and stays for the tighter cursor placement it can do on a normal
 * keystroke) but also a COMMAND that inserts one directly, like
 * `defaultKeymap`'s `insertBlankLine` (reachable on Ctrl/Cmd+Enter when a
 * completion popup happens to be open and swallows the field's own exit
 * binding first). A `transactionFilter` sees every transaction regardless
 * of what produced it, so this is the actual guarantee, not a best effort
 * at the input layer.
 *
 * Things earlier passes at this got wrong, all fixed here:
 *
 * - The caret was clamped to the CLEANED text's length instead of shifted
 *   by how many stripped characters sat ahead of it.
 * - The replacement spec silently dropped every annotation and effect —
 *   `externalSync` (an external value-sync misread as typing) and, worse,
 *   CodeMirror's OWN `userEvent`/`addToHistory`/`time` (undo-grouping
 *   corruption — see `knownAnnotations`'s doc). `effects` are forwarded
 *   unconditionally (a plain array on `Transaction`, unlike annotations,
 *   which have no generic enumerable list); `scrollIntoView` likewise.
 * - A transaction that, once cleaned, changes the DOCUMENT not at all
 *   (pasting a bare `"\n"`, or pasting text that survives cleaning back to
 *   exactly what a replaced selection already said) either dispatched a
 *   pointless full document-replace (a dead undo step) or, at the other
 *   extreme, dropped the transaction so completely that a REPLACED
 *   SELECTION was left standing open instead of collapsed to where the
 *   paste actually ended — the very next keystroke would have overwritten
 *   the pasted text a second time. Both are handled by always computing
 *   the corrected selection and only including `changes` when the doc
 *   actually differs.
 */
export function singleLineGuard(isMultiline: () => boolean): Extension {
  return EditorState.transactionFilter.of((tr) => {
    if (isMultiline() || !tr.docChanged) return tr;
    const text = tr.newDoc.toString();
    if (!/[\r\n]/.test(text)) return tr;
    const cleaned = text.replace(/[\r\n]+/g, "");
    const { anchor, head } = tr.newSelection.main;
    const shift = (pos: number) => Math.max(0, Math.min(pos - newlinesBefore(text, pos), cleaned.length));
    const selection = { anchor: shift(anchor), head: shift(head) };
    const preserved = {
      effects: tr.effects,
      annotations: knownAnnotations(tr),
      scrollIntoView: tr.scrollIntoView,
    };
    if (cleaned === tr.startState.doc.toString()) {
      // Nothing textual changes, but the selection still has to land where
      // a real edit would have — a paste that replaced a selection with
      // (once cleaned) the same text it already held must still collapse
      // the selection to the end of the paste, not leave the old range
      // standing open for the next keystroke to clobber.
      return { selection, ...preserved };
    }
    return {
      changes: { from: 0, to: tr.startState.doc.length, insert: cleaned },
      selection,
      ...preserved,
    };
  });
}

// src/components/codeEditorHighlight.ts — the highlighter codeEditor.tsx
// mounts, replacing `syntaxHighlighting(classHighlighter)`.
//
// WHY a hand-written `HighlightStyle` and not `classHighlighter` (the stock
// @lezer/highlight highlighter this replaces): `classHighlighter`'s own
// rule table (node_modules/@lezer/highlight/dist/index.js) has no entry for
// `controlKeyword`, `definitionKeyword`, `moduleKeyword`, `operatorKeyword`,
// or either `function(...)` combination, so @lezer/highlight's own
// specificity fallback (a tag's `.set`, most-specific first) walks past all
// of them to the nearest ancestor tag that DOES have one. Measured on this
// exact tree (@lezer/highlight 1.2.3, @codemirror/lang-python 6.2.1):
//   controlKeyword / definitionKeyword / moduleKeyword / operatorKeyword
//     all collapse to plain `tags.keyword` -> "tok-keyword"
//   a call site, `function(variableName)` (e.g. `range(x)`), collapses to
//     `tok-variableName`; a method call, `function(propertyName)`
//     (e.g. `obj.foo()`), collapses to `tok-propertyName`
//   a Python/JS function DEFINITION is `function(definition(variableName))`
//     — its `.set` chain visits `definition(variableName)` (which DOES
//     have a classHighlighter rule, "tok-variableName tok-definition")
//     BEFORE it ever reaches plain `function(variableName)`, so it collapses
//     there and never reaches a "tok-function" class at all, at any
//     specificity level `classHighlighter` covers.
// In Dark Modern (Zach: "its important that people can set it to what they
// are used to") that means `if`/`return`/`for` render keyword-blue
// (#569cd6) instead of the correct control-purple (#c586c0), and a function
// name renders variable-blue (#9cdcfe) instead of the correct yellow
// (#dcdcaa) — the two most recognisable VS Code colours, both wrong. See
// codeEditorTheme.ts's own WHY on `--bbox-tok-control-keyword`/
// `--bbox-tok-function`, which have carried the right values the whole time
// with nothing ever emitting a class to hang them on.
//
// This file is `classHighlighter`'s own rule list (transcribed verbatim
// below, one rule per line matching its source order) PLUS the missing
// rules, each one UNIONING its class string with whatever `classHighlighter`
// already produced for that exact tag rather than replacing it — never
// "tok-controlKeyword" alone, always "tok-keyword tok-controlKeyword". Two
// reasons, both load-bearing:
//   1. `HighlightStyle`/`tagHighlighter` picks ONE map entry per token — the
//      first match walking that token's tag `.set` from most to least
//      specific — so a rule for the exact composed tag (e.g.
//      `function(definition(variableName))`) must be its own entry with
//      every class the token needs; you cannot "layer" two separate,
//      differently-specific entries and get both.
//   2. codeEditor.css's selectors were written expecting `classHighlighter`-
//      shaped input (a bare token gets exactly one ancestor's class) and
//      groups `tok-keyword`/`tok-operatorKeyword`/`tok-definitionKeyword`/
//      `tok-moduleKeyword` under ONE rule for exactly this reason — keeping
//      the old class present alongside the new one means every rule that
//      already worked keeps working unchanged, with the new, more specific
//      selector (`tok-controlKeyword`, `tok-function`) simply winning the
//      cascade tie by appearing later in that file. Dropping the old class
//      would also fail this file's own H1 unit test, which asserts the new
//      highlighter's class set is a strict superset of `classHighlighter`'s
//      for every token in real Python/JS/JSON source.
import { HighlightStyle } from "@codemirror/language";
import { tags } from "@lezer/highlight";

export const codeEditorHighlightStyle = HighlightStyle.define([
  // --- verbatim from @lezer/highlight's classHighlighter (1.2.3), same order ---
  { tag: tags.link, class: "tok-link" },
  { tag: tags.heading, class: "tok-heading" },
  { tag: tags.emphasis, class: "tok-emphasis" },
  { tag: tags.strong, class: "tok-strong" },
  { tag: tags.keyword, class: "tok-keyword" },
  { tag: tags.atom, class: "tok-atom" },
  { tag: tags.bool, class: "tok-bool" },
  { tag: tags.url, class: "tok-url" },
  { tag: tags.labelName, class: "tok-labelName" },
  { tag: tags.inserted, class: "tok-inserted" },
  { tag: tags.deleted, class: "tok-deleted" },
  { tag: tags.literal, class: "tok-literal" },
  { tag: tags.string, class: "tok-string" },
  { tag: tags.number, class: "tok-number" },
  { tag: [tags.regexp, tags.escape, tags.special(tags.string)], class: "tok-string2" },
  { tag: tags.variableName, class: "tok-variableName" },
  { tag: tags.local(tags.variableName), class: "tok-variableName tok-local" },
  { tag: tags.definition(tags.variableName), class: "tok-variableName tok-definition" },
  { tag: tags.special(tags.variableName), class: "tok-variableName2" },
  { tag: tags.definition(tags.propertyName), class: "tok-propertyName tok-definition" },
  { tag: tags.typeName, class: "tok-typeName" },
  { tag: tags.namespace, class: "tok-namespace" },
  { tag: tags.className, class: "tok-className" },
  { tag: tags.macroName, class: "tok-macroName" },
  { tag: tags.propertyName, class: "tok-propertyName" },
  { tag: tags.operator, class: "tok-operator" },
  { tag: tags.comment, class: "tok-comment" },
  { tag: tags.meta, class: "tok-meta" },
  { tag: tags.invalid, class: "tok-invalid" },
  { tag: tags.punctuation, class: "tok-punctuation" },

  // --- the rules classHighlighter is missing (this file's own WHY above) ---
  // Bare keyword subtags: each already falls under codeEditor.css's shared
  // `.tok-keyword, .tok-operatorKeyword, .tok-definitionKeyword,
  // .tok-moduleKeyword` selector, so keeping "tok-keyword" alongside the
  // specific class changes nothing about which rule matches for these
  // three — only `tok-controlKeyword` has its own separate CSS rule.
  { tag: tags.controlKeyword, class: "tok-keyword tok-controlKeyword" },
  { tag: tags.definitionKeyword, class: "tok-keyword tok-definitionKeyword" },
  { tag: tags.moduleKeyword, class: "tok-keyword tok-moduleKeyword" },
  { tag: tags.operatorKeyword, class: "tok-keyword tok-operatorKeyword" },
  // A function name at a call site (`range(x)`, `obj.foo()`): the bare
  // `function(...)` tag, one level more specific than classHighlighter's
  // own `variableName`/`propertyName` entries above.
  { tag: tags.function(tags.variableName), class: "tok-variableName tok-function" },
  { tag: tags.function(tags.propertyName), class: "tok-propertyName tok-function" },
  // A function/method DEFINITION (`def move(...)`, `function move(...)`):
  // its own most-specific entry, since `function(definition(variableName))`'s
  // `.set` chain reaches `definition(variableName)` (mapped above) before it
  // ever reaches the bare `function(variableName)` rule two lines up — see
  // this file's own WHY, point 1.
  {
    tag: tags.function(tags.definition(tags.variableName)),
    class: "tok-variableName tok-definition tok-function",
  },
  {
    tag: tags.function(tags.definition(tags.propertyName)),
    class: "tok-propertyName tok-definition tok-function",
  },
]);

// src/components/codeEditorLayout.ts — the columns → pixel-width maths,
// recovered from claude/code-block-primitive's packages/bbox-ui/src/
// codeBlock.layout.ts (`CODE_BLOCK_GUTTER_PX`, `CODE_BLOCK_CHAR_RATIO`,
// `codeBlockCharPx`, `codeBlockWidthPx`) after main's 368a524 dropped the
// whole `look`/preset ladder that file also carried. Trimmed to just the
// width maths — no size ladder, no look/overflow enum, no `grow`/
// `grow-truncated` (this app has no FieldSpec/preset machinery to hang
// those on). Pure numbers, no React, no CodeMirror.
//
// DONOR LINES (branch `claude/code-block-primitive`, tip dc30352, read
// 2026-09-17 — the branch is unmerged but present, so `git show
// claude/code-block-primitive:packages/bbox-ui/src/codeBlock.layout.ts`
// resolves these offline):
//   • `:111` `CODE_BLOCK_GUTTER_PX = 36`  -> `CODE_EDITOR_GUTTER_PX`
//   • `:112` `CODE_BLOCK_CHAR_RATIO = 0.61` -> `CODE_EDITOR_CHAR_RATIO`
//   • `:116` `codeBlockCharPx` body        -> `codeEditorCharPx`
//   • `:135` `codeBlockWidthPx` body       -> `codeEditorWidthPx`
// Renames only; the arithmetic is byte-identical. main's 368a524 is the
// commit that dropped the rest of that file.
//
// NO PRIOR ART IS CLAIMED. `0.61` is an EMPIRICAL constant — a measured
// glyph-advance ratio for one specific font stack, not a derived or
// published figure — and the width formula is plain addition. The honest
// caveat that goes with an empirical constant: it is only right for the
// `ui-monospace` stack it was measured on, and a host that swaps the font
// silently gets a wrong width. That is a known limitation, not a bug being
// reported here.

/** The line-number gutter's reserved width, and the mono-cell approximation
 * (glyph advance ≈ 0.61 × font-size for the ui-monospace stack) — both
 * SystemSketch's own measured constants, ported via codeBlock.layout.ts. */
export const CODE_EDITOR_GUTTER_PX = 36;
export const CODE_EDITOR_CHAR_RATIO = 0.61;

/** Width in px of one character cell at `fontPx`. */
export function codeEditorCharPx(fontPx: number): number {
  return Math.max(1, fontPx * CODE_EDITOR_CHAR_RATIO);
}

/**
 * The box width a CodeEditor takes to show `columns` characters — padding,
 * plus the gutter when line numbers are on, plus the cells. `columns` is
 * the AUTHORED fact ("100 ch"), pixels derive from it, never the other way
 * round. Returns `undefined` for `columns <= 0`, the "fill whatever the
 * host gives me" default.
 */
export function codeEditorWidthPx(
  columns: number,
  fontPx: number,
  lineNumbers: boolean,
  paddingLeft: number,
  paddingRight: number,
): number | undefined {
  if (!Number.isFinite(columns) || columns <= 0) return undefined;
  return Math.round(
    paddingLeft +
      paddingRight +
      (lineNumbers ? CODE_EDITOR_GUTTER_PX : 0) +
      Math.round(columns) * codeEditorCharPx(fontPx),
  );
}

// src/components/codeEditorTheme.ts — the palette-swap half of syntax
// theming (docs/FEEDBACK-2026-09-17b-PLAN.md A-2). `codeEditor.tsx` mounts
// `syntaxHighlighting(classHighlighter)` once and never touches it again;
// `classHighlighter` (@lezer/highlight) emits stable, colourless `tok-*`
// classes, and codeEditor.css is the one place those get a colour — under
// selectors that read `var(--bbox-tok-*, <today's literal>)`. A theme is
// therefore nothing but a map of those custom-property names to hex
// strings, applied inline on the editor root: no second highlighter, no
// per-theme `EditorView.theme()`. Pure data + one small resolver, no React
// import needed beyond the `CSSProperties` return type.
//
// WHY a palette swap and not a CodeMirror theme extension: `EditorView.theme()`
// reconfigures CodeMirror's own stylesheet machinery per instance — four
// themes would mean four compartmented extensions, reconciled against
// whatever `classHighlighter` already painted, fighting the same cascade
// this file's sibling CSS already resolved once (codeEditor.css's own WHY
// on selector specificity). A CSS variable is one inline `style` write, no
// CodeMirror reconfiguration, and it composes with a caller's own `style`
// override for free.
import type { CSSProperties } from "react";

export interface CodeEditorTheme {
  /** Stable id — what a `theme` prop or a `<select>`'s `value` carries. */
  id: string;
  /** Human label, e.g. "Dark Modern". */
  label: string;
  appearance: "dark" | "light";
  /** CSS custom properties (`--bbox-tok-*`), applied inline to the editor root. */
  vars: Record<string, string>;
}

/**
 * Published token colours, read straight off each theme's own page at
 * https://code.visualstudio.com/docs/configure/themes (docs/FEEDBACK-2026-09-17b-PLAN.md
 * A-2's table). `controlKeyword` and `function` are carried even though
 * `classHighlighter` never actually emits `tok-controlKeyword`/`tok-function`
 * for any language this app ships (see CodeEditor.stories.tsx's `SyntaxThemes`
 * story doc comment) — keyword and control-keyword both collapse to
 * `tok-keyword`, and a function name collapses to `tok-variableName` (a def)
 * or `tok-propertyName` (a call), because @lezer/highlight's own
 * `classHighlighter` rule table has no entry for either subtag and falls
 * back to the nearest ancestor tag that does. Shipping the variable anyway
 * costs nothing and themes it correctly the day that changes.
 */
