/* ------------------------------------------------------------------ */
/* The vocabulary — §1                                                 */
/* ------------------------------------------------------------------ */

/** The closed set. Three members, like the skin table's fixed 13 tokens
 *  (skin.ts:89) — an open-ended set of marks degenerates into a pile of
 *  per-callsite overrides. */
export type DiagnosticSeverity = "error" | "warning" | "info";

export const DIAGNOSTIC_SEVERITIES: DiagnosticSeverity[] = ["error", "warning", "info"];

export interface Diagnostic {
  /**
   * Stable, producer-owned. Appendix B records the cost of not having one:
   * maxGraph's `setCellWarning(cell, null)` deletes EVERY overlay on the
   * cell, and per-item identity is what prevents that. It is also what
   * lets a host diff the list per item instead of rebuilding it (JointJS's
   * `list` highlighter skips `createListItem` for unchanged entries).
   */
  id: string;
  severity: DiagnosticSeverity;
  /** One-line human explanation — the FR's "text explanation for what the
   *  issue is". Optional: a mark can render before its prose exists. */
  message?: string;
  /** Rule id — VS Code's `Ruff(F407)` slot. */
  code?: string;
}

const SEVERITY_RANK: Record<DiagnosticSeverity, number> = { error: 0, warning: 1, info: 2 };

/**
 * One mark, N messages: every mark-bearing component's CHROME (the halo,
 * the glow, the underline, the backdrop) is painted once at the worst
 * severity present — never a fifth `state`, never a per-finding stack of
 * paint layers. `undefined` for an absent or empty list, never persisted —
 * the same contract as `received` (appearance.ts) and `dimmed`/`hinting`
 * (host-computed, re-derived every render).
 */
export function maxDiagnosticSeverity(diagnostics?: readonly Diagnostic[]): DiagnosticSeverity | undefined {
  if (!diagnostics || diagnostics.length === 0) return undefined;
  return diagnostics.reduce<DiagnosticSeverity>(
    (worst, d) => (SEVERITY_RANK[d.severity] < SEVERITY_RANK[worst] ? d.severity : worst),
    diagnostics[0].severity,
  );
}

/* ------------------------------------------------------------------ */
/* Tokens — §2. Ported, not invented: packages/bbox-ui/src/theme.css:28-31 */
/* / :79-89 — see src/globals.css's own port of these three.            */
/* ------------------------------------------------------------------ */

/**
 * severity -> CSS colour. `error` alone carries a fallback (`--destructive`
 * — every shadcn theme defines it), per §2's own table; `warning`/`info`
 * need none because this kit always ports the two tokens that back them
 * (src/globals.css).
 */
export function diagnosticColorVar(severity: DiagnosticSeverity): string {
  switch (severity) {
    case "error":
      return "var(--bbox-danger, var(--destructive))";
    case "warning":
      return "var(--bbox-warning)";
    case "info":
      return "var(--bbox-accent)";
  }
}

/* ------------------------------------------------------------------ */
/* HighlighterKind — Appendix A's JointJS table, Zach's mid-run ask:     */
/* "borrow their terminology... they have both the stroke and also the  */
/* mask... we can support both!"                                        */
/* ------------------------------------------------------------------ */

/**
 * How a highlighter draws itself, per JointJS's own vocabulary
 * (docs/INVALID-STATES-PLAN.md Appendix A's table — `dia.HighlighterView`'s
 * five types, of which this kit implements the three that apply to marking
 * an already-drawn element rather than restyling its own fill/class):
 *
 * - `"stroke"` — a crisp outline traced at a fixed offset from the
 *   element's own silhouette. JointJS's own docs call this "the same
 *   outline, cheaper and less precise" than `mask`: on a shape with
 *   corners, an offset outline drawn at the ORIGINAL corner radius is not
 *   truly equidistant at the corners (the offset silhouette should grow
 *   its OWN radius by the offset amount, and a cheap implementation
 *   usually does not bother). The DEFAULT kind — Zach, reacting to the
 *   report's drop-shadow halo: "I do wonder if visual language wise if we
 *   should just borrow from jointjs and do the highlighting.. perhaps
 *   that's clearer than the shadow drop..?" — a question, not a ruling,
 *   which is why `halo` below is kept, not deleted.
 * - `"mask"` — the equidistant version: JointJS reaches for real SVG
 *   masking to get a genuinely parallel outline around an arbitrary
 *   silhouette, at a real performance cost, which is exactly why they
 *   document it as the pricier alternative to `stroke`. Appendix B's own
 *   finding is the load-bearing citation for how this kit implements it:
 *   "`mask` with `deep: true` falls back to `getBoundingClientRect()` when
 *   the target is HTML inside a `foreignObject`" — every component this
 *   axis marks is plain HTML, not an SVG silhouette, so this kit's `mask`
 *   is ALWAYS a bounding-rect technique, never a pixel-traced one, matching
 *   JointJS's own documented HTML fallback rather than overbuilding a
 *   silhouette tracer nothing here needs. Concretely: for a rounded
 *   rectangle (`Block`), the equidistant offset of a rounded rect by `d` is
 *   exactly a rounded rect with the SAME straight edges offset by `d` and
 *   the corner radius increased by `d` (the Minkowski sum of a rounded
 *   rectangle and a disc) — `highlighterMaskFrameStyle` below is that
 *   arithmetic, not a literal `<mask>` element, because the bounding-rect
 *   case never needs one. For a shape with no corners at all (`Port`'s
 *   circle), the equidistant offset of a circle is trivially a larger
 *   circle — `stroke` and `mask` are the IDENTICAL geometry there, and
 *   `Port` says so rather than drawing two indistinguishable rings.
 * - `"halo"` — this kit's own pre-existing treatment (a soft box-shadow
 *   ring on `Port`, a glow prepended to `Block`'s shadow list, a
 *   translucent backdrop under `Trace`): what the proposal report showed
 *   Zach before this feedback. Not JointJS vocabulary — kept as the third
 *   sibling because he questioned it, he did not reject it.
 */
export type HighlighterKind = "stroke" | "mask" | "halo";

export const HIGHLIGHTER_KINDS: HighlighterKind[] = ["stroke", "mask", "halo"];

/** Zach's own lean, from the report feedback (see `HighlighterKind`'s own
 *  doc) — every mark-bearing component defaults here unless a story is
 *  deliberately demonstrating a different kind. */
export const DEFAULT_HIGHLIGHTER_KIND: HighlighterKind = "stroke";

/**
 * The `stroke` kind for a DOM rectangle (`Block`): a plain CSS `outline`,
 * offset outward from the border box. Cheap and browser-native — modern
 * Chromium/Firefox already clip an `outline`'s corners to follow the
 * element's OWN `border-radius`, but at the SAME radius the box itself
 * has, which is exactly JointJS's "less precise" than `mask`: the outline
 * stops being truly equidistant the moment the box has any radius at all.
 * `offsetPx` is the gap between the box's own border and the drawn line.
 */
export function highlighterStrokeOutlineStyle(color: string, offsetPx: number, widthPx = 2): CSSProperties {
  return {
    outline: `${widthPx}px solid ${color}`,
    outlineOffset: offsetPx,
  };
}

/**
 * The `mask` kind for a DOM rectangle — see `HighlighterKind`'s own doc
 * for the Minkowski-sum reasoning. A sibling frame, sized `offsetPx`
 * larger on every side (`inset: -offsetPx`) so it never affects the
 * marked element's own layout box, with `radiusCss` (the SAME
 * `var(--bbox-skin-radius, ...)` chain the element's own corner reads)
 * grown by exactly `offsetPx` — `outline-offset` cannot do this (it
 * cannot touch `border-radius`), which is the whole reason this needs a
 * second element rather than one CSS property on the original.
 */
export function highlighterMaskFrameStyle(color: string, offsetPx: number, radiusCss: string, widthPx = 2): CSSProperties {
  return {
    position: "absolute",
    inset: -offsetPx,
    borderRadius: `calc(${radiusCss} + ${offsetPx}px)`,
    border: `${widthPx}px solid ${color}`,
    pointerEvents: "none",
  };
}

/* ------------------------------------------------------------------ */
/* The underline helper — §5's EditableText/LabeledPort/ValueCapsule row */
/* ------------------------------------------------------------------ */

/**
 * The one shared recipe behind "wavy underline, resting text" (§7's stock-
 * parts table: plain CSS `text-decoration`, no library). `error`/`warning`
 * wear a wavy line; `info` a dotted one — the same split §5 draws between a
 * halo and nothing, restated in the underline's own vocabulary.
 */
export function diagnosticUnderlineStyle(severity: DiagnosticSeverity): CSSProperties {
  return {
    textDecorationLine: "underline",
    textDecorationStyle: severity === "info" ? "dotted" : "wavy",
    textDecorationColor: diagnosticColorVar(severity),
    // Thickened slightly so the mark reads as deliberate at body-text sizes
    // rather than as a stray browser-default decoration.
    textDecorationThickness: "1.5px",
    textUnderlineOffset: "2px",
  };
}

/* ------------------------------------------------------------------ */
/* DiagnosticTooltip — the hover half of §5's interaction contract:    */
/* "hover any marked text/dot -> Tooltip with message + code (no       */
/* actions)". A thin wrapper, not a new visual: absent/empty           */
/* `diagnostics` renders `children` completely untouched, so a mark-   */
/* bearing component pays zero DOM cost at rest (same contract as      */
/* `Port`'s own `showHitRegion`/`hinting` — geometry identical on or   */
/* off).                                                                */
/* ------------------------------------------------------------------ */

export interface DiagnosticTooltipProps {
  diagnostics?: readonly Diagnostic[];
  /** The marked element itself — becomes the Tooltip's trigger via Base
   *  UI's `render` merge (the same pattern `Tooltip.stories.tsx`'s
   *  `OnIconButton` story already uses for a real button). */
  children: ReactElement;
}

export function DiagnosticTooltip({ diagnostics, children }: DiagnosticTooltipProps): ReactElement {
  if (!diagnostics || diagnostics.length === 0) return children;
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger render={children} />
        <TooltipContent side="top">
          <div data-slot="diagnostic-tooltip-body" className="flex flex-col gap-1">
            {diagnostics.map((d) => (
              <div key={d.id} className="flex items-center gap-1.5">
                {d.code ? <span className="opacity-70">{d.code}</span> : null}
                <span>{d.message ?? d.severity}</span>
              </div>
            ))}
          </div>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

/* ------------------------------------------------------------------ */
/* DiagnosticFlag — §4's one genuinely-new interactive composition:    */
/* the anchored corner chip, wired as a Popover trigger. Message/code/ */
/* actions/footer is the click half of §5's contract; the hover half   */
/* lives on whatever it is attached to, via `DiagnosticTooltip` above. */
/* ------------------------------------------------------------------ */

const SEVERITY_ICON: Record<DiagnosticSeverity, LucideIcon> = {
  error: OctagonX,
  warning: TriangleAlert,
  info: Info,
};

/** The chip's own diameter, px — small enough to straddle a Block's corner
 *  or ride a LabeledPort's secondary slot without dominating either. */
export const DIAGNOSTIC_FLAG_SIZE_PX = 18;

export interface DiagnosticFlagProps {
  /** Non-empty — a caller renders no flag at all when the list is empty;
   *  "nothing" is the mark-bearing component's own job (§5's own table),
   *  not this component's. */
  diagnostics: Diagnostic[];
  /** The host's own follow-up controls, inside the popover body — VS
   *  Code's action button. Absent renders none, same present-beats-absent
   *  contract `LabeledPort`'s slots use. */
  actions?: ReactNode;
  /** Footer links — VS Code's View Problem / Quick Fix row. */
  footer?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

// WHY lucide-react is imported DIRECTLY here rather than through
// `./glyph`'s resolver-context pattern (§7's stock-parts table names "via
// Glyph"): `glyph.tsx` imports `@bbox-ui/glyph-content`, `private: true`
// and unpublished — the same blocker class CLAUDE.md already names for the
// two canvas adapters, and the exact reason `glyph.tsx` itself is
// deliberately NOT a registry item. `DiagnosticFlag` IS meant to ship as a
// registry item (this axis's one new interactive component), and this
// kit's registry items never take a `registryDependency` on each other —
// so it cannot depend on a component that cannot itself be installed.
// `dropdown-menu.tsx` already sets the precedent of importing lucide-react
// icons straight from the package for exactly this reason.
export function DiagnosticFlag({ diagnostics, actions, footer, className, style }: DiagnosticFlagProps) {
  const severity = maxDiagnosticSeverity(diagnostics) ?? "info";
  const Icon = SEVERITY_ICON[severity];
  const color = diagnosticColorVar(severity);
  const count = diagnostics.length;

  return (
    <Popover>
      <PopoverTrigger
        render={
          <button
            type="button"
            data-slot="diagnostic-flag"
            data-severity={severity}
            data-count={count > 1 ? count : undefined}
            aria-label={`${count} ${severity} diagnostic${count === 1 ? "" : "s"}`}
            className={cn(
              "relative inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full border-2",
              className,
            )}
            style={{
              width: DIAGNOSTIC_FLAG_SIZE_PX,
              height: DIAGNOSTIC_FLAG_SIZE_PX,
              background: "var(--card)",
              borderColor: color,
              color,
              ...style,
            }}
          >
            <Icon aria-hidden style={{ width: "70%", height: "70%" }} />
            {/* The badge's own COUNT (Appendix B item 3 / convergence
                table: Vyuh's status badges, maxGraph's
                `containsValidationErrors`) — the one piece of chrome a
                scalar `diagnostic` could never have rendered, and the
                deciding reason §1 was amended to a list. One finding = no
                count, same read as today's single-mark design. */}
            {count > 1 && (
              <span
                data-slot="diagnostic-flag-count"
                aria-hidden
                className="absolute -bottom-1 -right-1 inline-flex min-w-[14px] items-center justify-center rounded-full px-[3px] text-[9px] leading-[14px] font-semibold text-white"
                style={{ background: color }}
              >
                {count}
              </span>
            )}
          </button>
        }
      />
      {/* Click: the full anatomy — message · code chip · host actions ·
          host footer, one block per diagnostic (VS Code's own hover, which
          is Zach's reference screenshot). */}
      <PopoverContent data-slot="diagnostic-flag-content">
        <div className="flex flex-col gap-2">
          {diagnostics.map((d) => (
            <div key={d.id} className="flex items-center gap-1.5">
              <span style={{ color: diagnosticColorVar(d.severity) }}>{d.message ?? d.severity}</span>
              {d.code ? (
                <Badge variant="outline" size="sm">
                  {d.code}
                </Badge>
              ) : null}
            </div>
          ))}
        </div>
        {actions ? (
          <div data-slot="diagnostic-flag-actions" className="mt-2 flex gap-2">
            {actions}
          </div>
        ) : null}
        {footer ? (
          <div data-slot="diagnostic-flag-footer" className="mt-2 flex gap-3 text-xs text-muted-foreground">
            {footer}
          </div>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}

/* src/components/keyboardReorder.css — when the move-this-item chord's hint
 * (keyboardReorder.ts) shows: only while a SINGLE-line editor inside that
 * item holds focus.
 *
 * WHY CSS `:has(:focus)` and not React state from focus/blur events: the
 * editor closing is an UNMOUNT (Enter swaps it back to resting text), and
 * Chrome fires no blur for a focused element removed from the DOM — so a
 * state flag set on focus was measured staying lit after the editor was
 * gone. `:focus` is recomputed by the browser itself and cannot go stale.
 */

[data-slot="port-edge-reorder-hint"],
[data-slot="block-member-reorder-hint"] {
  display: none;
}

[data-slot="port-edge-member"]:has([data-slot="code-editor"][data-multiline="false"] .cm-content:focus)
  > [data-slot="port-edge-reorder-hint"] {
  display: block;
}

/* The `:not(...)` keeps a member of a NESTED stack from lighting its outer
 * member's hint too — only the innermost member being edited shows one,
 * matching the keydown handler, which answers only to its own slot. */
[data-slot="block-member"]:has(
    :is(input[data-slot="editable-text-input"], [data-slot="code-editor"][data-multiline="false"] .cm-content):focus
  ):not(
    :has(
      [data-slot="block-member"]
        :is(input[data-slot="editable-text-input"], [data-slot="code-editor"][data-multiline="false"] .cm-content):focus
    )
  )
  > [data-slot="block-member-reorder-hint"] {
  display: block;
}

// src/components/keyboardReorder.ts — the IDE "move line" hotkey, applied
// to the thing a single-line editor is editing rather than to a line of
// text: while a port's label (`portEdge.tsx`) or a stacked member's title
// (`blockMembers.tsx`) is being edited, one chord moves THAT item one slot
// along its container. Pure key matching plus the focus hand-back; the
// reorder itself stays each container's own drag operation, so a keyboard
// move and a pointer drag produce the same list (see the two call sites).
//
// Zach, 2026-09-21: "Support for IDE hotkeys to reorder in single line edit
// mode on port edge and on member stack ... ctrl up or down (for a column)
// or (ctrl left right) for a row" and "If you are editing their title and
// you do the ide hot keys then it should change its order in that stack."
//
// Ours, ad hoc — no algorithm to cite; the chord vocabulary is the one VS
// Code and CodeMirror already ship (`moveLineUp`/`moveLineDown` on
// Alt+↑/↓, `@codemirror/commands`' `defaultKeymap`).
import { EditorView } from "@codemirror/view";

/**
 * Which modifier drives the move. `"ctrl"` is Zach's literal spec; `"alt"`
 * is the VS Code / CodeMirror move-line convention, which leaves Ctrl+arrows
 * as word-jump everywhere. A taste call, so both ship and the stories carry
 * a live switch between them.
 */
export type ReorderChord = "ctrl" | "alt";

export type ReorderAxis = "row" | "column";

type ChordEvent = Pick<KeyboardEvent, "key" | "ctrlKey" | "altKey" | "shiftKey" | "metaKey">;

/**
 * -1 (toward the start), +1 (toward the end), or `null` when the key is not
 * this axis's reorder chord and must fall through to the editor untouched.
 *
 * WHY only the axis-matched pair: Ctrl+←/→ is word-jump in every text
 * editor, so taking it only where it IS the reorder axis (a row) keeps it
 * working everywhere else — on a column, Ctrl+←/→ still moves the caret by
 * a word, and on a row Ctrl+↑/↓ still reaches the editor.
 *
 * Exact modifiers, no extras: Shift is selection-extend and Meta is the Mac
 * line/document jump, so a chord carrying either is somebody else's key.
 */
export function reorderDeltaForKey(event: ChordEvent, axis: ReorderAxis, chord: ReorderChord): -1 | 1 | null {
  if (event.shiftKey || event.metaKey) return null;
  const chordHeld = chord === "ctrl" ? event.ctrlKey && !event.altKey : event.altKey && !event.ctrlKey;
  if (!chordHeld) return null;
  const [back, forward] = axis === "column" ? ["ArrowUp", "ArrowDown"] : ["ArrowLeft", "ArrowRight"];
  if (event.key === back) return -1;
  if (event.key === forward) return 1;
  return null;
}

/** The discoverability hint an open editor shows, e.g. `Ctrl ↑↓ reorder`. */
export function reorderHintText(axis: ReorderAxis, chord: ReorderChord): string {
  return `${chord === "ctrl" ? "Ctrl" : "Alt"} ${axis === "column" ? "↑↓" : "←→"} reorder`;
}

/**
 * Whether `target` is a SINGLE-line text editor the chord may act from — a
 * `CodeEditor` in one-line mode or an `EditableText` single-line `<input>`.
 * A multi-line editor owns Alt/Ctrl+↑/↓ itself (CodeMirror's move-line), so
 * it is never a reorder source.
 */
export function isSingleLineTextEditor(target: Element): boolean {
  if (target instanceof HTMLInputElement) return target.closest('[data-slot="editable-text-input"]') === target;
  return target.closest('[data-slot="code-editor"]')?.getAttribute("data-multiline") === "false";
}

/**
 * Snapshot the focused editor's caret now, and return a function that puts
 * focus and caret back after the container re-renders in its new order.
 *
 * WHY this exists — a GUARD, and honest about it: React reorders keyed
 * siblings by moving DOM nodes (`insertBefore`), and the DOM spec's removal
 * steps drop focus from a moved node. MEASURED 2026-09-22 in Chromium
 * (vitest-playwright, both "Keyboard reorder" stories): focus and caret
 * survived every move WITHOUT this — a mutation replacing it with a no-op
 * stayed green. It is kept because an engine that does follow the removal
 * steps would silently strand the caret on `<body>` with the editor still
 * mounted, and the restore no-ops whenever focus survived. For a CodeMirror
 * view the selection is re-dispatched from the snapshot, not the DOM.
 */
export function captureEditingFocus(target: EventTarget | null): () => void {
  if (!(target instanceof HTMLElement)) return () => {};
  const view = EditorView.findFromDOM(target);
  if (view) {
    const selection = view.state.selection;
    return () => {
      if (!view.dom.isConnected) return;
      if (!view.hasFocus) view.focus();
      if (!view.state.selection.eq(selection)) view.dispatch({ selection });
    };
  }
  if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
    const { selectionStart, selectionEnd, selectionDirection } = target;
    return () => {
      if (!target.isConnected || target.ownerDocument.activeElement === target) return;
      target.focus({ preventScroll: true });
      if (selectionStart !== null && selectionEnd !== null) target.setSelectionRange(selectionStart, selectionEnd, selectionDirection ?? undefined);
    };
  }
  return () => {
    if (target.isConnected && target.ownerDocument.activeElement !== target) target.focus({ preventScroll: true });
  };
}

"use client";

// src/components/labeledPort.tsx — ported by value from
// packages/bbox-ui/src/port.tsx's `LabeledPort` (docs/PORT-EDGE-PLAN.md
// Phase 2): the composite of `Port` (./port.tsx) plus its two independently
// positioned slots, both absolutely positioned off the dot's own box (see
// this file's B4 note below).
//
// What ported OVER verbatim (pure geometry, no schema): the `??`-fallback
// chain (`labelOrigin ?? TEXT_LAYOUT_AS_PLACEMENT[textLayout].origin`) — in
// plain props this chain alone IS the preset behaviour, no schema layer
// needed underneath it — and `slotPlacementStyle` itself (./port.layout.ts),
// now driving BOTH slots (originally just the secondary one; see B4 below).
//
// What's LEFT BEHIND (docs/PORT-EDGE-PLAN.md's own list — none of it is
// geometry): the `size` cascade rung (D4), `tone`/`lens`/`reveal`/
// `producers` (D3 — no `PortCountBadge` fallback; an unset secondary slot
// renders nothing), and `anchored` (wall geometry for a real Block — a
// Storybook specimen is exactly the standalone flex pairing this file keeps).
//
// What's REBUILT (D1, superseded 2026-09-16, superseded AGAIN 2026-09-17
// (docs/FEEDBACK-2026-09-17c-PLAN.md F-1)): the label slot's built-in fill
// went CodeField -> plain-text-via-`EditableText` -> plain-text-at-rest,
// `CodeEditor` while editing. Zach's own diagnosis of the 2026-09-16 build:
// "I also think in multi line edit mode, for simplicity we should be using
// labeled ports that use the CodeEditor single line. Right now you may be
// having difficulties because you are using EditableText in the label
// slot." `DefaultPortLabel` below now conditionally renders ONE of a plain
// `<span>` (rest) or a single-line `CodeEditor` (editing) at the SAME
// position — never both at once, so entering edit mode REPLACES the display
// text rather than painting an editor over it (F-1 item 2), and the type
// size cannot drift between the two the way it could across two unrelated
// components: both branches read `fontSizePx` off the exact same
// `PORT_TEXT_SIZES[textSize]` number (F-1's own acceptance test — resting
// `getComputedStyle().fontSize` vs the editor's — passes BY CONSTRUCTION,
// not by two components happening to agree). The SLOT BOUNDARY (`labelSlot`,
// present-beats-absent) is unchanged — a host that wants something else
// entirely still swaps the fill with zero changes to the placement math
// below (`LabeledPort.stories.tsx`'s own `CodeLabel` story already does
// this).

import type { LanguageSupport } from "@codemirror/language";
import type { EditorView } from "@codemirror/view";
import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { useEffect, useRef, useState } from "react";

import { cn } from "../lib/utils";
import { CodeEditor } from "./codeEditor";
import {
  DiagnosticTooltip,
  diagnosticUnderlineStyle,
  maxDiagnosticSeverity,
  type Diagnostic,
  type HighlighterKind,
} from "./highlighter";
import { HIT_REGION_FILL, HIT_REGION_OUTLINE } from "./hitRegion";
import { Port, type PortState } from "./port";
// The visual-variant registry (lane `ports`, 2026-09-19): the default dot
// diameter and text rung when a caller sets neither, the ring overhang the
// label clears, and the type→colour palette for the by-type variants.
import { PORT_VARIANT_ATTR, portVariantLabelFont, portVariantVars, usePortVariant, type PortVariantId } from "../skin/portVariants";
import {
  PORT_DIAMETERS,
  PORT_LABEL_GAP,
  PORT_SECONDARY_SLOT_GAP_PX,
  PORT_TEXT_SIZES,
  slotPlacementStyle,
  SECONDARY_LAYOUT_AS_ORIGIN,
  TEXT_LAYOUT_AS_PLACEMENT,
  defaultSecondarySlotLayout,
  inwardTextLayout,
  type BlockSide,
  type PortDirection,
  type PortSize,
  type PortTextLayout,
  type PortTextSize,
  type SecondarySlotLayout,
  type SlotOrigin,
  type SlotAlign,
  type SlotPlacement,
} from "./port.layout";

/* ------------------------------------------------------------------ */
/* DefaultPortLabel — LabeledPort's built-in label fill (D1, 2026-09-16: */
/* plain text via EditableText, not CodeField). A host that wants a     */
/* different editor passes `labelSlot` instead — see LabeledPortProps.   */
/* ------------------------------------------------------------------ */

/** Below this, the editor grows no narrower — a 1-2 char value still reads
 *  as a text field, not a single blinking-caret sliver. */
const MIN_LABEL_COLUMNS = 3;

/**
 * Click-to-edit. Two MUTUALLY EXCLUSIVE branches, never both mounted: at
 * rest a plain `<span>` (`port-label-display`), while editing a single-line
 * `CodeEditor` — swapping the element TYPE at the same tree position, so
 * React unmounts one and mounts the other rather than layering one over the
 * other (F-1 item 1/2: "the actual ports should basically look identical
 * ... when you are in multi line edit mode, the display text shouldn't show
 * any more"). Local `value` mirrors `children` whenever not mid-edit (so an
 * unwired label simply reflects whatever the host passes), and
 * `onLabelWrite` fires live on every keystroke — the same "fired on every
 * keystroke" contract the donor's `CodeField`-backed `PortLabel` documented.
 * Escape reverts to the value captured at the moment editing started.
 */
function DefaultPortLabel({
  children = "",
  direction = "input",
  textSize = "xs",
  type,
  fontFamily = "var(--bbox-skin-font-sans, inherit)",
  disabled = false,
  onLabelWrite,
  onLabelKeyDown,
  placeholder,
  language,
  showHitRegion = false,
  diagnostics,
  className,
  style,
}: {
  children?: string;
  direction?: PortDirection;
  textSize?: PortTextSize;
  /** The secondary run — the port's type — drawn after the name at the
   *  variant's `type.size`/`opacity` (portVariants.css). Rest only: the
   *  editor edits the NAME, and a type beside a caret reads as editable. */
  type?: string;
  /** The label face — the variant's (`portVariantLabelFont`); defaults to
   *  the skin's sans token, this label's behaviour before variants. */
  fontFamily?: string;
  disabled?: boolean;
  onLabelWrite?(value: string): void;
  onLabelKeyDown?(event: KeyboardEvent, view: EditorView): boolean;
  placeholder?: string;
  language?: LanguageSupport;
  /** Paint this label's click-to-edit target (its own box). Paints
   * nothing while `disabled` — a disabled label has no click handler, so
   * there is no region to show; painting one would be a lie. */
  showHitRegion?: boolean;
  /** §5's LabeledPort row: "wavy underline under the label text" — applied
   *  to the REST span only (`port-label-display` below). The editing
   *  branch swaps in a `CodeEditor`, which carries its own positional
   *  `diagnostics` shape (ranges, not a per-element list) — out of scope
   *  here, same boundary §5's own table draws. */
  diagnostics?: Diagnostic[];
  className?: string;
  style?: CSSProperties;
}) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(children);
  const snapshotRef = useRef(children);

  // Mirrors the host's `children` whenever this field isn't mid-edit — the
  // same "reverts to children" contract the donor's unwired PortLabel had.
  useEffect(() => {
    if (!editing) setValue(children);
  }, [children, editing]);

  // F-1's own acceptance test: `getComputedStyle().fontSize` on the resting
  // label and on the editor's own text must be EQUAL. Both branches below
  // read this SAME number — there is no second ladder to drift out of sync
  // with (the bug Zach saw was two DIFFERENT components each picking their
  // own size; one component reading one variable can't repeat that).
  const fontSizePx = PORT_TEXT_SIZES[textSize];
  // Text hugs the dot on the side the label actually flows toward — same
  // intent `direction` carried on the donor's CodeField.
  const align = direction === "output" ? "right" : "left";
  const exitEditing = () => setEditing(false);

  if (editing && !disabled) {
    return (
      <span data-slot="port-label" data-direction={direction} data-editing="true" className={cn("flex min-w-0 items-center", className)} style={style}>
        <CodeEditor
          value={value}
          onWrite={(next) => {
            setValue(next);
            onLabelWrite?.(next);
          }}
          // Loses focus (click elsewhere, tab away) commits and exits —
          // the ONE path `onEnter`/`onEscape` below don't already cover.
          onEditEnd={exitEditing}
          multiline={false}
          language={language}
          fontSizePx={fontSizePx}
          align={align}
          // An <input>-like port label: cut at the edge, no scrollbar —
          // same convention `LabeledPort.stories.tsx`'s `CodeLabel` story
          // already established for a CodeEditor filling this slot.
          overflow="clip"
          columns={Math.max(MIN_LABEL_COLUMNS, value.length)}
          autoFocus="select"
          onEnter={exitEditing}
          onKeyDown={onLabelKeyDown}
          onEscape={() => {
            setValue(snapshotRef.current);
            onLabelWrite?.(snapshotRef.current);
            exitEditing();
          }}
        />
      </span>
    );
  }

  const isEmpty = value === "";
  const labelSeverity = maxDiagnosticSeverity(diagnostics);
  return (
    <span
      data-slot="port-label"
      data-direction={direction}
      data-editing="false"
      className={cn("flex min-w-0 items-center", className)}
      style={{
        ...style,
        // The label's hit region IS this span's own box (the onClick
        // below) — an implicit region with no named constant, painted on
        // the real target so it cannot drift. Nothing while `disabled`:
        // no handler, no region.
        ...(showHitRegion && !disabled
          ? { background: HIT_REGION_FILL, outline: HIT_REGION_OUTLINE, outlineOffset: -1 }
          : null),
      }}
      onClick={() => {
        if (disabled) return;
        snapshotRef.current = value;
        setEditing(true);
      }}
    >
      {/* Truthful rendering: a long value still ellipsizes visually, but
       *  the full string stays one hover away via `title` — the same
       *  recipe `editableText.tsx`'s own `editable-text-content` span
       *  uses, not reinvented here. */}
      <DiagnosticTooltip diagnostics={diagnostics}>
      <span
        data-slot="port-label-display"
        data-diagnostic={labelSeverity}
        title={!isEmpty ? value : undefined}
        data-placeholder={isEmpty && placeholder ? "" : undefined}
        style={{
          fontSize: fontSizePx,
          // The variant's weight (v2 SystemSketch-original is 500, the
          // rest 400) — read from the property the port root publishes,
          // falling back to the plain weight for a bare label.
          fontWeight: "var(--bbox-port-label-weight, 400)",
          // §5's wavy/dotted underline mark (./diagnostic.tsx's own
          // `diagnosticUnderlineStyle`) — `undefined` when there is
          // nothing to mark, so a plain label's `text-decoration` is
          // exactly what it was before this axis existed.
          ...(labelSeverity ? diagnosticUnderlineStyle(labelSeverity) : null),
          // The skin seam (src/skin/skin.ts + skin.css) — the ONE token
          // this resting display text needs. `--bbox-skin-font-sans` is
          // set INLINE (beating inheritance) rather than the plain
          // `--bbox-skin-font` Block/Badge/Port already inherit, because a
          // LabeledPort is not always mounted inside a Block's own
          // font-cascaded subtree — PortEdge.stories.tsx and
          // LabeledPort.stories.tsx both mount it as a bare specimen with
          // no ancestor that sets ANY font token. Fallback is `inherit`,
          // this label's exact behaviour today (no font-family of its own
          // at all), so a consumer who never imports skin.css is
          // byte-identical.
          // The variant's face (v2 SystemSketch-original is the mono
          // signature row) — still through the skin's font tokens, so the
          // sketch skin re-fonts every variant; see `portVariantLabelFont`.
          fontFamily,
          display: "block",
          minWidth: 0,
          maxWidth: "100%",
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
          textAlign: align,
          opacity: isEmpty ? 0.5 : undefined,
        }}
      >
        {isEmpty ? (placeholder ?? "") : value}
      </span>
      </DiagnosticTooltip>
      {type ? (
        // Reading order name → type on BOTH directions, never mirrored —
        // the app's own floating port made the same call and recorded why
        // (apps/systemsketch/src/shapes/port/PortFace.tsx `RestingLabel`:
        // mirroring rendered an output as "Image mask", a type-first
        // annotation language). `white-space: pre` keeps every authored
        // character (truthful rendering). Paint: portVariants.css.
        <span data-slot="port-label-type" style={{ marginLeft: 6, fontFamily }}>
          {type}
        </span>
      ) : null}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* LabeledPort — Port + the label slot + the secondary slot, paired as */
/* flex siblings for a standalone specimen.                            */
/* ------------------------------------------------------------------ */

export interface LabeledPortProps extends ComponentProps<"div"> {
  /** The label slot's entire content, one line. */
  children?: string;
  direction?: PortDirection;
  edge?: BlockSide;
  diameter?: PortSize;
  /** Sensible default is `inwardTextLayout(edge)` when omitted. */
  textLayout?: PortTextLayout;
  textSize?: PortTextSize;
  state?: PortState;
  hidden?: boolean;
  dimmed?: boolean;
  hinting?: boolean;
  /** Forwarded to `Port` untouched — see `PortDotPaintInput.availability`'s
   *  own doc (docs/INVALID-STATES-PLAN.md D5, ruling 5). */
  availability?: "available" | "unavailable";
  /**
   * The diagnostic axis (docs/INVALID-STATES-PLAN.md §5's LabeledPort
   * row) — forwarded to `Port` (the dot mark) and to the built-in label
   * (the wavy/dotted underline — a fixed treatment regardless of
   * `highlighterKind`; Zach's own approval on text marks: "no need to
   * reinvent the wheel there at all"). Ignored by the underline when
   * `labelSlot` overrides the built-in field — a host-supplied slot owns
   * its own typography. `DiagnosticFlag` (./highlighter.tsx) is NOT wired
   * here automatically; §5 says it "may ride the existing secondarySlot",
   * so a host composes `secondarySlot={<DiagnosticFlag diagnostics={...} />}`
   * itself rather than this component silently placing one.
   */
  diagnostics?: Diagnostic[];
  /** Forwarded to `Port` — see `PortDotPaintInput.highlighterKind`'s own
   *  doc. Has no effect on the label's own underline. */
  highlighterKind?: HighlighterKind;
  /**
   * The label slot's placement, reaching PAST `textLayout` (the preset over
   * exactly these three). Omit any of them and the preset decides; set one
   * and it wins. `offsetX` is + away from the dot along the origin's own
   * axis, `offsetY` is + DOWN, and both may be negative.
   */
  labelOrigin?: SlotOrigin;
  labelAlign?: SlotAlign;
  labelOffsetX?: number;
  labelOffsetY?: number;
  /** The secondary slot's placement — the same three controls over the
   *  same `SlotOrigin` type, with `secondarySlotLayout` as its preset. */
  secondaryOrigin?: SlotOrigin;
  secondaryAlign?: SlotAlign;
  secondaryOffsetX?: number;
  secondaryOffsetY?: number;
  /**
   * Content for the LABEL position. Present — INCLUDING empty — replaces
   * the built-in `DefaultPortLabel` entirely, same position, same lift.
   * Absent means the built-in field. This is the seam Phase 4's multi-line
   * lane editor (and, later, a real CodeField) attaches through: swap what
   * fills this slot without touching `LabeledPort`'s placement math at all.
   */
  labelSlot?: ReactNode;
  /** Content for the SECONDARY position, same present-beats-absent
   *  contract as `labelSlot`. There is no `producers`-count fallback here
   *  (D3) — an unset secondary slot renders nothing, full stop. */
  secondarySlot?: ReactNode;
  /** Where an explicit `secondarySlot` sits. Omit for the AUTO default —
   * the corner opposite wherever the label is actually flowing. */
  secondarySlotLayout?: SecondarySlotLayout;
  /** No caret, no edits on the label's built-in field. */
  disabled?: boolean;
  /** Forwarded to `Port` — the halo's diameter in px (default 40). */
  hitPx?: number;
  /**
   * The visual variant (src/skin/portVariants.ts). Omit and the
   * document-wide `<html data-bbox-port-variant>` decides (default `v1`);
   * set it to pin this port. Decides the default `diameter` and `textSize`
   * when those are omitted too. Its RING never moves the label: the label
   * clears the fixed `PORT_RING_OVERHANG_PX` allowance past the dot's box
   * on every variant, so only the box size itself shifts the text.
   */
  variant?: PortVariantId;
  /**
   * The port's TYPE, drawn as a muted secondary run after the name
   * (`[data-slot="port-label-type"]`) — "label small inside the row, type
   * secondary". Also handed to `Port` as `dataType`, where the two by-type
   * variants (v2, v3) colour the dot from it through their own source's
   * palette (`portTypePaint`); every other variant colours by state.
   * Ignored by a host-supplied `labelSlot`, which owns its own runs.
   */
  type?: string;
  /** An explicit CSS colour for the type — wins over either palette. */
  typeColor?: string;
  /** Forwarded to `Port` — the fan-in count circle riding the dot, on the
   *  side away from the label. See `PortProps.producers`. */
  producers?: number;
  /** Forwarded to `Port` — see `PortProps.selected`. */
  selected?: boolean;
  /**
   * Paint every pointer target this composite owns: the dot's halo (via
   * `Port`) and — when the built-in label is editable — the label's own
   * click-to-edit box. Pure paint; geometry is identical on or off. A
   * host-supplied `labelSlot` owns its own interactivity, so nothing is
   * painted over it.
   */
  showHitRegion?: boolean;
  /** Fired on every keystroke of the built-in label field. */
  onLabelWrite?(value: string): void;
  /**
   * The built-in label editor's own key hook, ahead of its keymap — see
   * `CodeEditorProps.onKeyDown`. `PortEdge` hands its move-this-port chord
   * in here (`keyboardReorder.ts`); return `true` to claim the key.
   */
  onLabelKeyDown?(event: KeyboardEvent, view: EditorView): boolean;
  /** Shown in the built-in label field when `children` is empty. */
  placeholder?: string;
  /**
   * The built-in label field's syntax parser while editing (F-1/F-3), e.g.
   * `python()` from `@codemirror/lang-python` — the same prop `CodeEditor`
   * itself already exposes, forwarded straight through. Omit for plain
   * text. Ignored when `labelSlot` is set — that override owns its own
   * editor entirely, same as `CodeLabel` story's pattern below.
   */
  labelLanguage?: LanguageSupport;
}

/**
 * The flex-row pairing of `Port` + its two slots, for a standalone specimen
 * — a real host mounting a port on a real block wall would position the
 * dot and the label independently instead (the donor package's `anchored`
 * mode, deliberately not ported here — see this file's module doc).
 */
export function LabeledPort({
  direction = "input",
  edge = "left",
  diameter,
  textLayout,
  textSize,
  state = "empty",
  hidden = false,
  dimmed = false,
  hinting = false,
  availability,
  diagnostics,
  highlighterKind,
  labelOrigin,
  labelAlign,
  labelOffsetX,
  labelOffsetY,
  secondaryOrigin,
  secondaryAlign,
  secondaryOffsetX,
  secondaryOffsetY,
  labelSlot,
  secondarySlot,
  secondarySlotLayout,
  disabled = false,
  hitPx,
  showHitRegion = false,
  onLabelWrite,
  onLabelKeyDown,
  placeholder,
  labelLanguage,
  variant: variantId,
  type,
  typeColor,
  producers,
  selected = false,
  className,
  style,
  children = "",
  ...props
}: LabeledPortProps) {
  // Hooks before the early return — `hidden` is a prop, not a hook order.
  const variant = usePortVariant(variantId);
  if (hidden) return null;
  const resolvedTextLayout = textLayout ?? inwardTextLayout(edge);
  // Omitted `diameter`/`textSize` fall to the VARIANT, not to a constant —
  // that is the whole mechanism by which "the small pair is the default"
  // (Zach's ruling) reaches every port nobody sized explicitly, and by
  // which the `<html>` switch re-sizes them all.
  const diameterPx = diameter === undefined ? variant.dot.diameter : typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  const resolvedTextSize: PortTextSize = textSize ?? variant.text;
  const labelFont = portVariantLabelFont(variant);
  const resolvedSecondaryLayout = secondarySlotLayout ?? defaultSecondarySlotLayout(resolvedTextLayout);

  // The named layout is the PRESET; an explicit origin/offset reaches past
  // it — the unified (origin, x, y) model every host and every saved shape
  // ultimately speaks (see port.layout.ts's own module doc).
  const textLayoutPreset = TEXT_LAYOUT_AS_PLACEMENT[resolvedTextLayout];
  const labelPlacement: SlotPlacement = {
    origin: labelOrigin ?? textLayoutPreset.origin,
    align: labelAlign ?? textLayoutPreset.align,
    offsetX: labelOffsetX ?? 0,
    offsetY: labelOffsetY ?? textLayoutPreset.offsetY,
  };
  const secondaryPlacement: SlotPlacement = {
    origin: secondaryOrigin ?? SECONDARY_LAYOUT_AS_ORIGIN[resolvedSecondaryLayout],
    align: secondaryAlign ?? "center",
    offsetX: secondaryOffsetX ?? 0,
    offsetY: secondaryOffsetY ?? 0,
  };

  // A host-given `secondarySlot` wins outright — INCLUDING when it is
  // empty (`<></>`), which is what makes an emptied slot stay empty rather
  // than reverting to some default. There is no `producers` fallback (D3).
  const resolvedSecondarySlot: ReactNode = secondarySlot !== undefined ? secondarySlot : undefined;

  // B4 fix: the ROOT box is exactly the dot's own box (diameterPx square),
  // never the label's. Both slots are absolutely positioned OFF that box
  // via `slotPlacementStyle` — the SAME function the secondary slot always
  // used — instead of the old flex-row pairing (`originFlexDirection` +
  // a `flexOffsetTransform` computed as a delta from the ROW's own centre).
  // That old approach silently assumed the row's cross-centre (what
  // `items-center` actually aligns) equals the DOT's centre — true only
  // when the label is exactly as tall as the dot. A host that centres this
  // component as a unit (a PortEdge rail's `alignItems: "center"`, in
  // particular) was therefore centring the COMBINED dot+label box, so the
  // dot itself drifted off the rail's centre line the instant a label was
  // taller than the dot (docs bug B4). Sizing the root to the dot alone
  // makes that impossible by construction: whatever centres THIS component
  // centres the dot, and the label — now an overlay, not a flow sibling —
  // extends outward from wherever it actually sits, at any height.
  // The label clears the RESERVED ring allowance (`PORT_RING_OVERHANG_PX`),
  // not this variant's painted ring — see port.layout.ts's WHY: a variant
  // switch moves text only by the box's own size change, and every layout
  // consumer that reads the same closed form keeps agreeing.
  const labelSlotStyle = slotPlacementStyle(labelPlacement, { w: diameterPx, h: diameterPx }, PORT_LABEL_GAP);

  // The producers circle rides the side AWAY from the label, so it never
  // sits on the text: a left-wall port (label flowing right, into the
  // block) wears it on the left, outside the block, where the cables it
  // counts actually arrive.
  const producersAt: "left" | "right" = labelPlacement.origin === "right" ? "left" : "right";

  return (
    <div
      data-slot="port"
      data-state={state}
      data-direction={direction}
      data-edge={edge}
      data-text-layout={resolvedTextLayout}
      {...{ [PORT_VARIANT_ATTR]: variant.id }}
      className={cn("relative inline-flex shrink-0", className)}
      // The variant's custom properties, published on THIS root so the label
      // and type runs (siblings of the dot, not its descendants) read the
      // same numbers the dot painted with — and so a consumer with only the
      // component source, no portVariants.css, still renders right.
      style={{ width: diameterPx, height: diameterPx, ...portVariantVars(variant), ...style }}
      {...props}
    >
      <Port
        state={state}
        diameter={diameter}
        variant={variant.id}
        dimmed={dimmed}
        hinting={hinting}
        availability={availability}
        diagnostics={diagnostics}
        highlighterKind={highlighterKind}
        hitPx={hitPx}
        showHitRegion={showHitRegion}
        selected={selected}
        producers={producers}
        producersAt={producersAt}
        dataType={type}
        typeColor={typeColor}
      />
      {labelSlot !== undefined ? (
        <span data-slot="port-label-slot" className="absolute" style={labelSlotStyle}>
          {labelSlot}
        </span>
      ) : (
        <DefaultPortLabel
          direction={direction}
          textSize={resolvedTextSize}
          type={type}
          fontFamily={labelFont}
          disabled={disabled}
          onLabelWrite={onLabelWrite}
          onLabelKeyDown={onLabelKeyDown}
          placeholder={placeholder}
          language={labelLanguage}
          showHitRegion={showHitRegion}
          diagnostics={diagnostics}
          className="absolute"
          style={labelSlotStyle}
        >
          {children}
        </DefaultPortLabel>
      )}
      {resolvedSecondarySlot != null && (
        // F-6: "the slot position may change but its always just a single
        // horizontal text line, similar to the primary label slot" —
        // `whiteSpace: nowrap` is the structural guarantee (Zach's
        // screenshot showed "Event 4" wrapping to two lines the instant a
        // host's own width constraint squeezed this slot; a shrink-to-fit
        // absolute box never needs to wrap ON ITS OWN, but nothing stopped
        // an ANCESTOR from imposing one — see `SecondarySlot` story's
        // `SingleLineContent` case). `display: inline-flex` + `alignItems:
        // center` keeps arbitrary content (a `<Pill>`, an icon+digit pair)
        // vertically centred on one line rather than stacking as block
        // children would.
        <span
          data-slot="port-secondary-slot"
          className="pointer-events-none absolute inline-flex items-center whitespace-nowrap"
          style={slotPlacementStyle(secondaryPlacement, { w: diameterPx, h: diameterPx }, PORT_SECONDARY_SLOT_GAP_PX)}
        >
          {resolvedSecondarySlot}
        </span>
      )}
    </div>
  );
}

// src/components/paintOrder.ts — the paint-order ladder (Card 04, the
// z-order lane of docs/provenance/z-order.md's wave).
//
// THE RULING THIS FILE IMPLEMENTS (full text: the z-order lane brief) —
// "the line is the box, not the node." The mechanical test: can the
// answer be computed from ONE component's own props, knowing nothing
// about what else is on the canvas and nothing about what the pointer is
// doing?
//   - Yes → paint order. Deterministic from the component's own tree,
//     identical on every host, required for the render to be correct AT
//     ALL. That is layout, it is portable, and it lives HERE, named.
//   - Needs the selection, the pointer, or a sibling node's identity →
//     canvas z-order. Host-owned. Never travels, never lives here.
//
// THIS IS A REFACTOR, NOT A FEATURE, for five of these nine tiers: the
// kit already emitted raw numeric `zIndex` literals before this file
// existed, ad hoc, coordinated only by prose comments across three
// files. Replacing them with named tokens below is defined to be a
// NO-OP — every one of the five reproduces its pre-existing literal
// exactly, verified by a captured getComputedStyle before/after on the
// same mounted stories (src/components/PaintOrder.stories.tsx,
// "TokensReproduceTodaysNumbers"; the raw numbers are recorded in
// docs/provenance/z-order.md). Only `headerChrome` is new — the nesting
// tier Zach actually asked for (a Block's header/footer must paint above
// its own `BlockMembers` region, however deeply that region nests other
// Blocks inside it).
//
// THE ISOLATION INVARIANT is what makes a closed, per-tier integer scale
// safe to reuse across files that never coordinate with each other:
// every component root that emits a tier below sets `isolation: isolate`
// (see block.tsx's root, blockPort.tsx's `[data-slot="block-port"]`
// root, portEdge.tsx's `[data-slot="port-edge"]` root). A CSS stacking
// context is a hard wall — a descendant's z-index cannot outrank
// anything outside its isolated root no matter what integer it carries.
// That is what lets `portDot` and `flagBadge` share the raw value `1`
// without ever actually competing: they live in different isolated
// roots and are never compared in the same stacking context. It is also
// what makes `headerChrome` beat an arbitrarily deep nested Block's own
// highest tier: the nested Block, however many levels deep, is trapped
// inside its OWN isolated root, so it contributes only its own
// (z-index:auto, i.e. stack level 0) box to its parent's stacking order
// — never its interior maximum. Remove the invariant from one nested
// root and this reasoning breaks; `PaintOrder.stories.tsx`'s
// `NestedChildStaysBehindHeader` story is the measured proof, and a
// mutation test (temporarily deleting one `isolation: isolate`) is
// recorded as having actually turned it red in docs/provenance/z-order.md.
//
// The kit NEVER emits a z-index on a node ROOT (a Block's own outer box,
// a BlockPort wrapper's own outer box) — only on things INSIDE one. A
// host's canvas z-order (raise-on-select, drag-to-front, Vyuh
// Flow's `child.z = parent.z + 1`) stays exactly that: host-owned,
// never emitted here.

/**
 * The closed, ordered ladder — ascending: earlier names paint further
 * back, later names paint on top, WITHIN one isolated component root.
 * "Ordered" is a design narrative connecting the tiers to what they
 * paint, not a claim that every numeric value is globally monotonic —
 * the isolation invariant above is what actually keeps unrelated tiers
 * (e.g. `portDot` and `flagBadge`, both `1`, in different files) from
 * ever needing to out-rank each other; see `PAINT_TIER_VALUE`'s own
 * per-entry comments for exactly which existing call site each number
 * reproduces.
 */
export const PAINT_TIER_ORDER = [
  "underlay",
  "surface",
  "memberContent",
  "memberOverflow",
  "wire",
  "headerChrome",
  "portDot",
  "flagBadge",
  "laneOverlay",
  "dragActive",
  "diagnosticHalo",
] as const;

export type PaintTierName = (typeof PAINT_TIER_ORDER)[number];

/**
 * One frozen value per tier. Every entry that reproduces a pre-existing
 * raw literal says so and names its call site; the two new entries
 * (`headerChrome`, and the currently-unwired placeholders) say that too.
 */
const PAINT_TIER_VALUE: Readonly<Record<PaintTierName, number>> = Object.freeze({
  // NEW (2026-09-22, lane side-effect-ports) — the one NEGATIVE tier, and
  // the only one that paints BELOW a box's own content. A negative z-index
  // inside an isolated root paints right after that root's own background
  // and border and before every in-flow child, so a line drawn here sits on
  // the card surface and UNDER the body, the header text and — in an
  // expanded Block — every member card. Its one caller is the mutation line
  // (blockPort.tsx's `MutationLines`), which must not paint over member
  // content; `wire` (above `memberContent`) says the opposite.
  underlay: -1,
  // Placeholder — not wired to any raw zIndex today. Lowest in the
  // ladder: a surface/inset background paints under its own box's
  // content.
  surface: 0,
  // portEdge.tsx:846 (`FreeSlotCard`) — the RESTING (non-dragging) value
  // of `zIndex: isDragging ? 10 : 1`. A free-mode draggable card is
  // exactly "content within the box".
  memberContent: 1,
  // Placeholder — not wired today. Content that bleeds past its own
  // slot but stays inside the parent box (e.g. a future overflowing
  // member preview).
  memberOverflow: 1,
  // Placeholder — not wired today. A connector line drawn within one
  // component's own box (distinct from `Trace`/cross-canvas wires,
  // which are host-composed and out of scope for a single box's ladder).
  wire: 1,
  // NEW — block.tsx's `block-header` / `block-footer`. Not a
  // pre-existing literal: today those two slots are non-positioned and
  // structurally lose to ANY positioned sibling (including a
  // `position: relative` `BlockMembers` region with z-index:auto),
  // which is exactly backwards for nesting. `headerChrome` is what a
  // Block's own chrome needs to beat its own members region — see this
  // file's header comment and `PaintOrder.stories.tsx`'s
  // `NestedChildStaysBehindHeader`.
  headerChrome: 2,
  // blockPort.tsx:412 (`BlockFunctionPort`) and blockPort.tsx:538
  // (`BlockPortRail`'s wrapper) — both were `zIndex: 1`. A port's own
  // dot, whether the header's reserved function port or a rail item,
  // needs to sit above the Block it decorates (BlockPort.stories.tsx's
  // own `StackingAboveBlock`) — including above the Block's OWN
  // `headerChrome`, since the function port is literally the header's
  // pin. That relationship holds without portDot needing to outrank
  // headerChrome numerically: the whole `<Block>` is a SIBLING of the
  // rail/function-port divs inside `BlockPort`'s own isolated
  // `[data-slot="block-port"]` root, not a descendant of them, so the
  // comparison that actually matters is portDot's explicit positive
  // z-index vs. the whole (isolation-capped) Block's stack level 0 —
  // see this file's header comment.
  portDot: 1,
  // block.tsx:334 (`block-diagnostic-flag`) — was `zIndex: 1`. The
  // corner diagnostic badge.
  flagBadge: 1,
  // portEdge.tsx:1003 (`PortLaneOverlay`) — was `zIndex: 5`. The
  // floating multi-line lane editor.
  laneOverlay: 5,
  // portEdge.tsx:846 (`FreeSlotCard`) — the DRAGGING value of
  // `zIndex: isDragging ? 10 : 1`. Explicitly named, per the brief's own
  // instruction, so the one place a gesture leaks into paint order is
  // visible and reviewable rather than inline.
  dragActive: 10,
  // Placeholder — not wired today. Block's own halo highlighter
  // (`highlighterKind="halo"`) is a `boxShadow`, which needs no z-index
  // at all; this tier exists so a future halo-as-overlay implementation
  // has a named slot at the top of the ladder without inventing a
  // number.
  diagnosticHalo: 1,
});

/** Look up one tier's frozen z-index value. The only way any component
 *  in `src/components` may produce a `zIndex` — see
 *  `paintOrder.test.ts`'s grep guard, which fails on any raw numeric
 *  `zIndex` literal surviving in this directory. */
export function paintTier(name: PaintTierName): number {
  return PAINT_TIER_VALUE[name];
}

/**
 * The one structural half of the ruling: every component root that
 * emits any tier above must set this. Spread onto that root's `style`.
 * Kept as a named export (rather than callers writing the literal
 * object) so `PaintOrder.stories.tsx` can assert every emitting root
 * used exactly this, not a hand-rolled equivalent.
 */
export const ISOLATED_ROOT_STYLE = { isolation: "isolate" } as const;

// src/components/popover.tsx — based on the stock shadcn `new-york` Popover
// (apps/docs/src/registry/new-york-v4/ui/popover.tsx, over Base UI's
// `@base-ui/react/popover`), NOT copied verbatim: that stock copy only ever
// positions against its own trigger, and this kit needs a popover that can
// hang off a point on the canvas that has no DOM element at all (the
// font-size popover in docs/menus/screenshots/03-font-size-popover.png opens
// off the selection, not off a button). `PopoverPositioner.Props` already
// accepts `anchor: Element | VirtualElement | ...` (verified against
// apps/storybook-basics/node_modules/@base-ui/react/internals/
// useAnchorPositioning.d.ts) — the stock copy's `Pick` just never asked for
// it. `container` and `collisionPadding` are exposed for the same reason:
// they're the two other host-contract knobs docs/menus/MENU-KIT-DESIGN.md
// §4 names ("container? — portal target inside the host's token scope",
// "collisionPadding" for the boundary a canvas-anchored popup must respect).
"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";

import { cn } from "../lib/utils";

function Popover({ ...props }: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />;
}

function PopoverTrigger({ ...props }: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />;
}

export interface PopoverContentProps
  extends PopoverPrimitive.Popup.Props,
    Pick<
      PopoverPrimitive.Positioner.Props,
      "align" | "alignOffset" | "side" | "sideOffset" | "anchor" | "collisionPadding"
    > {
  /** WHY: portal target inside the host's own token/theme scope (the kit's
      universal host contract, MENU-KIT-DESIGN.md §4) — `undefined` keeps
      Base UI's own default of `document.body`, which is fine for a host
      with no scoped root. */
  container?: PopoverPrimitive.Portal.Props["container"];
  /** WHY (ported concept, menuLabModel.ts's `popoverMode`): a live text
      editor open elsewhere on the surface (an inline rename field, a
      color-hex input) must keep its OWN focus while this popover is open —
      the default "move focus into the popup on open" would steal the caret
      mid-keystroke. Maps to Base UI Popup's `initialFocus`, narrowed to a
      boolean because the kit only ever needs "move focus" vs "leave it
      alone," never `initialFocus`'s ref/interaction-type callback forms.
      Default `true` (Base UI's own default); pill/editing surfaces pass
      `false`. */
  autoFocus?: boolean;
}

function PopoverContent({
  className,
  align = "center",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  anchor,
  collisionPadding,
  container,
  autoFocus = true,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal container={container}>
      <PopoverPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        anchor={anchor}
        collisionPadding={collisionPadding}
        className="isolate z-50 outline-none"
      >
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          initialFocus={autoFocus}
          className={cn(
            "data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 bg-popover text-popover-foreground flex flex-col gap-2.5 rounded-lg p-2.5 text-sm shadow-md ring-1 duration-100 data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2 z-50 w-72 origin-(--transform-origin) outline-hidden",
            className,
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  );
}

export { Popover, PopoverContent, PopoverTrigger };

