/**
 * The board's four-value axis — "what is in the port": empty, a default
 * value set, wired to something, or data has flowed through it just now.
 * `dimmed`/`hidden` are NOT rungs of this union (see `PortProps`'s own
 * docs) — neither is a fact about what the port IS.
 */
export type PortState = "empty" | "valueSet" | "wired" | "received";

export const PORT_STATES: PortState[] = ["empty", "valueSet", "wired", "received"];

export const PORT_STATE_LABELS: Record<PortState, string> = {
  empty: "Empty",
  valueSet: "Default Value",
  wired: "Wired",
  received: "Data Received",
};

interface StateTokenPair {
  ring: string | null;
  fill: string | null;
  core: string | null;
}

const STATE_TOKENS: Record<PortState, StateTokenPair> = {
  empty: { ring: "foreground", fill: null, core: null },
  valueSet: { ring: "muted-foreground", fill: "muted", core: null },
  wired: { ring: "primary", fill: null, core: "primary" },
  received: { ring: "bbox-received", fill: "bbox-received", core: "bbox-received" },
};

/**
 * `primary` resolves through the bbox accent (with a fallback to whatever
 * host `--primary` already means) so "wired" reads as the design system's
 * own orange rather than the host's button colour — same special case
 * `paintVar` makes in the donor package. `--bbox-primary`/`--bbox-received`
 * are the two tokens this phase appends to `src/globals.css`.
 */
export function paintVar(token: string): string {
  return token === "primary" ? "var(--bbox-primary, var(--primary))" : `var(--${token})`;
}

/* ------------------------------------------------------------------ */
/* The dot's paint                                                     */
/* ------------------------------------------------------------------ */

export interface PortDotPaintInput {
  state?: PortState;
  dimmed?: boolean;
  hinting?: boolean;
  /**
   * Drag-time validity preview (docs/INVALID-STATES-PLAN.md D5, ruling 5)
   * — "on by default": whether THIS port is a legal target for the
   * connection currently being dragged. `undefined` means no gesture is
   * in flight (zero paint change — every pre-existing snapshot stays
   * byte-identical). Computed ONCE per gesture by the host
   * (`connectionAvailability`, scene kit) and handed down as paint; this
   * component never asks WHY a port is unavailable, only THAT it is —
   * ruling 2's layering rule, one prop over. Wins over `hinting`/`dimmed`
   * (see `portRingColor`'s own precedence doc) because it is the more
   * specific, more ephemeral, in-gesture fact.
   */
  availability?: "available" | "unavailable";
  /** The diagnostic axis (docs/INVALID-STATES-PLAN.md §5's Port row) — a
   *  judgement ABOUT the port, made by an external producer, never a fifth
   *  `state`. Only the worst severity present paints (`maxDiagnosticSeverity`,
   *  ./highlighter.tsx); the rest ride the flag's popover, not this mark. */
  diagnostics?: Diagnostic[];
  /** Which `HighlighterKind` draws the mark. Defaults to
   *  `DEFAULT_HIGHLIGHTER_KIND` ("stroke") — Zach's own lean from the
   *  report feedback; `"halo"` is the pre-existing treatment, kept as a
   *  sibling, not deleted. */
  highlighterKind?: HighlighterKind;
  /**
   * The visual variant in force (src/skin/portVariants.ts). Decides the
   * ring widths and which paint grammar maps `state` onto ring, disc and
   * core (`portGrammarPaint`). Defaults to v1 so every pure call site
   * (`sketchAtEdge`'s ring colour, a story computing a paint) gets the
   * default look without resolving anything; `Port` passes its own.
   */
  variant?: PortVariant;
  /**
   * The port's declared TYPE name — read only by the two by-type grammars
   * (v2 SystemSketch-original, v3 langflow), each through its own source's
   * palette (`portTypePaint`). Every other grammar ignores it: colour
   * comes from STATE there (the 2026-09-10 ruling).
   */
  dataType?: string;
  /** An explicit CSS colour for the type, winning over either palette. */
  typeColor?: string;
}

const DEFAULT_VARIANT = PORT_VARIANTS[DEFAULT_PORT_VARIANT_ID];

/**
 * Static half of the dot's class — sizing/shape/transition only. Every
 * colour fact is dynamic per state and lives in `portDotStyle` instead.
 *
 * Hover is a real CSS `:hover` pseudo-class, deliberately NOT a `hover`
 * prop — nothing outside this component ever needs to SET hover. Since
 * 2026-09-19 the hover rule lives in `src/skin/portVariants.css` (it
 * reads the variant's own `--bbox-port-hover-scale`/`-ring`), so the old
 * `hover:scale-110` utility is gone from here; `transition-transform`
 * (Tailwind v4: `transform, translate, scale, rotate`) still animates it.
 */
export function portDotClass(): string {
  return "relative box-border inline-flex shrink-0 rounded-full transition-transform duration-[50ms] ease-in-out motion-reduce:transition-none";
}

/**
 * The single place `availability` is folded into the pre-existing
 * `hinting`/`dimmed` paint facts (docs/INVALID-STATES-PLAN.md D5, ruling
 * 5's precedence: `availability > hinting > dimmed > state`). `undefined`
 * (no gesture in flight) passes `hinting`/`dimmed` through untouched — the
 * zero-paint-change contract every existing snapshot depends on.
 * `"available"` reuses `hinting`'s own shape outright; `"unavailable"`
 * reuses `dimmed`'s — each OVERRIDING the caller's own `hinting`/`dimmed`
 * rather than composing with them, because a port cannot simultaneously be
 * "the drag target" and "faded for being off-focus".
 */
function resolveAvailabilityPaint(
  availability: PortDotPaintInput["availability"],
  hinting: boolean,
  dimmed: boolean,
): { hinting: boolean; dimmed: boolean } {
  if (availability === "available") return { hinting: true, dimmed: false };
  if (availability === "unavailable") return { hinting: false, dimmed: true };
  return { hinting, dimmed };
}

/**
 * One grammar's answer for one state: the ring's colour, the disc's colour
 * (`null` = the card, i.e. hollow) and the centre's (`null` = no core span).
 *
 * WHY one table per grammar, not per-channel enums: the five sources
 * disagree about what a port's colour MEANS — STATE in this trunk (the
 * 2026-09-10 ruling), TYPE in the original SystemSketch and in langflow —
 * and about which circle carries it. Independent knobs would let two
 * grammars combine into a look nobody proposed; a switch keeps each variant
 * exactly what its source draws. Gesture facts (`hinting`, `dimmed`,
 * `availability`) are NOT grammar: they override every variant the same
 * way in `portRingColor`/`portDotStyle`/`portCoreStyle` below.
 */
export interface PortGrammarPaint {
  ring: string | null;
  fill: string | null;
  core: string | null;
}

export function portGrammarPaint(
  state: PortState,
  variant: PortVariant = DEFAULT_VARIANT,
  dataType?: string,
  typeColor?: string,
): PortGrammarPaint {
  const tokens = STATE_TOKENS[state];
  const tok = (token: string | null) => (token ? paintVar(token) : null);
  switch (variant.dot.grammar) {
    case "trunk":
      // v1 — this trunk's own three circles, unchanged; only the scale moved.
      return { ring: tok(tokens.ring), fill: tok(tokens.fill), core: tok(tokens.core) };
    case "systemsketch": {
      // v2 — block-canvas.css:1103-1132: the ring is ALWAYS the type's
      // colour; the disc is the card (unwired), muted (`.Port_default`,
      // owns a default), the type colour (`.Port_connected`). `received`
      // has no original counterpart, so it borrows the trunk's own token.
      const type = portTypePaint("systemsketch", dataType, typeColor)!;
      const fill = state === "valueSet" ? paintVar("muted-foreground") : state === "wired" ? type.disc : state === "received" ? paintVar("bbox-received") : null;
      return { ring: type.disc, fill, core: null };
    }
    case "langflow": {
      // v3 — handleRenderComponent/index.tsx:110-131: the disc IS the type
      // colour and the 3px ring its pale `-foreground` pair, in EVERY
      // state. langflow lets the cable say "wired" (a connected handle only
      // swaps to the SOURCE's colour, :144-145) — faithfully, so here.
      const type = portTypePaint("langflow", dataType, typeColor)!;
      return { ring: type.tint, fill: type.disc, core: null };
    }
    case "pearl":
      // v4 — React Flow UI `BaseHandle`: `bg-slate-100` + `border-slate-300`
      // at rest (neutral token mixes, so dark mode follows), stock xyflow
      // ink once wired (`--xy-handle-background-color-default: #1a192b`,
      // this app's `--foreground`), the trunk's received token for data.
      switch (state) {
        case "empty":
          return { ring: "color-mix(in srgb, var(--foreground) 24%, var(--card))", fill: "color-mix(in srgb, var(--foreground) 5%, var(--card))", core: null };
        case "valueSet":
          return { ring: "color-mix(in srgb, var(--foreground) 45%, var(--card))", fill: "color-mix(in srgb, var(--foreground) 22%, var(--card))", core: null };
        case "wired":
          return { ring: paintVar("foreground"), fill: paintVar("foreground"), core: null };
        case "received":
          return { ring: paintVar("bbox-received"), fill: paintVar("bbox-received"), core: null };
      }
      break;
    case "reticle":
      // v5 — DP - Port's three circles literally: the outline takes the
      // state colour, the background stays the card, the CENTRE is always
      // drawn — muted until something attaches, lit when wired.
      return {
        ring: tok(tokens.ring),
        fill: null,
        core: tok(tokens.core) ?? (state === "valueSet" ? paintVar("muted-foreground") : "color-mix(in srgb, var(--foreground) 32%, var(--card))"),
      };
  }
  return { ring: tok(tokens.ring), fill: tok(tokens.fill), core: tok(tokens.core) };
}

/**
 * The dot's ring colour, as one exported derivation.
 *
 * WHY extracted rather than left inline (ported from packages/bbox-ui/src/
 * port.tsx's own `portRingColor`): the sketch skin draws the ring as a
 * path instead of as box-shadow layers, and it has to be the SAME colour.
 * A second copy of this precedence is exactly how a `hinting` port would
 * end up orange in one skin and grey in another. `null` means "this state
 * paints no ring at all". Precedence: see `resolveAvailabilityPaint`'s doc
 * — gesture facts first, then the variant's grammar.
 */
export function portRingColor({
  state = "empty",
  dimmed = false,
  hinting = false,
  availability,
  variant = DEFAULT_VARIANT,
  dataType,
  typeColor,
}: PortDotPaintInput): string | null {
  const effective = resolveAvailabilityPaint(availability, hinting, dimmed);
  if (effective.hinting) return paintVar("primary");
  if (effective.dimmed) return paintVar("muted-foreground");
  return portGrammarPaint(state, variant, dataType, typeColor).ring;
}

/**
 * The dot's ring/fill, per the variant's grammar (`portGrammarPaint`).
 * `dimmed` forces the ring to `muted-foreground` and
 * fades the whole dot to ~45% opacity, leaving the resting fill/core colour
 * underneath untouched (a dimmed `wired` port still reads "wired, just not
 * focused right now"). `hinting` wears `wired`'s own shape (hollow ring, lit
 * core) in the accent colour regardless of `state` — previewing the port
 * BECOMING wired, with a wide halo. `availability` picks between these two
 * shapes outright — see `resolveAvailabilityPaint`'s doc.
 */
export function portDotStyle({
  state = "empty",
  dimmed = false,
  hinting = false,
  availability,
  diagnostics,
  highlighterKind = DEFAULT_HIGHLIGHTER_KIND,
  variant = DEFAULT_VARIANT,
  dataType,
  typeColor,
}: PortDotPaintInput): CSSProperties {
  const effective = resolveAvailabilityPaint(availability, hinting, dimmed);
  const ringColor = portRingColor({ state, dimmed, hinting, availability, variant, dataType, typeColor });
  // `hinting` (or `availability: "available"`) renders hollow (no fill),
  // matching `wired`'s own shape on the default grammar.
  const fillColor = effective.hinting ? null : portGrammarPaint(state, variant, dataType, typeColor).fill;
  const gapPx = variant.dot.gap;
  // The drag preview rings a port one step heavier than its resting ring.
  const stateRingPx = effective.hinting ? variant.dot.ring + 1 : variant.dot.ring;

  const layers: string[] = [];
  if (ringColor != null) {
    // The card-coloured punch-out first (0 on the ring-only variants), then
    // the ring — the same two-layer recipe the fixed 2/3px rings used.
    if (gapPx > 0) layers.push(`0 0 0 ${gapPx}px var(--card)`);
    layers.push(`0 0 0 ${gapPx + stateRingPx}px ${ringColor}`);
  }
  if (effective.hinting) {
    layers.push("0 0 0 9px color-mix(in srgb, var(--bbox-primary, var(--primary)) 38%, transparent)");
  }
  // WHY APPENDED, not prepended (docs/INVALID-STATES-PLAN.md §3: "state
  // ring/fill untouched"): CSS box-shadow layers paint front-to-back in
  // list order — the FIRST layer wins any overlap. The state ring's own
  // two layers above are already opaque out to their own radius; appending
  // this translucent wash puts it strictly BEHIND them, so it can only
  // ever show in the band beyond the state ring (identical geometry to
  // `hinting`'s own halo just above — same reuse §5's Port row calls for).
  // Prepending would alpha-blend it OVER the opaque state ring instead,
  // recolouring the very fact this axis must not touch.
  // `info` paints NOTHING on a Port (§5's own table) — only error/warning
  // earn a mark, in whichever `highlighterKind` the caller asked for.
  const diagnosticSeverity = maxDiagnosticSeverity(diagnostics);
  if (diagnosticSeverity && diagnosticSeverity !== "info") {
    const color = diagnosticColorVar(diagnosticSeverity);
    if (highlighterKind === "halo") {
      layers.push(`0 0 0 9px color-mix(in srgb, ${color} 38%, transparent)`);
    } else {
      // `stroke` and `mask` are the IDENTICAL geometry on a circle
      // (HighlighterKind's own doc: the equidistant offset of a circle is
      // trivially a larger circle — there is no corner for `mask` to get
      // more right than `stroke` does). A crisp two-layer ring — a card-
      // coloured gap, then a solid line — one step further out than the
      // state ring, the SAME two-layer recipe that ring itself already
      // uses one step in.
      const gap = gapPx + stateRingPx + 2;
      layers.push(`0 0 0 ${gap}px var(--card)`);
      layers.push(`0 0 0 ${gap + 2}px ${color}`);
    }
  }

  const style: CSSProperties = {};
  // Behind a token so the sketch skin can blank the CSS rings and let the
  // drawn one (below, in `Port`) take their place. Undefined on every other
  // skin, so the `var()` fallback IS the layer list and nothing changes.
  if (layers.length > 0) style.boxShadow = `var(--bbox-skin-dot-rings, ${layers.join(", ")})`;
  // Opaque resting paint, never transparent — a wall-mounted dot straddles a
  // block's border, and a transparent interior would let it show through a
  // hollow (`empty`/`wired`) dot. `var(--card)` is the same token the 2px
  // surface ring already uses, so ring and disc read as one punch-out.
  style.background = fillColor ?? "var(--card)";
  if (effective.dimmed && !effective.hinting) style.opacity = 0.45;
  if (effective.hinting) style.transform = "scale(1.18)";
  return style;
}

/** The core's own diameter as a fraction of the dot's. */
const PORT_CORE_RATIO = 0.42;
/** Below this box the 0.42 core is a 2px speck; a half-box core (3px in
 *  the 6px default) is the smallest pinhead that still reads as "lit". */
const PORT_CORE_RATIO_SMALL = 0.5;
const PORT_CORE_SMALL_BOX_PX = 8;

export function portCoreRatio(diameterPx: number): number {
  return diameterPx <= PORT_CORE_SMALL_BOX_PX ? PORT_CORE_RATIO_SMALL : PORT_CORE_RATIO;
}

/**
 * The small inner "core" dot — the THIRD of DP - Port's three circles. On
 * the default grammar it is lit for `wired` (disc stays hollow, core lit
 * instead of a solid fill) and `received` (core matches the already-solid
 * fill, reading as "fully lit"); the reticle grammar draws it in every
 * state; the solid-disc grammars never do (the whole disc carries it).
 * `null` means no core layer at all, not a transparent one.
 * `availability: "available"` lights the core the same way `hinting` does
 * (see `resolveAvailabilityPaint`'s doc); `"unavailable"` has no core
 * treatment of its own, same as `dimmed`.
 */
export function portCoreStyle({
  state = "empty",
  hinting = false,
  availability,
  variant = DEFAULT_VARIANT,
  dataType,
  typeColor,
}: PortDotPaintInput): CSSProperties | null {
  const effectiveHinting = resolveAvailabilityPaint(availability, hinting, false).hinting;
  if (effectiveHinting) return { background: paintVar("primary") };
  const core = portGrammarPaint(state, variant, dataType, typeColor).core;
  return core == null ? null : { background: core };
}

/* ------------------------------------------------------------------ */
/* Port — the dot alone: the disc + both rings + the lit core + the    */
/* 40px hit halo. Knows nothing about labels or slots.                 */
/* ------------------------------------------------------------------ */

export interface PortProps extends ComponentProps<"span"> {
  state?: PortState;
  diameter?: PortSize;
  /** Author-set, persisted. Genuinely absent when true — `if (hidden)
   * return null`, no element, no 40px halo, no pointer events at all. Not
   * "opacity 0, still clickable" — Zach's own annotation on the sketch:
   * "Completely remove it, we don't want it to be selectable either." */
  hidden?: boolean;
  /** Host-set, never persisted — the port is out of focus, or mid-drag and
   * not a legal target. Composes OVER the resting paint (a dimmed `wired`
   * port stays legible as "wired, unfocused"), never a fifth `state`. */
  dimmed?: boolean;
  /** Host-set, never persisted — the pointer is over this port mid-drag,
   * previewing it becoming `wired`. */
  hinting?: boolean;
  /** See `PortDotPaintInput.availability`'s own doc — drag-time validity
   *  preview (ruling 5), on by default at the host level. `undefined`
   *  (no gesture) is a zero-paint-change no-op; wins over `hinting`/
   *  `dimmed` when set. Emits `data-availability`. */
  availability?: "available" | "unavailable";
  /** The diagnostic axis — see `PortDotPaintInput.diagnostics`'s own doc.
   *  Absent or `[]` paints no mark at all. Hovering the dot shows every
   *  message (`DiagnosticTooltip`, ./highlighter.tsx); there is no flag
   *  here — Port is the dot alone, and §5 puts the flag on the composites
   *  that HAVE a corner or a slot to anchor it (`LabeledPort`, `Block`). */
  diagnostics?: Diagnostic[];
  /** See `PortDotPaintInput.highlighterKind`'s own doc. */
  highlighterKind?: HighlighterKind;
  /**
   * The hit halo's diameter in the component's OWN px. Defaults to
   * `PORT_HIT_PX` (40). The constant is scene-space: under a host's
   * viewport transform it scales with zoom. A host that wants a
   * screen-constant target divides by its own zoom before passing —
   * per ARCHITECTURE.md the host owns the viewport transform, so the
   * current zoom is an input here, never something Port measures.
   */
  hitPx?: number;
  /**
   * Paint the hit halo (translucent wash + dashed outline) so the region
   * is visible. Pure paint on the EXISTING halo span — geometry and
   * hit-testing are identical with this on or off, same rule as
   * `PortEdge`'s `showCard` overlay.
   */
  showHitRegion?: boolean;
  /**
   * The visual variant (src/skin/portVariants.ts). Omit — the normal case
   * — and the document-wide `<html data-bbox-port-variant>` decides,
   * defaulting to `v1`; set it to pin THIS port (a gallery showing all
   * five at once). When `diameter` is also omitted the variant's own dot
   * diameter is used, which is how "the small pair is the default" reaches
   * every port nobody sized explicitly.
   */
  variant?: PortVariantId;
  /**
   * Host-set, never persisted — the port is the current selection. Emits
   * `data-selected`; the outline is a CSS rule in portVariants.css sized
   * by the variant. Like `dimmed`, a modifier layered over the state, never
   * a fifth `state` (DP - Port: "Hover and out-of-focus are modifiers, not
   * states").
   */
  selected?: boolean;
  /**
   * How many cables meet this port (Zach, 2026-09-19: "The port only should
   * have 1 connection point in the center. Instead you should show the
   * producer circle that has the number for the number of arrows
   * intersecting at that port"). Rendered as a small count circle riding
   * the dot when 2 or more — a lone cable is the ordinary wired look and
   * a "1" on every wired port would be noise (the original SystemSketch's
   * own rule, `bboxUi/core/port.tsx:336`, `producers >= 2`). The number is
   * fed by the host (lane `producers-count` computes it from the scene);
   * this component only draws what it is handed.
   */
  producers?: number;
  /**
   * Which side of the dot the producers circle rides — the side AWAY from
   * the label, so it never sits on the text. `LabeledPort` derives it from
   * the label's origin; a bare `Port` defaults to `right`.
   */
  producersAt?: "left" | "right";
  /** See `PortDotPaintInput.dataType` — only the by-type variants read it. */
  dataType?: string;
  /** See `PortDotPaintInput.typeColor`. */
  typeColor?: string;
}

/**
 * The dot alone. `hidden` renders NOTHING — not a fifth visual state, a
 * visibility fact (see `PortProps.hidden`'s own doc, and Port.stories.tsx's
 * `Hidden` story, which asserts the DOM node is actually gone).
 */
export function Port({
  state = "empty",
  diameter,
  hidden = false,
  dimmed = false,
  hinting = false,
  availability,
  diagnostics,
  highlighterKind = DEFAULT_HIGHLIGHTER_KIND,
  hitPx = PORT_HIT_PX,
  showHitRegion = false,
  variant: variantId,
  selected = false,
  producers,
  producersAt = "right",
  dataType,
  typeColor,
  className,
  style,
  ...props
}: PortProps) {
  // Hooks before the early return — `hidden` is a prop, not a hook order.
  const variant = usePortVariant(variantId);
  if (hidden) return null;
  const diameterPx = diameter === undefined ? variant.dot.diameter : typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  // A fixed 40px hit target regardless of the painted diameter.
  const haloInset = (diameterPx - hitPx) / 2;
  const coreStyle = portCoreStyle({ state, hinting, availability, variant, dataType, typeColor });
  const ringColor = portRingColor({ state, dimmed, hinting, availability, variant, dataType, typeColor });
  const ringExpansion = portVariantRingExpansion(variant);
  const diagnosticSeverity = maxDiagnosticSeverity(diagnostics);
  const showProducers = producers != null && producers >= 2;
  const producersOffset = showProducers ? portProducersOffsetPx(variant, producersAt) : null;
  const typePaint = portTypePaint(variant.dot.grammar, dataType, typeColor);
  return (
    // Hover -> Tooltip (message + code, no actions) is §5's interaction
    // contract for "any marked text/dot"; absent/empty `diagnostics`
    // returns `children` untouched, so a Port with no marks pays zero DOM
    // cost (see ./diagnostic.tsx's own header).
    <DiagnosticTooltip diagnostics={diagnostics}>
    <span
      data-slot="port-dot"
      data-state={state}
      data-diameter={diameter ?? diameterPx}
      data-dimmed={dimmed || undefined}
      data-hinting={hinting || undefined}
      data-selected={selected || undefined}
      data-availability={availability}
      data-diagnostic={diagnosticSeverity}
      data-highlighter-kind={diagnosticSeverity ? highlighterKind : undefined}
      // The variant this dot resolved to — the same attribute a host stamps
      // on `<html>`, republished per port so a CSS-only reader (or a
      // screenshot diff) can tell which look painted without walking up.
      {...{ [PORT_VARIANT_ATTR]: variant.id }}
      // WHY these two: docs/peps/0001-sketch-skin-at-the-boundary.md M4.
      // The dot's state rings are `box-shadow` layers, entirely OUTSIDE
      // this element's own box, so a boundary pass needs to know how far
      // out its drawn ring has to land. Before this migration that lived
      // only in `sketchAtEdge.ts`'s `ringExpansion`, which parsed this
      // element's computed `box-shadow` spreads back out — "DOM
      // archaeology" by its own header, kept only because that lane could
      // not edit this file. Now that it can, these publish the SAME two
      // numbers directly (unchanged arithmetic: the ring's own centre-line
      // sits `GAP*2 + RING*3` beyond the dot's diameter, drawn with a
      // `RING`-wide pen — now over the VARIANT's rings, `portVariantRing-
      // Expansion`, rather than fixed constants) and the parser is deleted.
      data-bbox-ring-expand={ringExpansion.expand}
      data-bbox-ring-pen={ringExpansion.pen}
      // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M7. Same gap as
      // Badge's — the edge's default seed is geometry (`${w}x${h}`), this
      // component's own is semantic (`port:${state}:${diameter}`).
      // Publishing it makes the wobble pattern match what the deleted
      // in-core `SketchOutline` call used to draw, not just its amplitude.
      data-bbox-seed={`port:${state}:${diameter ?? diameterPx}`}
      className={cn(portDotClass(), className)}
      style={{
        width: diameterPx,
        height: diameterPx,
        // The variant's numbers, published as custom properties so the
        // hover/selected/producers rules in portVariants.css (and any
        // CSS-only consumer below this element) read THIS dot's variant.
        ...portVariantVars(variant),
        // The type colour the by-type variants painted with — what the
        // langflow hover glow in portVariants.css reads.
        ...(typePaint ? ({ "--bbox-port-type-color": typePaint.disc } as CSSProperties) : null),
        ...portDotStyle({ state, dimmed, hinting, availability, diagnostics, highlighterKind, variant, dataType, typeColor }),
        // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M6. The ring's
        // colour is STATE-owned (computed above by `portRingColor`, not the
        // skin), so it is published in a channel the skin never writes,
        // rather than left for a boundary pass to read back off
        // `getComputedStyle(el).borderColor` — the sketch skin blanks that
        // to transparent on purpose (its mechanism for hiding a crisp line
        // while keeping its width), which would draw an invisible ring.
        // Naming a colour this component already computed is not a skin
        // import.
        ...({ "--bbox-ink-state": ringColor ?? undefined } as CSSProperties),
        ...style,
      }}
      {...props}
    >
      <span
        data-slot="port-dot-halo"
        aria-hidden
        className="absolute rounded-full"
        style={{
          inset: haloInset,
          // Paint-only when shown: background/outline never move geometry,
          // and the halo is the REAL hit element either way — so the drawn
          // region cannot disagree with the target it visualises.
          ...(showHitRegion
            ? { background: HIT_REGION_FILL, outline: HIT_REGION_OUTLINE, outlineOffset: -1 }
            : null),
        }}
      />
      {coreStyle && (
        <span
          data-slot="port-dot-core"
          aria-hidden
          className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full"
          style={{ width: `${portCoreRatio(diameterPx) * 100}%`, height: `${portCoreRatio(diameterPx) * 100}%`, ...coreStyle }}
        />
      )}
      {showProducers && producersOffset && (
        // The producers count circle, riding the dot up-and-outward on the
        // side away from the label, overlapping the painted ring by 2px like
        // a notification badge (geometry + WHY: `portProducersOffsetPx`).
        // Inside this span on purpose: it scales with the dot on hover and
        // dims with it, and a wire host that resolves a port by
        // `[data-slot="port-dot"]` never mistakes it for a second attach
        // point (it is `pointer-events: none` and not a dot). Paint lives in
        // portVariants.css; `data-style` picks ink vs. the original's soft
        // chip.
        <span
          data-slot="port-producers"
          data-count={producers}
          data-style={variant.producers.style}
          aria-label={`${producers} producers`}
          style={{
            left: `calc(50% + ${producersOffset.dx}px)`,
            top: `calc(50% + ${producersOffset.dy}px)`,
            transform: "translate(-50%, -50%)",
          }}
        >
          {producers}
        </span>
      )}
    </span>
    </DiagnosticTooltip>
  );
}

/**
 * src/components/portEdge.layout.ts — the pure data/math half of PortEdge,
 * ported by value from `demos/dndkit-lab/src/{types,layout,grouping}.ts`
 * and (Stage 6's new piece) `groupSyntax.ts` on the unmerged
 * `claude/dndkit-lab` branch, commit 5898ecb (docs/PORT-EDGE-PLAN.md's D2:
 * copy the lab's LOGIC as props, never merge the branch).
 *
 * Generalized in exactly one place versus the donor: `computeSlots`/
 * `buildColorMap` read the lab's fixed module-level `CARD_IDS` constant;
 * here they take the caller's own id list, since `PortEdge` has no fixed
 * card roster of its own. Everything else — `mainAxisPositions`,
 * `distributionStyle`, the grouping/clustering algorithm, the group-syntax
 * parser — is unchanged math.
 *
 * DONOR LINE NUMBERS, so a re-sync is a diff and not a search. All four
 * files read at commit 5898ecb on 2026-09-17 (`git show 5898ecb:<path>`;
 * the branch is unmerged but the commit is in this repo, so these resolve
 * offline forever):
 *
 *   • `layout.ts:39-69`   `mainAxisPositions` — byte-identical arithmetic.
 *   • `layout.ts:71-74`   `clamp`.
 *   • `grouping.ts:111-127` `computeSlots` — the one generalization above.
 *     The donor's line 121 reads `CARD_IDS.filter((cid) => ...)`; here that
 *     is `order.filter(...)`. Its third parameter is also widened, from the
 *     donor's `clustered: boolean` to this file's three-state `mode`.
 *   • `grouping.ts:129+`  `PALETTE`, and `buildColorMap` below it.
 *   • `groupSyntax.ts`    (72 lines) the whole group-syntax parser.
 *
 * PRIOR ART, for the one function here that implements a published spec
 * rather than a local convention — see `mainAxisPositions`' own docblock.
 * Everything else in this file is ad hoc: `computeSlots` is a stable
 * group-by preserving first-appearance order, and no prior art is claimed
 * for it.
 */
import type { CSSProperties } from "react";

import type { Diagnostic } from "./highlighter";
import type { PortState } from "./port";
import type { BlockSide } from "./port.layout";

/* ------------------------------------------------------------------ */
/* PortEdgeItem — moved here (W1, 2026-09-18) from portEdge.tsx so the   */
/* anchor registry below can name it in `PortLayoutFn`'s own signature   */
/* without portEdge.layout.ts importing BACK from portEdge.tsx (that     */
/* file already imports FROM this one — the reverse would be circular). */
/* portEdge.tsx re-exports this under the same name, so every existing   */
/* `import { PortEdgeItem } from "./portEdge"` call site is unaffected.  */
/* ------------------------------------------------------------------ */

/** One draggable unit on an edge. `state` defaults to `"empty"` when a
 *  caller's story never bothers to set it. */
export interface PortEdgeItem {
  id: string;
  label: string;
  state?: PortState;
  /**
   * The diagnostic axis (docs/INVALID-STATES-PLAN.md §5's PortEdge row):
   * "nothing on the rail itself" — forwarded straight to the `LabeledPort`
   * the default render draws for this item; the PORT is the subject, the
   * rail is furniture. A host's own `renderItem` override is responsible
   * for forwarding this itself if it wants the mark.
   */
  diagnostics?: Diagnostic[];
  /** Forwarded straight to the `LabeledPort` the default render draws for
   *  this item — same "nothing on the rail itself, the PORT is the
   *  subject" rule `diagnostics` follows, one row up. See
   *  `PortDotPaintInput.availability`'s own doc
   *  (docs/INVALID-STATES-PLAN.md D5, ruling 5). */
  availability?: "available" | "unavailable";
  /**
   * The port's TYPE — drawn by the default `LabeledPort` as the muted
   * secondary run after the name (lane `ports`, 2026-09-19: "label small
   * inside the row, type secondary"), and the source of the by-type
   * variants' colour. Optional: a port with no type renders the name alone.
   */
  type?: string;
  /** An explicit CSS colour for the type, winning over the palette. */
  typeColor?: string;
  /**
   * How many cables meet this port — the fan-in/fan-out count the
   * `producers-count` lane computes from the scene and the port renders
   * as a count circle riding the dot (Zach, 2026-09-19: one attach point
   * in the centre, plus "the producer circle that has the number").
   * Forwarded to the default `LabeledPort`; a host `renderItem` forwards
   * it itself, same rule as `diagnostics`.
   */
  producers?: number;
  /** Host-set selection, forwarded to the default `LabeledPort`. */
  selected?: boolean;
  /**
   * P-056. The line this port contributes to the MULTI-LINE LANE, when that
   * is not the same string as `label`. Omit — the normal case, and every
   * story on this file — and the lane shows `label`, exactly as before.
   *
   * WHY the two can differ at all, which is not obvious from inside this
   * component: a host may paint a port's line in two places with two
   * different amounts of room. SystemSketch's block rail paints only the NAME
   * HALF of `gain_x: float`, and that is a measured ruling rather than a
   * shortcut — two annotated labels flowing inward from opposite walls of a
   * 160px card overlap by 73px of unreadable text
   * (`apps/systemsketch/src/shapes/block/BlockFace.tsx`'s `labelOf`). The
   * lane is an overlay beside the rail and has the room, so it is the one
   * surface that can show — and therefore edit — the whole declaration. With
   * one field for both, typing `gain_y: int` into the lane would splice a
   * colon into a name and produce `gain_y: int: float`.
   *
   * `formatPortLane`/`reconcilePortLane` (./portLane.ts) are the only readers,
   * and they write an edited line back into whichever of the two fields the
   * item actually declared — see `withPortLaneLine` there.
   */
  laneLine?: string;
}

/* ------------------------------------------------------------------ */
/* Spacing — demos/dndkit-lab/src/types.ts + layout.ts                 */
/* ------------------------------------------------------------------ */

export type SpacingScheme = "space-between" | "space-evenly" | "space-around";

export const SPACING_SCHEMES: { value: SpacingScheme; label: string; hint: string }[] = [
  {
    value: "space-between",
    label: "Edge to edge",
    hint: "space-between — first/last card flush against the container, gaps only between cards",
  },
  {
    value: "space-evenly",
    label: "Including edge",
    hint: "space-evenly — equal gap before the first card, between cards, and after the last",
  },
  {
    value: "space-around",
    label: "Around",
    hint: "space-around — equal margin on both sides of each card, so edge gaps end up half the between-card gap",
  },
];

export type AlignAnchor = "start" | "end";

export interface DistributeConfig {
  mode: "distribute";
  scheme: SpacingScheme;
}

export interface AlignConfig {
  mode: "aligned";
  anchor: AlignAnchor;
  /** px gap between cards. */
  gap: number;
  /** Extra px pushed in from the anchor edge, on top of the container's
   *  own padding — what makes one edge's ports start further along than
   *  another's. */
  edgePadding: number;
}

/**
 * The caller places each port itself, at a main-axis offset it supplies per
 * port id. No spacing rule at all — the edge stops deciding where its dots go
 * and simply honours a number. Ported from claude/notebook-lab-work-order-472c22
 * `27b4314` (2026-09-19, "A camera for the board, and every port on the row
 * that owns it").
 *
 * WHY this exists as a third mode rather than another spacing scheme: the two
 * above answer "how do N ports share this rail's length", and there are hosts
 * for which that question is the wrong one. A notebook block is one of them —
 * a port's job there is to say WHICH ROW of code binds the name, so its
 * position is information the host already has and the rail must not
 * recompute. Under `distribute`, growing a block by Δ moves port `i` by
 * `i·Δ/(n−1)`: every port but the first, for a reason that has nothing to do
 * with the code. That makes position noise.
 *
 * `offsets` is keyed by SLOT id (a port's own id when it is ungrouped, the
 * group's id when it is not) and measured in px from the rail's CONTENT box
 * along its main axis, to the slot box's LEADING edge — the same origin and
 * the same units `mainAxisPositions` returns, so a host can compute one from
 * the other. A slot with no entry sits at 0.
 *
 * Its geometry is the registered `"anchored"` `PortLayoutFn` below — one
 * entry in the same registry every other mode resolves through, not a
 * parallel positioning path. Distinct from `mode: "custom"`, which also
 * positions absolutely: that one is a DRAG affordance (every card becomes a
 * `useDraggable`), and a host whose port positions are derived from its own
 * data wants the geometry without handing the human a way to shove a dot
 * off its row — and without dnd-kit listeners sitting on a dot a cable may
 * later need to drag from (`portEdge.tsx`'s `AnchorSlotCard` renders it
 * `fixed`). Distinct from `PortEdgeProps.anchorLayout` too: that names a
 * whole registered 2-D arrangement and keeps every card draggable; this is
 * a per-port NUMBER the host's own data already holds.
 */
export interface AnchoredConfig {
  mode: "anchored";
  offsets: Record<string, number>;
}

/** How a PortEdge lays its cards out along its main axis. `distribute` is
 *  the three space-* schemes (spreads across the whole container).
 *  `aligned` packs cards from one end with an explicit gap instead — the
 *  mode a real port edge needs, since "space-between" reflows every port's
 *  position the instant a sibling edge's count changes. `anchored` hands
 *  placement back to the caller entirely. */
export type Distribution = DistributeConfig | AlignConfig | AnchoredConfig;

export const DEFAULT_ALIGN_GAP = 18;

/**
 * Lane E → Lane D (docs/FEEDBACK-2026-09-17c-PLAN.md, Lane E's own scoping
 * note): a `PortEdge` is one edge — it has no idea which of a Block's other
 * three edges carry ports, so it cannot decide its own default
 * `Distribution`. `BlockPort` is the one component that sees all four, so
 * this is the rule IT must apply; exported here (not duplicated as a
 * literal in blockPort.tsx) so both sides read the same source of truth:
 *
 *   • any populated edge is top or bottom → EVERY edge defaults to
 *     `{ mode: "distribute", scheme: "space-around" }` — `SPACING_SCHEMES`'
 *     own "Around" entry, Zach's "Distribute and Around" wording for it.
 *   • populated edges are left/right only → EVERY edge defaults to
 *     `{ mode: "aligned", anchor: "start" }` (the classic single-port-view
 *     packing: `DEFAULT_ALIGN_GAP`, no extra edge padding).
 *   • an explicit per-edge `distribution` from the caller always wins —
 *     this function only supplies what a caller omitted.
 *
 * `mainAxisPositions`'s own `space-around` branch already centres a lone
 * item with no `count === 1` special case beyond the one CSS itself
 * requires (see that function's own docblock) — verified, not
 * re-implemented, by `PortEdge.stories.tsx`'s `EdgeDistributionControls`.
 */
// Overloads so a caller passing a literal gets the NARROW arm back. Without
// them the return is the `Distribution` union, and `BlockPort` — which
// layers its own `gap`/`edgePadding` onto the aligned arm — cannot spread the
// result without TypeScript objecting that `gap` is absent from
// `DistributeConfig`. Narrowing here keeps the one-rule seam usable instead
// of pushing every caller back to a duplicated literal.
export function defaultDistributionForEdges(hasRowEdgePopulated: true): DistributeConfig;
export function defaultDistributionForEdges(hasRowEdgePopulated: false): AlignConfig;
export function defaultDistributionForEdges(hasRowEdgePopulated: boolean): Distribution;
export function defaultDistributionForEdges(hasRowEdgePopulated: boolean): Distribution {
  return hasRowEdgePopulated
    ? { mode: "distribute", scheme: "space-around" }
    : { mode: "aligned", anchor: "start", gap: DEFAULT_ALIGN_GAP, edgePadding: 0 };
}

export interface Size {
  width: number;
  height: number;
}

// Must match the inline padding/border PortEdge's own track applies below.
export const CONTAINER_PADDING = 14;
export const CONTAINER_BORDER = 2;

/** The box a free-positioned card is actually laid out in: the padding box. */
export function innerBoxSize(size: Size): Size {
  return { width: size.width - 2 * CONTAINER_BORDER, height: size.height - 2 * CONTAINER_BORDER };
}

/**
 * Reproduces CSS flexbox `justify-content` main-axis positions, so
 * switching into free-position ("Custom") mode can snapshot exactly where
 * the browser had already placed each card — no DOM measurement needed.
 */
/**
 * Where each card's leading edge sits along the main axis. Ported from
 * `demos/dndkit-lab/src/layout.ts:39-69` @ 5898ecb, arithmetic unchanged.
 *
 * PRIOR ART — this is not invented, it is CSS Box Alignment Level 3's
 * content-distribution, reimplemented in numbers because a host that places
 * ports on a canvas needs the POSITIONS, not a flex container. Spec read
 * 2026-09-17 at https://www.w3.org/TR/css-align-3/; each branch below
 * matches its normative definition, quoted:
 *
 *   space-between — "The first alignment subject is placed flush with the
 *     start edge of the alignment container, the last alignment subject is
 *     placed flush with the end edge" → first position 0, gap free/(n-1).
 *   space-evenly  — "with a full-size space on either end … the spacing
 *     between any two adjacent alignment subjects, before the first … and
 *     after the last … is the same" → gap free/(n+1), first at gap.
 *   space-around  — "with a half-size space on either end … the spacing
 *     before the first and after the last alignment subject is half the
 *     size of the other spacing" → gap free/n, first at gap/2.
 *
 * The `count === 1` branch is the one place the spec does not decide the
 * answer for us (there is no "between" with one subject); it reproduces
 * what browsers actually do, which is the donor's own stated reason at
 * `layout.ts:49-52` — "Matches browser behaviour". Not re-measured here.
 */
export function mainAxisPositions(count: number, mainSize: number, cardMain: number, scheme: SpacingScheme): number[] {
  if (count === 0) return [];
  const free = Math.max(mainSize - count * cardMain, 0);

  if (count === 1) {
    return scheme === "space-between" ? [0] : [free / 2];
  }

  switch (scheme) {
    case "space-between": {
      const gap = free / (count - 1);
      return Array.from({ length: count }, (_, i) => i * (cardMain + gap));
    }
    case "space-evenly": {
      const gap = free / (count + 1);
      return Array.from({ length: count }, (_, i) => gap + i * (cardMain + gap));
    }
    case "space-around": {
      const gap = free / count;
      return Array.from({ length: count }, (_, i) => gap / 2 + i * (cardMain + gap));
    }
  }
}

export function clamp(value: number, min: number, max: number): number {
  if (max < min) return min;
  return Math.min(Math.max(value, min), max);
}

/**
 * The main-axis CSS for a track given its Distribution. `distribute` reuses
 * the browser's own space-* keywords. `aligned` packs from one end with a
 * real `gap`, plus — when `edgePadding` is set — extra padding on that same
 * anchor side.
 */
export function distributionStyle(axis: "row" | "column", distribution: Distribution): CSSProperties {
  // `anchored` places every slot absolutely, so the track has no flow left to
  // justify. Returning `{}` rather than throwing keeps this total over the
  // union — a caller that reads the style before checking the mode gets the
  // no-op, which is the truthful answer.
  if (distribution.mode === "anchored") return {};
  if (distribution.mode === "distribute") {
    return { justifyContent: distribution.scheme };
  }
  const style: CSSProperties = {
    justifyContent: distribution.anchor === "start" ? "flex-start" : "flex-end",
    gap: distribution.gap,
  };
  if (distribution.edgePadding > 0) {
    const prop =
      axis === "row"
        ? distribution.anchor === "start"
          ? "paddingLeft"
          : "paddingRight"
        : distribution.anchor === "start"
          ? "paddingTop"
          : "paddingBottom";
    (style as Record<string, number>)[prop] = CONTAINER_PADDING + distribution.edgePadding;
  }
  return style;
}

/**
 * Zach's rule for the "Offset" preset: the trailing edge's push-in clears
 * every leading slot AND the gap after it — `count * (slotMainPx + gap)`.
 *
 * FIXED 2026-09-17 (docs/PROPOSALS-2026-09-17.md P9a — the recorded IOU).
 * The original shipped as `count * gap`, which ignored the slots
 * themselves and under-shot by `count * slotMainPx` (72px for 3 empty
 * 24px slots at the default gap) — enough that the trailing lane's first
 * port lands INSIDE the leading lane's last slot instead of clear below
 * it, i.e. the two lanes visually interleave. `slotMainPx` has no default
 * here (unlike `blockPort.layout.ts`'s `offsetEdgePaddingPx`, which this
 * now matches formula-for-formula): this module is PortEdge's own generic
 * math and doesn't own a slot-size constant — `EMPTY_SLOT_MIN_PX` lives in
 * `portEdge.tsx`, `PORT_EDGE_SLOT_MIN_PX` in `blockPort.layout.ts` — so a
 * caller states its own slot size rather than this file guessing one.
 * Still an approximation in the one way the original docblock named and
 * this fix doesn't touch: a uniform `slotMainPx` assumes every leading
 * slot is the same size, which is only true with `showCard` off (a
 * variable-width card lane needs a caller-side sum over real slot rects,
 * not a closed form).
 *
 * `apps/storybook-basics/src/components/OffsetPaddingFor.stories.tsx`'s
 * `OverlaidOffsetLanes` story is the regression: it renders two PortEdge
 * tracks sharing one coordinate frame with this formula as the trailing
 * track's `edgePadding`, and asserts — via real `getBoundingClientRect`
 * boxes — that no trailing slot's main-axis span overlaps a leading one's.
 * Restoring the old `count * gap` turns that story red (mutation-tested;
 * see the story file's own header for the transcript).
 */
export function offsetPaddingFor(count: number, slotMainPx: number, gap: number): number {
  return Math.max(0, count) * (slotMainPx + gap);
}

/* ------------------------------------------------------------------ */
/* Anchor registry (W1, 2026-09-18) — a PortLayoutFn maps the items on   */
/* one rail to the points they sit at; a host asks for one by name       */
/* instead of switching on a closed union of arrangement kinds. Named    */
/* `Anchor`, not `PortAnchor` (docs/WORK-ORDER-2026-09-18.md, W1's own    */
/* "Naming" section): scoped to ports here, but the same idea             */
/* `blockMembers`' free/stack modes and `traceBadge`'s `{t,o}` drag        */
/* already reimplement — a name that doesn't paint itself into a ports-   */
/* only corner is what keeps a later unification cheap.                  */
/*                                                                        */
/* WHY `x`/`y` are plain numbers, not yet centred on a card (2026-09-18): */
/* a `PortLayoutFn` only ever learns `rail.mainSize`/`cardMain` along ONE */
/* axis — it has no idea how tall/wide the perpendicular axis is, so it   */
/* cannot itself compute where "centred" falls there. `axisAnchor` below  */
/* reports the plain leading-edge position (`mainAxisPositions`'s own     */
/* convention) on the rail's axis and `0` on the other; `portEdge.tsx`,   */
/* the one caller that actually knows the box's full size, is what turns  */
/* that into a real on-screen point (see its own `railAnchor` doc) — the  */
/* split that keeps a `PortLayoutFn` a pure function of a 1-D rail rather  */
/* than requiring every registrant to re-derive a 2-D box it was never    */
/* given enough information to reason about.                             */
/* ------------------------------------------------------------------ */

/** A point a layout places one member at. `side`/`angle` are not read by
 *  `PortEdge` itself — they exist for a LATER consumer of this same
 *  registry (a Block's members, a trace badge's `{t, o}` drag) that needs
 *  more than a bare point; a `PortLayoutFn` may set either, and a caller
 *  that doesn't care is free to ignore them. */
export interface Anchor {
  x: number;
  y: number;
  side?: BlockSide;
  angle?: number;
}

/** What a `PortLayoutFn` is told about the rail it's placing members on:
 *  its length along its own axis (`mainSize`), the fixed footprint every
 *  member occupies (`cardMain` — PortEdge's slots are square, so this is
 *  both dimensions of one member), which screen axis that length runs
 *  along, and the pixel gap the caller wants between members (only
 *  consulted by a layout that packs from an anchor rather than
 *  distributing across the full `mainSize`). */
export interface PortLayoutRail {
  mainSize: number;
  cardMain: number;
  axis: "row" | "column";
  gap: number;
}

/** `items` in, `Anchor[]` out, one per item, same order and length as
 *  `items`. `args` is deliberately untyped: a registrant defines its own
 *  shape (the built-ins below read an `AlignConfig` or nothing) and a
 *  caller that doesn't know a given layout's `args` shape simply omits
 *  it — this file cannot enumerate every layout that will ever register
 *  here, so it does not try to type their configs. */
export type PortLayoutFn = (items: readonly PortEdgeItem[], rail: PortLayoutRail, args?: unknown) => Anchor[];

const portLayoutRegistry = new Map<string, PortLayoutFn>();

/** Registers (or replaces) a named layout. A story or host component calls
 *  this once, at module scope, before any `<PortEdge>` asks for it by
 *  name — the same "register before use" contract a router or a command
 *  palette uses, chosen over a closed union so a NEW layout (an ellipse,
 *  an arc — see `PortEdge.AnchorLayouts.stories.tsx`) never has to touch
 *  this file to exist. */
export function registerPortLayout(name: string, fn: PortLayoutFn): void {
  portLayoutRegistry.set(name, fn);
}

/** Looks a layout up by name; `undefined` if nothing registered it. */
export function portLayout(name: string): PortLayoutFn | undefined {
  return portLayoutRegistry.get(name);
}

/** The plain leading-edge-on-this-axis, zero-on-the-other anchor every
 *  built-in linear layout below returns — see this section's own WHY for
 *  why the cross coordinate can't be anything more specific than `0` from
 *  inside a `PortLayoutFn`. */
function axisAnchor(rail: PortLayoutRail, mainPos: number): Anchor {
  return rail.axis === "row" ? { x: mainPos, y: 0 } : { x: 0, y: mainPos };
}

/** Wraps `mainAxisPositions` for one fixed `SpacingScheme` — registered
 *  three times below (once per scheme) so a caller asks for
 *  `portLayout("space-around")` etc. by the same name `SPACING_SCHEMES`
 *  already uses, rather than one layout plus a second scheme parameter a
 *  caller would have to remember to pass. */
function distributeLayout(scheme: SpacingScheme): PortLayoutFn {
  return (items, rail) => mainAxisPositions(items.length, rail.mainSize, rail.cardMain, scheme).map((pos) => axisAnchor(rail, pos));
}

for (const { value } of SPACING_SCHEMES) {
  registerPortLayout(value, distributeLayout(value));
}

/**
 * The `aligned` config as a layout: packs from `anchor` with `gap`
 * (`rail.gap`) between members, `edgePadding` pushing the WHOLE run in
 * from that same edge — arithmetic equivalent to what
 * `distributionStyle`'s `justifyContent: flex-start|flex-end` + CSS `gap`
 * + the extra `padding*` it adds already produced, restated as pixel
 * positions instead of CSS a browser resolves for us (this component no
 * longer lays these cards out as flex children — see portEdge.tsx's own
 * `PortEdgeBody`/`AnchorSlotCard` doc for why owning the pixels here is
 * what let `neutralizeScale`/comment B1 be deleted). `args` is expected
 * to be the `AlignConfig` half of the edge's own `Distribution`; a caller
 * that omits it gets the same defaults `distributionStyle` already
 * assumed (`anchor: "start"`, `DEFAULT_ALIGN_GAP`, no edge padding).
 */
registerPortLayout("aligned", (items, rail, args) => {
  const cfg = (args as AlignConfig | undefined) ?? { mode: "aligned", anchor: "start", gap: DEFAULT_ALIGN_GAP, edgePadding: 0 };
  const gap = cfg.gap;
  const pitch = rail.cardMain + gap;
  const n = items.length;
  return Array.from({ length: n }, (_, i) => {
    const mainPos =
      cfg.anchor === "start"
        ? cfg.edgePadding + i * pitch
        : rail.mainSize - cfg.edgePadding - rail.cardMain - (n - 1 - i) * pitch;
    return axisAnchor(rail, mainPos);
  });
});

/**
 * The `anchored` config (`AnchoredConfig`) as a layout: every slot sits at
 * the leading-edge offset the host supplied for its id, 0 when it supplied
 * none. `args` is the edge's own `AnchoredConfig`. Registered here — not
 * branched on inside `portEdge.tsx` — so there is ONE geometry path for
 * every mode (W1's registry) and the tentative-order preview, the grouped
 * path and the resting render all read the same answer. `rail.cardMain` is
 * never consulted, which is why a real (wider) group can come through here
 * too: the offset IS the slot's leading edge, whatever its span.
 */
registerPortLayout("anchored", (items, rail, args) => {
  const offsets = (args as AnchoredConfig | undefined)?.offsets ?? {};
  return items.map((item) => axisAnchor(rail, offsets[item.id] ?? 0));
});

/* ------------------------------------------------------------------ */
/* Grouping — demos/dndkit-lab/src/grouping.ts, generalized off the     */
/* caller's own id list instead of a fixed CARD_IDS constant.           */
/* ------------------------------------------------------------------ */

export interface GroupAssignment {
  groupId: string;
  order: number;
}

export interface GroupingSetDef {
  id: string;
  label: string;
  description: string;
  /** Deliberately partial — an id missing here is not an error. Every id
   *  still resolves to SOME group: `resolveAssignment` falls back to the
   *  id's own value (a singleton group of one). */
  assignments: Record<string, GroupAssignment>;
}

export interface Slot {
  slotId: string;
  members: { id: string; order: number }[];
}

export function resolveAssignment(id: string, set: GroupingSetDef): GroupAssignment {
  return set.assignments[id] ?? { groupId: id, order: 0 };
}

/**
 * Walks the flat id order and clusters same-group ids into one slot each,
 * positioned wherever that group's first member currently sits — the
 * mechanism that makes "move together" and drag-as-one-unit the same thing:
 * whichever slot a drag relocates carries every member with it, in BOTH
 * `"grouped"` and `"collapsed"` mode (`"off"` never clusters). What differs
 * between the two is drawn by the caller, not by this function: `"grouped"`
 * still renders every member's own port (portEdge.tsx's `SlotBody` lays
 * them out along the edge's own axis, at the SAME pitch the rest of the
 * edge uses — B5/B7), `"collapsed"` renders the whole slot as one ×N chip
 * (unchanged — B8). Keeping the CLUSTERING itself unified here is what
 * keeps "grouped members drag as a unit" true for free: it's one
 * `useSortable` id either way, so dnd-kit's own live-reorder preview never
 * has to be taught about a multi-id unit.
 */
export function computeSlots(order: string[], set: GroupingSetDef, mode: "off" | "grouped" | "collapsed"): Slot[] {
  if (mode === "off") {
    return order.map((id) => ({ slotId: id, members: [{ id, order: 0 }] }));
  }
  const seen = new Set<string>();
  const slots: Slot[] = [];
  for (const id of order) {
    const { groupId } = resolveAssignment(id, set);
    if (seen.has(groupId)) continue;
    seen.add(groupId);
    const members = order
      .filter((cid) => resolveAssignment(cid, set).groupId === groupId)
      .map((cid) => ({ id: cid, order: resolveAssignment(cid, set).order }))
      .sort((a, b) => a.order - b.order);
    slots.push({ slotId: groupId, members });
  }
  return slots;
}

/* ------------------------------------------------------------------ */
/* The overflow decision — RULING 7's "comes from the port edge         */
/* implementation" half.                                               */
/* ------------------------------------------------------------------ */

/** What a `maxVisible` cut leaves behind. Pure data: no DOM, no chrome,
 *  no wording — the caller (`editor/portOverflowChip.tsx` today) decides
 *  how, or whether, to say it. */
export interface SlotOverflow {
  /** The slots that stay on the track. */
  visible: Slot[];
  /** The slots cut from the track entirely — not grouped, not collapsed,
   *  gone. */
  hidden: Slot[];
  /** How many PORTS those cut slots held. See the WHY below for why this
   *  is not `hidden.length`. */
  hiddenPortCount: number;
}

/**
 * Split an edge's slots at `maxVisible` (undefined — the normal case —
 * cuts nothing).
 *
 * WHY: Zach, ruling 7 on the "+X more" chip — "ideally this just comes
 * from the port edge implementation... but YOu do need to provide the
 * chrome to do this... should be in bbox-editor". This function is the
 * first half of that split, and it is pure precisely so the second half
 * (the chrome, in `editor/`) can be swapped without the COUNT ever being
 * recomputed by whoever draws it. A chip that counts for itself is a
 * second source of truth for the same fact.
 *
 * WHY `hiddenPortCount` sums MEMBERS rather than counting cut slots:
 * grouping merges N ports into one slot box, so a cut landing past a real
 * group hides N ports in one slot. `hidden.length` would report "+1 more"
 * for a family of four — a false count, which
 * `feedback_truthful_property_rendering` rules out just as firmly for a
 * number as for a label.
 */
export function splitByMaxVisible(slots: Slot[], maxVisible: number | undefined): SlotOverflow {
  if (maxVisible == null) return { visible: slots, hidden: [], hiddenPortCount: 0 };
  const cut = Math.max(0, maxVisible);
  const visible = slots.slice(0, cut);
  const hidden = slots.slice(cut);
  return { visible, hidden, hiddenPortCount: hidden.reduce((n, s) => n + s.members.length, 0) };
}

/**
 * The pixel gap BETWEEN adjacent top-level slot boxes a `Distribution`
 * actually produces on the edge's main axis — the same number flexbox
 * computes via CSS `gap` (`aligned`) or `justify-content` (`distribute`),
 * derived analytically (mirrors `mainAxisPositions`'s own per-scheme math)
 * rather than measured from the DOM.
 *
 * WHY a grouped (not collapsed) slot needs this at all (B5/B7): its members
 * render side by side INSIDE one slot, at their own internal `gap` — for
 * the whole edge's port-to-port pitch to stay uniform, that internal gap
 * must equal exactly this inter-slot gap, and every slot's own main-axis
 * box (`slotMainPx`) must be the same fixed size a single-port slot uses.
 * Given both of those, the "gap between box edges" flexbox guarantees is
 * uniform is the SAME gap on both sides of a group, so port-to-port
 * distance works out uniform everywhere: between two ungrouped ports,
 * between an ungrouped port and a group's near edge, and inside the group.
 */
export function interSlotGapPx(distribution: Distribution, containerMainPx: number, slotCount: number, slotMainPx: number): number {
  // An anchored edge has no pitch: consecutive slots are wherever the caller
  // put them, and the distance between two of them is not a property of the
  // edge. 0 is the honest answer — and it is the number a GROUPED anchored
  // slot lays its own members out at, which is right, because one slot is one
  // anchor point.
  if (distribution.mode === "anchored") return 0;
  if (distribution.mode === "aligned") return distribution.gap;
  if (slotCount <= 1) return 0;
  const free = Math.max(containerMainPx - slotCount * slotMainPx, 0);
  switch (distribution.scheme) {
    case "space-between":
      return free / (slotCount - 1);
    case "space-evenly":
      return free / (slotCount + 1);
    case "space-around":
      return free / slotCount;
  }
}

export const PALETTE = [
  "#f59e0b", // amber
  "#22d3ee", // cyan
  "#a78bfa", // violet
  "#fb7185", // rose
  "#84cc16", // lime
  "#38bdf8", // sky
  "#fb923c", // orange
  "#e879f9", // fuchsia
];

/** One colour per real (>1 member) group, in first-appearance order —
 *  stable and legible, not hashed. */
export function buildColorMap(order: string[], set: GroupingSetDef): Map<string, string> {
  const sizes = new Map<string, number>();
  for (const id of order) {
    const { groupId } = resolveAssignment(id, set);
    sizes.set(groupId, (sizes.get(groupId) ?? 0) + 1);
  }
  const groupOrder: string[] = [];
  for (const id of order) {
    const { groupId } = resolveAssignment(id, set);
    if ((sizes.get(groupId) ?? 0) > 1 && !groupOrder.includes(groupId)) groupOrder.push(groupId);
  }
  const map = new Map<string, string>();
  groupOrder.forEach((groupId, i) => map.set(groupId, PALETTE[i % PALETTE.length]));
  return map;
}

/* ------------------------------------------------------------------ */
/* Group syntax — claude/dndkit-lab's groupSyntax.ts (5898ecb), net-new */
/* on that branch, ported unchanged (already generic over `knownIds`).  */
/* ------------------------------------------------------------------ */

/**
 * Zach, 2026-09-12: groups are something the EDGE assigns, not a value a
 * port carries. One textarea, one line per group, each a bracketed (or
 * bare) comma-separated list of ids: `[args,kwargs]`, `(args, kwargs)`,
 * and `args, kwargs` all parse identically. A line resolving to fewer than
 * 2 known members is dropped silently (a group of one is just an
 * ungrouped port) rather than treated as an error.
 */
const BRACKET_PAIRS: [string, string][] = [
  ["(", ")"],
  ["{", "}"],
  ["[", "]"],
];

function unwrap(line: string): string {
  for (const [open, close] of BRACKET_PAIRS) {
    if (line.startsWith(open) && line.endsWith(close)) return line.slice(1, -1);
  }
  return line;
}

export interface ParsedGroups {
  assignments: Record<string, GroupAssignment>;
  /** Ids named in the text that aren't a port on this edge — surfaced so a
   *  typo is visible, but never blocking. */
  unknownIds: string[];
}

export function parseGroupSyntax(text: string, knownIds: string[]): ParsedGroups {
  const known = new Set(knownIds);
  const assignments: Record<string, GroupAssignment> = {};
  const unknownIds: string[] = [];
  const lines = text
    .split("\n")
    .map((line) => unwrap(line.trim()).trim())
    .filter(Boolean);

  lines.forEach((line, lineIndex) => {
    const members = line
      .split(",")
      .map((m) => m.trim())
      .filter(Boolean);
    if (members.length < 2) return;
    const groupId = `g${lineIndex}`;
    members.forEach((id, order) => {
      if (!known.has(id)) {
        unknownIds.push(id);
        return;
      }
      assignments[id] = { groupId, order };
    });
  });

  return { assignments, unknownIds };
}

export function groupingSetFromText(text: string, knownIds: string[]): { set: GroupingSetDef; unknownIds: string[] } {
  const { assignments, unknownIds } = parseGroupSyntax(text, knownIds);
  return {
    set: { id: "text", label: "Text groups", description: "Typed on the edge itself.", assignments },
    unknownIds,
  };
}

/* ------------------------------------------------------------------ */
/* portConstraintOf — the ELK rung a PortEdge's own props already imply  */
/* (W1, docs/WORK-ORDER-2026-09-18.md, "Also in this lane").             */
/* ------------------------------------------------------------------ */

/**
 * Maps `PortEdge`'s existing `mode`/`freeOffsets` pair onto the one
 * distinction ELK's layout actually needs — is this rail's ORDER pinned,
 * or is each member's absolute POSITION pinned. `mode: "custom"` fixes a
 * real x/y (`freeOffsets`), and so does an `anchored` distribution (the
 * host's own `offsets`, `AnchoredConfig`); every other `"auto"` scheme
 * only ever fixes the sequence a registered `PortLayoutFn` then lays out,
 * never a literal position — so the mapping looks at `distribution` only
 * to tell `anchored` apart.
 *
 * WHY no `FREE` / `FIXED_SIDE` / `FIXED_RATIO` (do not add them):
 * bbox-ui has no representation for "ELK may put this anywhere", "pinned
 * to a side but free along it", or "pinned to a fraction of the rail" —
 * this component only ever expresses "order is fixed" or "position is
 * fixed". Reporting a rung this component cannot actually honour would
 * be a lying adapter; a coarser, TRUE rung is worth more than a precise,
 * false one.
 */
export function portConstraintOf(props: { mode?: "auto" | "custom"; distribution?: Distribution }): "FIXED_ORDER" | "FIXED_POS" {
  // An `anchored` distribution (`AnchoredConfig`) pins each port's position
  // as literally as Custom's `freeOffsets` do — the host supplied the
  // number — so it reports the same rung.
  return props.mode === "custom" || props.distribution?.mode === "anchored" ? "FIXED_POS" : "FIXED_ORDER";
}

/* ------------------------------------------------------------------ */
/* Variable-width slot packing (W1) — a real, not-collapsed GROUP is     */
/* WIDER than a single slot (`GroupSlotBody`'s own flex row: k member    */
/* boxes plus (k-1) of its own internal gap). The registry above cannot  */
/* express that: a `PortLayoutFn` only ever learns ONE uniform           */
/* `cardMain`, because `PortEdgeItem` carries no member count for it to  */
/* read one from. `portEdge.tsx` is the one caller that DOES know each   */
/* slot's real span, so it calls this — not the registry — whenever a    */
/* real group is present.                                                */
/* ------------------------------------------------------------------ */

/** A slot's real main-axis footprint: `cardMain` for an ordinary
 *  (singleton or collapsed) slot, or a real group's own row/column of
 *  `memberCount` boxes at `cardMain` plus `(memberCount - 1)` of the
 *  SAME `gap` `GroupSlotBody` lays its members out at. */
export function slotMainSpan(memberCount: number, cardMain: number, gap: number): number {
  return memberCount <= 1 ? cardMain : memberCount * cardMain + (memberCount - 1) * gap;
}

/**
 * Generalizes `mainAxisPositions`' own per-scheme leading-offset
 * convention (space-between: flush at 0; space-evenly/around: a leading
 * gap) and `aligned`'s pack-from-an-edge convention to variable spans,
 * walking slot-by-slot rather than dividing one uniform free space.
 * `gap` is the FIXED per-port pitch this file's `interSlotGapPx` already
 * derives (using the real PORT count, not the slot count) — using that
 * same fixed gap between every pair of REAL (possibly wider) slot boxes
 * is the self-consistency argument `interSlotGapPx`'s own doc proves:
 * it is the value that keeps a grouped edge's port-to-port pitch equal
 * to its own ungrouped pitch (A5's actual requirement), not merely
 * internally uniform.
 *
 * Not claimed byte-identical for a single (`spans.length <= 1`) real
 * group under a `distribute` scheme — `mainAxisPositions`' own
 * `count === 1` branch centres in the free space rather than applying a
 * leading offset, and no shipped story exercises that combination (a
 * lone real group IS a single slot, but `GroupedSpacing`, the story that
 * exercises real groups at all, always has ungrouped siblings beside
 * it) — flagged rather than silently assumed correct.
 */
export function packVariableSlotSpans(spans: number[], distribution: Exclude<Distribution, AnchoredConfig>, gap: number, mainSize: number): number[] {
  const n = spans.length;
  const positions = new Array<number>(n);
  if (distribution.mode === "aligned" && distribution.anchor === "end") {
    let cursor = mainSize - distribution.edgePadding;
    for (let i = n - 1; i >= 0; i -= 1) {
      cursor -= spans[i];
      positions[i] = cursor;
      cursor -= gap;
    }
    return positions;
  }
  const leadingOffset =
    distribution.mode === "aligned"
      ? distribution.edgePadding
      : distribution.scheme === "space-between"
        ? 0
        : distribution.scheme === "space-evenly"
          ? gap
          : gap / 2; // space-around
  let cursor = leadingOffset;
  for (let i = 0; i < n; i += 1) {
    positions[i] = cursor;
    cursor += spans[i] + gap;
  }
  return positions;
}

